-- Quiz questions v1 — 625 questions across 125 topics.
-- Generated from supabase/content/quiz-questions-v1.json. Edit that file and regenerate rather than
-- hand-patching rows here:
--
--   npm run db:seed:questions
--
-- Questions are attached by topic slug, resolved from the topic title by the
-- same slugify() the topic seed uses. A title that does not resolve fails the
-- generator rather than silently dropping the question.
--
-- Re-runnable: there is no unique key to hang `on conflict` on, so the guard is
-- per topic — a topic that already has any question is skipped whole, rather
-- than half-inserted. The subquery is evaluated against the table as it was
-- before this statement, so the rows being inserted cannot hide each other.
--
-- correct answers per question:
--   1 correct  250
--   2 correct  185
--   3 correct  190

insert into public.quiz_questions
  (topic_id, question, options, correct_indexes, explanation, sort_order)
select t.id, q.question, q.options, q.correct_indexes, q.explanation, q.sort_order
from (values
  ('dunning-kruger-effect', 'Who is most likely to badly overestimate their own skill?', '["Someone recognised at the very top of the field","Someone who has not yet touched the subject","Nobody in particular, since it varies at random","Someone with a little experience of the subject"]'::jsonb, '{3}'::smallint[], 'The effect lives in the beginner who has just enough knowledge to form opinions, not in the complete outsider who knows they know nothing. That first bit of competence is what supplies the confidence.', 0::smallint),
  ('dunning-kruger-effect', 'Why do beginners not notice how much they are missing?', '["They are usually told they are doing well by others","They cannot yet see what a good answer looks like","Judging the work needs the skill they are missing","They are naturally more arrogant than the experts"]'::jsonb, '{1,2}'::smallint[], 'Judging your own work well requires the same knowledge as doing it well, so the gap hides itself. It is not a personality trait: the same person becomes accurate about their level as soon as they learn enough to see the standard.', 1::smallint),
  ('dunning-kruger-effect', 'What often happens to self-assessment among real experts?', '["They assume what is easy for them is easy for others","They stop being able to judge work in their own field","They rate themselves lower than they really deserve","They rate themselves higher the more they have learnt"]'::jsonb, '{0,2}'::smallint[], 'Experts see the whole landscape of what they still do not know, which drags their self-rating down, and they underestimate their edge because their own skill feels ordinary to them. The popular version of the effect only tells the beginner half of the story.', 2::smallint),
  ('dunning-kruger-effect', 'What is the strongest criticism of the popular version?', '["Nearly everyone guesses they are somewhat above average","It applies mostly to people who lack any formal education","The pattern disappears once you leave the laboratory","Part of the curve shows up even in purely random data"]'::jsonb, '{0,3}'::smallint[], 'Almost everyone estimates themselves near the same middling point, so weak performers overshoot and strong performers undershoot automatically. Statisticians have shown that plotting self-rating against score produces a similar picture even from random numbers, which is why the effect is smaller than the meme suggests.', 3::smallint),
  ('dunning-kruger-effect', 'You finish a weekend crash course. What should you assume?', '["You have reached the stage where you see the gaps","Your self-assessment is at its most accurate point","Your confidence has probably run ahead of your skill","You are now able to judge other people''s work well"]'::jsonb, '{2}'::smallint[], 'A short course is exactly the position the effect describes: enough to feel capable, not enough to see the standard. The safe move is to assume your judgement of your own level is the least reliable thing you own right now.', 4::smallint),
  ('the-monty-hall-problem', 'You pick a door, the host opens another showing a goat. What holds?', '["Switching wins about two times out of three","The two closed doors are now equally likely","Your first pick was right one time in three","Staying wins about two times out of three"]'::jsonb, '{0,2}'::smallint[], 'Your first pick had a one in three chance and nothing that happened afterwards changed it, so the other two thirds are now concentrated on the single remaining door. The doors only look equal if you forget that the host was never choosing at random.', 0::smallint),
  ('the-monty-hall-problem', 'Why does the puzzle feel like a coin flip to almost everyone?', '["The host picks the door to open entirely at random","Two doors are left, so people assume equal chances","People forget that the host knew where the car was","The prize is quietly moved after the first choice"]'::jsonb, '{1,2}'::smallint[], 'The intuition counts the doors that are left instead of tracking where the probability came from. The host''s knowledge is the whole engine of the puzzle, and it is the part that quietly drops out of people''s mental picture.', 1::smallint),
  ('the-monty-hall-problem', 'What does the opened goat door tell you about your own door?', '["That the car is certainly behind the other door","That it has now climbed to a fifty per cent chance","Nothing at all that you had not already worked out","That the host was lucky in this particular round"]'::jsonb, '{2}'::smallint[], 'The host can always open a goat door regardless of your choice, so seeing one carries no news about the door you are holding. Because your door stays at one in three, the remaining door has to carry the rest.', 2::smallint),
  ('the-monty-hall-problem', 'The host forgets and opens a door at random, showing a goat. What holds?', '["Staying and switching are now equally good bets","Nothing changes here, since a goat is just a goat","The advantage came from the host''s own knowledge","Switching still wins about two times in three"]'::jsonb, '{0,2}'::smallint[], 'A random reveal that happens to miss the car eliminates the rounds where the host would have exposed it, and that rebalances the two remaining doors to fifty-fifty. This is the cleanest proof that the puzzle is about the host''s information, not about counting doors.', 3::smallint),
  ('the-monty-hall-problem', 'With 100 doors, you pick one and the host opens 98 goats. What holds?', '["Switching wins 99 times out of every hundred","The two remaining doors are now equally likely","Your first pick has improved to one chance in two","The extra doors simply cancel out the advantage"]'::jsonb, '{0}'::smallint[], 'Your original guess was right one time in a hundred and stays there, so virtually all the probability piles onto the one door the host deliberately left closed. Scaling the puzzle up is the fastest way to feel why switching wins.', 4::smallint),
  ('the-birthday-paradox', 'In a room of 23 people, how likely is a shared birthday?', '["Around one in sixteen, so quite unlikely","About six per cent, so it rarely happens","Roughly 23 in 365, the obvious ratio","Just over half, more likely than not"]'::jsonb, '{3}'::smallint[], 'It crosses fifty per cent at 23 people, which is why the result feels wrong. The tempting answer of 23 out of 365 comes from comparing people to days instead of people to each other.', 0::smallint),
  ('the-birthday-paradox', 'Why does 23 feel far too small a number?', '["23 people already make 253 possible pairs of people","People picture themselves against the other 22 alone","Leap years quietly distort the whole calculation","Birthdays are not spread out evenly across the calendar"]'::jsonb, '{0,1}'::smallint[], 'The question is about any two people matching, but intuition silently rewrites it as a question about you. Counting pairs instead of people shows where the chances come from, and pairs grow much faster than the group does.', 1::smallint),
  ('the-birthday-paradox', 'Roughly how many people are needed before a match is near certain?', '["About 183, which is half the calendar year","Close to 365, roughly one person per day","About 57, far fewer than most people expect","About 300, most of the days in the year"]'::jsonb, '{2}'::smallint[], 'At around 57 people the probability is already above 99 per cent, long before the group approaches the number of days. Half the year sounds like the natural halfway mark, but that intuition again counts days rather than pairs.', 2::smallint),
  ('the-birthday-paradox', 'How large must the group be for someone to share YOUR birthday?', '["About 57, the same as for a shared match","About 100, which is already a big enough room","Still around 23, just as for a random pair","Around 253, far more than for a random pair"]'::jsonb, '{3}'::smallint[], 'Fixing one specific birthday removes almost all the pairs, and you need roughly 253 people before a match with you is more likely than not. The gap between 23 and 253 is exactly the difference the paradox is built on.', 3::smallint),
  ('the-birthday-paradox', 'What makes everyday coincidences feel rarer than they are?', '["We ask about a specific match, not about any match","Coincidences really are rare even in large groups","The number of possible combinations grows very fast","Random events tend to spread themselves out evenly"]'::jsonb, '{0,2}'::smallint[], 'Both correct answers are the same mistake seen from two sides: we underrate how many opportunities for a match exist. Once you count the combinations rather than the participants, most striking coincidences stop being surprising.', 4::smallint),
  ('the-bystander-effect', 'A person collapses in a crowded station. What does research suggest?', '["The chance that any single person helps drops","People in crowds care less about total strangers","Everyone assumes somebody else is handling it","A crowd reacts faster because more people see it"]'::jsonb, '{0,2}'::smallint[], 'Responsibility gets divided among everyone present, so each individual feels less of it. It is not coldness: the same people help readily when they are the only witness.', 0::smallint),
  ('the-bystander-effect', 'Besides divided responsibility, what keeps people from acting?', '["Nobody else looks alarmed, so it must be fine","Fear of overreacting in front of other people","Crowds physically block access to the victim","Most people fail to notice an emergency at first"]'::jsonb, '{0,1}'::smallint[], 'People read the calm faces around them as evidence that nothing is wrong, and everyone is doing the same reading at once. Add the embarrassment of being the one who made a scene, and inaction becomes the default.', 1::smallint),
  ('the-bystander-effect', 'What is the recommended way to break the effect as a victim?', '["Ask the entire crowd for help in one shout","Point at one person and give them a task","Wait until someone steps forward by themselves","Shout louder so that more people hear you"]'::jsonb, '{1}'::smallint[], 'Naming one person destroys the diffusion by handing them undivided responsibility. Addressing the crowd, however loudly, leaves the responsibility spread out exactly as it was.', 2::smallint),
  ('the-bystander-effect', 'What do more recent studies of real emergencies show?', '["The effect disappears entirely outside the laboratory","In most filmed street conflicts, someone intervenes","Larger groups make intervention more likely overall","Trained professionals are the people who step in"]'::jsonb, '{1,2}'::smallint[], 'Video studies of genuine street incidents found bystanders intervening in the large majority of cases, and more people present meant a better chance that at least one of them acted. The effect is real for any given individual, but that is not the same as nobody helping.', 3::smallint),
  ('the-bystander-effect', 'When is the effect weakest?', '["When nobody present has any first aid training","When the crowd is unusually large and dense","When the danger is obvious and quite unambiguous","When bystanders are strangers to one another"]'::jsonb, '{2}'::smallint[], 'Ambiguity is what feeds the effect, so an unmistakable emergency removes most of it. Anonymity works the other way: people who know each other help more readily, not less.', 4::smallint),
  ('sunk-cost-fallacy', 'What makes a cost ''sunk'' in the sense that matters here?', '["It was spent on something that has since failed","It cannot be recovered whatever you decide next","It is usually large compared with the whole budget","It was paid out before the project even began"]'::jsonb, '{1}'::smallint[], 'The defining feature is irrecoverability, not size or timing. If the money comes back when you quit, it is not sunk and it does belong in the decision.', 0::smallint),
  ('sunk-cost-fallacy', 'You are an hour into a bad film you paid for. What is rational?', '["Stay, to be fair to the money you already spent","Leave, since only the remaining time is still yours","Stay, or the price of the ticket is simply thrown away","The ticket price should not enter into the decision"]'::jsonb, '{1,3}'::smallint[], 'The money is gone in both branches, so it cannot favour one over the other; only the next ninety minutes differ. The feeling that leaving ''wastes'' the ticket is the fallacy itself, since staying wastes the ticket plus your evening.', 1::smallint),
  ('sunk-cost-fallacy', 'Why is the pull so hard to resist?', '["People are simply not very good at doing arithmetic","The original cost can usually be recovered later","Losses hurt more than equivalent gains please us","Quitting feels like admitting the choice was wrong"]'::jsonb, '{2,3}'::smallint[], 'Both correct answers are about how ending the project forces you to book the loss, which loss aversion makes disproportionately painful. Continuing lets you keep the loss theoretical for a while longer.', 2::smallint),
  ('sunk-cost-fallacy', 'When is it right to carry on with a project you have poured money into?', '["When the project is already more than half finished","When the remaining work still pays for itself well","When the amount already spent is extremely large","When quitting would badly embarrass the whole team"]'::jsonb, '{1}'::smallint[], 'The only valid test is forward-looking: does the remaining work pay for itself. How far along you are is just another way of stating what you have already spent, which is exactly the number that must not count.', 3::smallint),
  ('sunk-cost-fallacy', 'Two years into a degree you no longer want. What follows here?', '["Finishing costs less than starting again elsewhere","The two years already spent are a reason to finish","The two years are gone whichever way you choose","Only the value of the years remaining now matters"]'::jsonb, '{2,3}'::smallint[], 'The finished years are unrecoverable and identical in both futures, so they cannot tip the balance. Finishing may still be right, but only if the remaining years are worth their cost on their own terms.', 4::smallint),
  ('confirmation-bias', 'What is the core of the bias?', '["We refuse to change our minds when proven wrong","We seek and weigh evidence that fits our beliefs","We deliberately ignore any facts that we dislike","We read mainly the sources we already agree with"]'::jsonb, '{1}'::smallint[], 'The bias steers where you look and how hard you scrutinise what you find, which is why it survives good intentions. Deliberate suppression is a different thing: confirmation bias is mostly invisible to the person doing it.', 0::smallint),
  ('confirmation-bias', 'Which behaviour would actually test a belief rather than confirm it?', '["Collecting many further cases that fit the rule","Checking whether the rule has ever been popular","Deliberately hunting for a case that would break it","Asking someone who already agrees whether it holds"]'::jsonb, '{2}'::smallint[], 'A belief is only tested by evidence that could have refuted it, so the useful question is what would prove you wrong. Piling up supporting cases feels like research but cannot change the conclusion.', 1::smallint),
  ('confirmation-bias', 'Why does more information often harden disagreement?', '["Both sides find plenty of material that supports them","The truth becomes harder to define with more data","Extra information makes people forget the whole question","Each side reads the other''s evidence more critically"]'::jsonb, '{0,3}'::smallint[], 'A large body of evidence gives everyone material to select from, and scrutiny is applied unevenly: friendly evidence gets a pass, hostile evidence gets audited. That asymmetry is why the same dataset can push two people further apart.', 2::smallint),
  ('confirmation-bias', 'How does the bias show up in a debugging session?', '["You cannot see the error message in front of you","You read the log for lines that match your theory","You test the hypothesis you already prefer first","You assume the bug must be in someone else''s code"]'::jsonb, '{1,2}'::smallint[], 'The bias does not blind you to data, it steers which data you go and fetch. Scanning a log for confirmation of your theory is the everyday form of it, and it is why a bug can hide in plain sight for hours.', 3::smallint),
  ('confirmation-bias', 'What genuinely reduces the bias?', '["Simply being told that the bias exists in people","Having someone whose job is to argue the other side","Spending considerably more time on the question","Writing down in advance what would change your mind"]'::jsonb, '{1,3}'::smallint[], 'Both working countermeasures make the disconfirming case someone''s explicit responsibility, before or beside you. Merely knowing about the bias barely helps, which is the uncomfortable finding in this whole area.', 4::smallint),
  ('the-halo-effect', 'What does the halo effect describe?', '["One good trait colours judgements of unrelated traits","Attractive defendants get lighter sentences on average","First impressions are formed within the first few seconds","We tend to copy the opinions of attractive people"]'::jsonb, '{0,1}'::smallint[], 'A single salient positive quality spills over into ratings of things it has nothing to do with, and courtroom studies are one of the clearest measured consequences. Speed of first impressions is a separate phenomenon and does not by itself involve the spillover.', 0::smallint),
  ('the-halo-effect', 'A well-designed product feels more reliable. What does this show?', '["Design quality is a good proxy for real reliability","Careful design really does predict reliability well","Appearance is transferring to an unrelated judgement","Users cannot assess reliability without testing it"]'::jsonb, '{2}'::smallint[], 'Beauty and reliability are separate properties, and the first is quietly standing in for the second. Treating looks as a deliberate proxy would at least be a reasoned choice; the halo happens without any reasoning at all.', 1::smallint),
  ('the-halo-effect', 'What is the mirror image of the effect called and what does it do?', '["The horn effect, where one flaw drags everything down","The contrast effect, where nearby items shift ratings","The nocebo effect, where expectations turn negative","The recency effect, where the last impression wins"]'::jsonb, '{0}'::smallint[], 'The same mechanism runs in reverse: one bad trait makes people rate unrelated qualities worse. The other three are real effects, but none of them is a single trait bleeding into unrelated judgements.', 2::smallint),
  ('the-halo-effect', 'How can a hiring process reduce the effect?', '["Let the panel discuss impressions before scoring","Have interviewers meet the candidate for longer","Assess anonymised work samples before meeting","Rate each criterion separately, then form a view"]'::jsonb, '{2,3}'::smallint[], 'Both fixes cut the channel the halo travels through, by separating the judgements or removing the person from the first assessment. Longer contact and group discussion tend to spread one strong impression rather than dilute it.', 3::smallint),
  ('the-halo-effect', 'Why is the effect so hard to catch in yourself?', '["It affects the people who are unaware of it happening","It requires strong feelings before it can occur","You experience the judgement as an independent one","The transfer happens before you form the opinion"]'::jsonb, '{2,3}'::smallint[], 'By the time the assessment reaches consciousness it already feels like your own reasoned view of that specific trait. Knowing about the effect does not stop it, which is why structural fixes beat good intentions.', 4::smallint),
  ('placebo-and-nocebo', 'What does the nocebo effect describe?', '["A treatment that works for firm believers alone","A drug that loses its effect after repeated use","A treatment that works better when it is expected","Expecting harm is enough to produce real symptoms"]'::jsonb, '{3}'::smallint[], 'Nocebo is the negative twin of placebo: the expectation of harm produces real symptoms. Improvement driven by positive expectation is the placebo side, which is why the two are so often confused.', 0::smallint),
  ('placebo-and-nocebo', 'What is true of placebo responses?', '["They involve measurable changes inside the body","They show mainly in reported symptoms like pain","They shrink tumours as reliably as they ease pain","They occur in the people who are easily suggestible"]'::jsonb, '{0,1}'::smallint[], 'Placebo can shift real physiology, including endorphin release, but its reach is strongest on subjective experience such as pain, nausea and fatigue. It does not cure the underlying disease, which is the most common overstatement of the idea.', 1::smallint),
  ('placebo-and-nocebo', 'Why do drug trials use a placebo group at all?', '["To give the control group something harmless to take","To separate the drug''s effect from expectation and time","To keep patients from knowing they are being studied","To measure how strong the placebo effect really is"]'::jsonb, '{1}'::smallint[], 'Without a comparison arm you cannot tell the drug apart from expectation, natural recovery and regression to the mean. Measuring placebo strength is a by-product, not the reason the design exists.', 2::smallint),
  ('placebo-and-nocebo', 'What happened in trials where patients knew the pill was inert?', '["Symptoms got worse because the trust had been broken","Nothing measurable happened without the deception","Some patients still reported a clear improvement","The effect appeared, but weaker than with deception"]'::jsonb, '{2,3}'::smallint[], 'Open-label placebo studies found real, if reduced, symptom improvement even when patients were told exactly what they were taking. That is awkward for the simple story that the effect is pure belief in a treatment.', 3::smallint),
  ('placebo-and-nocebo', 'A doctor lists rare side effects in detail. What is a likely consequence?', '["Some patients stop the treatment because of them","Patients tolerate the drug better, being forewarned","The drug itself becomes chemically less effective","More patients report exactly those side effects"]'::jsonb, '{0,3}'::smallint[], 'Naming symptoms makes patients notice and attribute them, which drives both reporting and dropout. This is the practical dilemma of nocebo: honest information can itself cause harm, and chemistry has nothing to do with it.', 4::smallint),
  ('the-cocktail-party-effect', 'What does the cocktail party effect describe?', '["Hearing more sharply after drinking alcohol","Losing the thread of a conversation in the noise","Your name cutting through speech you ignored","Focusing on a single voice among many at once"]'::jsonb, '{2,3}'::smallint[], 'The term covers both halves of the same trick: the ability to lock onto one speaker in a crowd, and the fact that certain words still get through from the streams you are not attending to. Both point to filtering that never fully switches the rest off.', 0::smallint),
  ('the-cocktail-party-effect', 'What does the name effect imply about unattended sound?', '["It is detected when the room happens to be quiet","It is discarded before any meaning is extracted","It is processed enough for meaning to be checked","It is stored word for word for several minutes"]'::jsonb, '{2}'::smallint[], 'If ignored speech were thrown away at the level of raw sound, your name could never break through, so some meaning must be analysed before the filter. That finding is what forced early models of attention to be rewritten.', 1::smallint),
  ('the-cocktail-party-effect', 'What helps you separate one speaker from a noisy background?', '["Differences in pitch between the two voices","Raising the overall volume of the whole room","Watching the speaker''s mouth as it moves","The tiny time difference between your two ears"]'::jsonb, '{0,2,3}'::smallint[], 'Your brain uses spatial cues from two ears, visual lip information, and voice characteristics like pitch to pull one stream out of the mixture. Raising the overall level lifts the target and the noise equally, which is why it does not help.', 2::smallint),
  ('the-cocktail-party-effect', 'Why do hearing aids struggle in exactly this situation?', '["They amplify all sound rather than selecting a source","They are simply not loud enough for very crowded rooms","Users lose interest in following a conversation","They filter out background noise too aggressively"]'::jsonb, '{0}'::smallint[], 'The device boosts the whole mixture instead of reconstructing the scene, which is exactly the problem loudness never solved. Aggressive noise filtering is what modern aids attempt as a fix, not the cause of the failure.', 3::smallint),
  ('the-cocktail-party-effect', 'You hear your name and ''remember'' the sentence before it. What is true?', '["You had been consciously attending the whole time","Unattended speech is recorded in full for recall","A short raw trace of recent sound stays available","Your memory is partly reconstructed after the fact"]'::jsonb, '{2,3}'::smallint[], 'A brief echoic store keeps the last seconds of sound, so attention can be turned back on it, and the rest is filled in from context. It is not a recording, and it is not evidence that you were listening the whole time.', 4::smallint),
  ('the-spotlight-effect', 'What does the spotlight effect describe?', '["We become clumsier when we know we are watched","We remember our own embarrassment very vividly","We notice other people''s mistakes before our own","We overestimate how much other people notice us"]'::jsonb, '{3}'::smallint[], 'The effect is a mismatch between how salient you are to yourself and how salient you are to anyone else. What other people notice about each other is a separate question and is not what the spotlight describes.', 0::smallint),
  ('the-spotlight-effect', 'Why do we make this mistake so consistently?', '["Social groups can really watch newcomers closely","Other people are busy monitoring themselves too","We are unusually self-critical as a whole species","We cannot ever fully leave our own point of view"]'::jsonb, '{1,3}'::smallint[], 'You are the permanent centre of your own experience and cannot subtract that when guessing what others perceive, and everyone around you is running the same private spotlight. Both correct answers describe the same asymmetry from either end.', 1::smallint),
  ('the-spotlight-effect', 'Students wore an embarrassing T-shirt into a room. What was found?', '["Roughly twice as many noticed as wearers expected","Almost everyone in the room could name the shirt","Wearers expected far more people to notice than did","The wearers'' estimates matched reality quite closely"]'::jsonb, '{2}'::smallint[], 'In the classic study the wearers predicted about half the room would notice, while roughly a quarter actually did. The gap, not the absolute number, is the finding.', 2::smallint),
  ('the-spotlight-effect', 'What follows for someone dreading a small public mistake?', '["The audience was mostly thinking about themselves","Nobody in the room registered the smallest detail","You should avoid such situations until you feel ready","Others noticed less than you think and forgot faster"]'::jsonb, '{0,3}'::smallint[], 'The realistic correction is that the audience registered less and moved on sooner, not that the world is blind. Overcorrecting into ''nobody saw anything'' is a different false belief, and avoidance keeps the fear intact.', 3::smallint),
  ('the-spotlight-effect', 'Where does the same bias appear beyond appearance?', '["Assuming your good work is being noticed as well","Assuming other people know that you dislike them","Assuming your nervousness is obvious to the room","Assuming an audience recalls your talk word for word"]'::jsonb, '{0,1,2}'::smallint[], 'The bias runs on internal states as well as visible ones and it is not only about the negative: your effort and quality go unnoticed for the same reason your stains do. The one about word-for-word recall is a claim about memory, not about how visible you are.', 4::smallint),
  ('survivorship-bias', 'Returning bombers had holes in the wings. Where should armour go?', '["On the engines and cockpit, which came back clean","Wherever the recorded damage was found most frequently","Spread evenly across the entire aircraft frame","On the wings, where the damage clearly shows"]'::jsonb, '{0}'::smallint[], 'The sample only contains aircraft that made it home, so the untouched areas are where a hit stopped a plane returning. Frequency of damage in the survivors measures survivable hits, which is precisely the wrong thing to armour.', 0::smallint),
  ('survivorship-bias', 'What is wrong with studying only successful companies for lessons?', '["The failures may well have done the same things","Success stories are usually exaggerated afterwards","Successful companies are too rare to study well","The sample cannot show which habits really mattered"]'::jsonb, '{0,3}'::smallint[], 'Without the failures you cannot tell a cause of success from something common to everyone who tried. Exaggeration is a real problem too, but it is a separate one: even perfectly honest accounts of winners would still mislead.', 1::smallint),
  ('survivorship-bias', 'Why does ''they built things to last back then'' usually fail as evidence?', '["Old materials were genuinely far more durable","Only the well-built examples are still standing","Records from the period are quite unreliable","Modern buildings are built to much lower standards"]'::jsonb, '{1}'::smallint[], 'The surviving buildings are a filtered sample rather than a random one, so they show you the best of the era, not the average. The same filter will one day make our own century look impeccably built.', 2::smallint),
  ('survivorship-bias', 'Which of these is a case of the same bias?', '["Judging fund managers by those still in business","Judging a course by the salaries of its graduates","Judging a diet by the people who stayed on it","Judging a drug by those who dropped out of its trial"]'::jsonb, '{0,1,2}'::smallint[], 'Each of these quietly deletes the cases that failed, quit or closed before the measurement. Looking at the dropouts is the opposite move: it is precisely the correction the bias calls for.', 3::smallint),
  ('survivorship-bias', 'What is the general fix?', '["Ask what was removed from the sample before you saw","Find the population the survivors were drawn from","Weight recent cases more heavily than older ones","Collect a much larger sample of the successes"]'::jsonb, '{0,1}'::smallint[], 'The bias is a property of how the data reached you, so more of the same filtered data does not help. Both correct answers describe reconstructing the denominator that the filter removed.', 4::smallint),
  ('anchoring', 'What does anchoring describe?', '["The effect works with plausible, realistic numbers","A first number pulls later estimates towards it","People stick to opinions they have stated publicly","Negotiators lose ground when they speak first"]'::jsonb, '{1}'::smallint[], 'An initial value becomes the starting point that all later adjustment works from. The unsettling part is that the anchor does not need to be plausible or even relevant, which is what the wheel-of-fortune experiments showed.', 0::smallint),
  ('anchoring', 'Participants spun a wheel, then estimated a percentage. What happened?', '["The wheel result clearly shifted their estimates","Participants who trusted the wheel were most affected","The effect held though the spin was visibly random","They ignored the number they knew to be random"]'::jsonb, '{0,2}'::smallint[], 'Estimates followed the wheel even though everyone had watched it being spun at random. That is the key demonstration: the anchor does not need to carry any information to move you.', 1::smallint),
  ('anchoring', 'Why is opening high often effective in a negotiation?', '["The other side adjusts from your number, not theirs","It sets the range the whole conversation happens in","It signals genuine confidence to the other side","It shortens the whole negotiation considerably"]'::jsonb, '{0,1}'::smallint[], 'The first offer defines the scale everyone then argues within, and adjustments from an anchor are typically too small. Confidence signalling may happen as well, but it is not the anchoring mechanism.', 2::smallint),
  ('anchoring', 'Where do shops use anchoring on you deliberately?', '["A very expensive item placed near mid-range ones","A sign reading ''limit 6 per customer'' on a shelf","A crossed-out original price beside the new one","Loyalty points awarded once the purchase is made"]'::jsonb, '{0,1,2}'::smallint[], 'Struck-through prices, a costly item that makes others look reasonable, and a purchase limit all plant a number before you decide. Points awarded afterwards cannot anchor the decision because they arrive after it.', 3::smallint),
  ('anchoring', 'What actually reduces anchoring?', '["Generating your own estimate before hearing theirs","Taking considerably more time over the decision","Knowing that the anchor is completely arbitrary","Rounding the anchor to a simpler number in advance"]'::jsonb, '{0}'::smallint[], 'Producing your own estimate before the other side names one gives you something to adjust from that is not theirs. Awareness, extra time and tidying up their number all leave the anchor doing its work.', 4::smallint),
  ('the-zeigarnik-effect', 'What did Zeigarnik observe about waiters and orders?', '["They memorised the orders using visual memory tricks","They remembered the largest orders far better","Completed orders faded from memory very quickly","They recalled unpaid orders better than settled"]'::jsonb, '{2,3}'::smallint[], 'The unfinished task stayed accessible and the finished one was released, which is the whole effect in one observation. Size of the order and memory technique were not what distinguished the two groups.', 0::smallint),
  ('the-zeigarnik-effect', 'What best explains why unfinished tasks stay in mind?', '["Unfinished work is usually more emotionally charged","People feel guilty about what they have not done","Unfinished tasks are rehearsed out loud more often","The brain marks the task as still needing resources"]'::jsonb, '{3}'::smallint[], 'An open goal keeps a claim on attention until it is closed, as though the task were still holding resources. Guilt and emotional weight often come along, but the effect shows up for entirely trivial tasks too.', 1::smallint),
  ('the-zeigarnik-effect', 'How do serial dramas exploit this?', '["They leave a question open instead of answering it","They recap the previous episode at the very start","They end each episode in the middle of a scene","They release episodes weekly rather than at once"]'::jsonb, '{0,2}'::smallint[], 'A cliffhanger is an artificially unclosed goal, and it keeps working on you between episodes. Recaps and release schedules affect memory and habit, but they close nothing and open nothing.', 2::smallint),
  ('the-zeigarnik-effect', 'You cannot stop thinking about an unstarted task. What helps?', '["Waiting until the thought fades away on its own","Writing down a concrete plan for tackling it","Deciding that the task does not really matter","Starting on it for just a few short minutes"]'::jsonb, '{1,3}'::smallint[], 'Studies found that making a specific plan quiets the intrusion almost as well as finishing, because the goal is handed off rather than left hanging. Simply willing yourself to stop caring does not close the loop, which is why the thought returns.', 3::smallint),
  ('the-zeigarnik-effect', 'What is a practical use for writing rather than for procrastination?', '["Writing a summary of what you did before stopping","Finishing each section completely before you stop","Leaving the next step half-done quite on purpose","Working in blocks that end with a finished section"]'::jsonb, '{2}'::smallint[], 'An open loop pulls you back, so deliberately leaving the next step half-done makes the following session start itself. Tidily wrapping up removes exactly that pull, which is why a neat stopping point is so hard to return from.', 4::smallint),
  ('the-hedonic-treadmill', 'What does the hedonic treadmill describe?', '["Happiness is fixed from birth and stays there","Good events stop feeling good almost immediately","Happiness declines steadily as a life goes on","Happiness returns towards a personal baseline"]'::jsonb, '{3}'::smallint[], 'The pattern is a drift back towards your own set point after both good and bad events. It is not a downward slide, and it is not instant: adaptation takes months or years, and it is never quite total.', 0::smallint),
  ('the-hedonic-treadmill', 'What did the study of lottery winners and accident victims suggest?', '["Winners ended up permanently far happier than before","Neither group''s happiness shifted at any later point","Both groups drifted back towards their earlier level","Adaptation was less complete for the injured group"]'::jsonb, '{2,3}'::smallint[], 'The famous finding was substantial adaptation on both sides, but it was never total, and later work found some losses that people never fully adapt to. That asymmetry is the part the popular version drops.', 1::smallint),
  ('the-hedonic-treadmill', 'Which change tends to leave the least lasting effect on wellbeing?', '["Moving to a warmer and much sunnier country","Buying a noticeably better and faster car","A pay rise matched by those around you","A long spell out of work and being unemployed"]'::jsonb, '{0,1,2}'::smallint[], 'Income relative to your reference group, climate and possessions are the classic examples of things people adapt to quickly. Long-term unemployment is one of the documented exceptions, where the baseline itself seems to shift down.', 2::smallint),
  ('the-hedonic-treadmill', 'What follows for how to spend money, according to this line of research?', '["Bigger purchases produce proportionally bigger gains","No purchase makes any real difference to happiness","Spending on other people lasts longer than on yourself","Rare luxuries resist adaptation better than daily ones"]'::jsonb, '{2}'::smallint[], 'Money spent on other people shows unusually durable effects, because the returns live in relationships rather than in your flat. Price and rarity do not protect a purchase from adaptation; a more expensive object is adapted to just as thoroughly.', 3::smallint),
  ('the-hedonic-treadmill', 'Why does the next goal never deliver what it promises?', '["The particular goal was simply the wrong one to pick","Your comparison point moves up with your circumstances","Anticipation feels more pleasant than the arrival","You forecast the new state using today''s expectations"]'::jsonb, '{1,3}'::smallint[], 'You predict the future from where you stand now, but by the time you arrive, the standard has moved with you. That is why replacing the goal with a better one does not break the pattern.', 4::smallint),
  ('the-prisoners-dilemma', 'Why do both prisoners betray, even though both would prefer silence?', '["Betraying is better whatever the other one does","Silence carries a heavier sentence than betrayal","They cannot trust the promises the other makes","Betraying gives them the highest possible payoff"]'::jsonb, '{0}'::smallint[], 'Defection pays more against a silent partner and against a betraying one, so each player reaches it independently. Mutual silence is in fact the better joint outcome, which is precisely why the result is a dilemma.', 0::smallint),
  ('the-prisoners-dilemma', 'What makes it a dilemma rather than merely a bad outcome?', '["Self-interest cannot reach the best joint outcome","The players are not allowed to talk to each other","Neither player can predict what the other will do","One player ends up much worse off than the other"]'::jsonb, '{0}'::smallint[], 'The sting is that the best joint outcome is unreachable by two people each doing what is rational for them. Uncertainty makes the story vivid but is not required: the arithmetic is unchanged even if each knows exactly what the other will choose.', 1::smallint),
  ('the-prisoners-dilemma', 'What changes when the game is played repeatedly with the same partner?', '["Defection can no longer be chosen by either of the two","The final round still pushes towards betrayal","Cooperation becomes the stable strategy over time","Today''s betrayal can be punished in the next round"]'::jsonb, '{1,2,3}'::smallint[], 'Repetition adds a future that makes retaliation possible, which is what lets cooperation survive. Defection remains available throughout, and a known last round removes the shadow of the future, which is why endgames get ugly.', 2::smallint),
  ('the-prisoners-dilemma', 'Which real situation has the same structure?', '["Two friends choosing which film they will watch","Two shops deciding whether to undercut each other","Two countries deciding whether to build weapons","Two fleets overfishing a shared stock of fish"]'::jsonb, '{1,2,3}'::smallint[], 'Each of the three has a move that pays off individually and ruins the shared outcome when everyone makes it. Choosing a film is a coordination problem: there is no gain from defecting, only from agreeing.', 3::smallint),
  ('the-prisoners-dilemma', 'Why did tit-for-tat do so well in Axelrod''s tournaments?', '["It was simple enough for opponents to read","It exploited weak opponents for maximum points","It retaliated at once and then forgave quickly","It never once defected before its opponent"]'::jsonb, '{0,2,3}'::smallint[], 'It was nice, provokable, forgiving and legible, which let it build cooperation with anyone willing while refusing to be farmed. It never beat any single opponent, which is the counterintuitive part: it won the tournament without ever winning a match.', 4::smallint),
  ('simpsons-paradox', 'What is Simpson''s paradox?', '["A trend in each subgroup reverses once combined","A correlation that is really a pure coincidence","A trend that disappears as the sample gets larger","A result that fails to replicate in a new study"]'::jsonb, '{0}'::smallint[], 'The paradox is a genuine reversal between the subgroup view and the combined view, with every number correct. It is not noise washing out with more data, which is what makes it so much more dangerous than a fluke.', 0::smallint),
  ('simpsons-paradox', 'Berkeley seemed to favour men overall but not per department. Why?', '["Women applied more to departments with low rates","Individual departments were quietly discriminating anyway","The overall figure mixed departments of varying rates","The overall figure had simply been miscalculated"]'::jsonb, '{0,2}'::smallint[], 'Application patterns differed across departments whose admission rates differed, so the pooled number reflected where people applied rather than how they were treated. Nothing was miscalculated, which is why the case is famous.', 1::smallint),
  ('simpsons-paradox', 'Which view should you trust when the two disagree?', '["The aggregate figure, since it rests on more data","Whichever grouping reflects how the outcome is caused","Neither view, because the data cannot be trusted","The subgroups, since they are far more detailed"]'::jsonb, '{1}'::smallint[], 'There is no purely statistical rule; you have to know what causes what before deciding which split is meaningful. That is why the paradox is really an argument about causation wearing a statistical costume.', 2::smallint),
  ('simpsons-paradox', 'Treatment A beats B for small stones and for large ones. What holds?', '["One of the two subgroup results has to be mistaken","A must therefore also be the better one overall","A still looks worse in the combined figures","The overall figure reflects which cases each got"]'::jsonb, '{2,3}'::smallint[], 'If the better treatment is used on the harder cases, its overall success rate can fall below the weaker one. Both subgroup results stay true, which is exactly what makes the aggregate misleading here.', 3::smallint),
  ('simpsons-paradox', 'What practical habit protects you from the paradox?', '["Preferring much larger datasets to smaller ones","Recomputing the average as a properly weighted mean","Checking whether a headline figure hides subgroups","Asking how the cases were assigned to each group"]'::jsonb, '{2,3}'::smallint[], 'Both useful habits are about looking for the hidden variable that sorts cases unevenly between groups. Sheer size does not protect you at all: bigger data can reverse just as cleanly.', 4::smallint),
  ('benfords-law', 'What does Benford''s law say about leading digits?', '["The last digit is the one that follows a pattern","Each digit from 1 to 9 appears about equally often","A leading 1 appears about 50 per cent of the time","A leading 9 appears under 5 per cent of the time"]'::jsonb, '{3}'::smallint[], 'The distribution falls steeply from about 30 per cent for a leading 1 to under 5 per cent for a leading 9. An even spread is the intuition the law contradicts, and the law concerns first digits rather than last.', 0::smallint),
  ('benfords-law', 'Which dataset would you expect to follow the law?', '["The lengths of the world''s major rivers","Telephone numbers issued in a given city","Populations of the towns in one country","Adult human heights measured in centimetres"]'::jsonb, '{0,2}'::smallint[], 'The law fits quantities that span several orders of magnitude and are not artificially bounded or assigned. Heights cluster tightly around one value and phone numbers are allocated by rules, so neither qualifies.', 1::smallint),
  ('benfords-law', 'Why does the pattern arise in the first place?', '["People prefer to record numbers starting with 1","Measurement errors cluster around the low values","Growth spends longer between 1 and 2 than 9 and 10","Small numbers are simply more common than large"]'::jsonb, '{2}'::smallint[], 'Anything growing by percentages takes far longer to climb from 1 to 2 than from 9 to 10, so it sits in the low leading digits more often. The pattern is about scale, not about small values being commoner or people preferring them.', 2::smallint),
  ('benfords-law', 'An auditor finds a firm''s expense claims are digit-uniform. What follows?', '["It is a red flag that is worth investigating","The firm must have rounded its figures heavily","Invented numbers get spread out far too evenly","It proves the figures must have been fabricated"]'::jsonb, '{0,2}'::smallint[], 'People inventing numbers spread them evenly because they believe that looks random, which is the tell auditors look for. It remains circumstantial: a deviation is grounds for a closer look, never proof on its own.', 3::smallint),
  ('benfords-law', 'What limits its use as evidence of fraud?', '["Some legitimate datasets do not follow the law","It requires very large samples to be meaningful","It can identify which specific entries were faked","Prices and thresholds distort the leading digits"]'::jsonb, '{0,1,3}'::smallint[], 'Bounded, assigned or price-clustered data can deviate for innocent reasons, and small samples produce noise that means nothing. The law describes a distribution, so it can never finger an individual entry.', 4::smallint),
  ('regression-to-the-mean', 'What does regression to the mean describe?', '["Averages become more accurate as data accumulates","Poor performers improve and good ones permanently fall","Performance improves steadily with regular practice","Any measurement containing luck drifts back to average"]'::jsonb, '{3}'::smallint[], 'Whenever an outcome mixes skill with chance, an extreme reading was probably helped by luck that will not repeat. Nothing changes permanently and no force pulls anyone anywhere: it is a property of noisy measurement.', 0::smallint),
  ('regression-to-the-mean', 'Praise is followed by worse flights, criticism by better ones. What holds?', '["Praise makes trainees complacent and careless","Both changes are expected after extreme results","Criticism works considerably better than praise","The feedback may have had no real effect at all"]'::jsonb, '{1,3}'::smallint[], 'Exceptional flights are followed by average ones and terrible flights by better ones whatever the instructor says, so the feedback gets credit and blame it did not earn. This is the classic example of the world teaching people the wrong lesson.', 1::smallint),
  ('regression-to-the-mean', 'Where does the effect create false confidence in treatments?', '["Speed cameras placed after a bad accident year","Remedies tried at the worst point of an illness","A drug tested against a proper placebo control group","Coaching bought after an unusually bad quarter"]'::jsonb, '{0,1,3}'::smallint[], 'Each of these intervenes at an extreme, so improvement was likely anyway and gets attributed to the intervention. A properly randomised control group is the fix, because the comparison group regresses too.', 2::smallint),
  ('regression-to-the-mean', 'When does the effect NOT appear?', '["When the measurement is repeated a great many times","When the sample being studied is extremely large","When the same person is measured on two occasions","When the measure is almost pure skill and little luck"]'::jsonb, '{3}'::smallint[], 'Regression needs two ingredients, randomness in the measure and an extreme starting point, so a nearly pure skill measure shows almost none. Repeating the measurement is where it shows up most clearly rather than least.', 3::smallint),
  ('regression-to-the-mean', 'A footballer on the cover after a record season plays worse. What holds?', '["Record seasons are selected for being extreme ones","The player''s underlying skill has probably declined","A season that good was partly luck, not repeated","The cover appearance somehow jinxed the player"]'::jsonb, '{0,2}'::smallint[], 'The player was chosen because of an extreme result, which guarantees a likely fall regardless of what appears on any magazine. The curse is regression to the mean wearing a superstition.', 4::smallint),
  ('the-pygmalion-effect', 'What does the Pygmalion effect claim?', '["Expectations act though nobody behaves differently","Others'' expectations change how well you perform","Believing in yourself improves your own results","Praise alone makes people work a good deal harder"]'::jsonb, '{1}'::smallint[], 'The claim is that someone else''s belief changes their behaviour towards you, and that changed behaviour changes your performance. An effect with no behavioural channel would be telepathy, and it is not what the research describes.', 0::smallint),
  ('the-pygmalion-effect', 'In the original study, what were teachers told and what happened?', '["Teachers were told which pupils were struggling","Teachers were shown genuine aptitude test results","The named pupils had genuinely scored much higher","The named pupils gained more on the later tests"]'::jsonb, '{3}'::smallint[], 'The labelled children gained more even though the labels had been assigned at random and carried no information. Because the only thing that differed was the teachers'' belief, the change had to come from the teachers.', 1::smallint),
  ('the-pygmalion-effect', 'Through what channels do expectations reach the student?', '["Direct statements about who is expected to do well","More time given to answer a difficult question","A warmer tone of voice and more eye contact","More demanding material being handed out"]'::jsonb, '{1,2,3}'::smallint[], 'The transmission is mostly unspoken: waiting longer, warmer treatment and harder work assigned all follow from an expectation without anyone announcing it. Explicit statements are not needed, and that is what makes the effect hard to police.', 2::smallint),
  ('the-pygmalion-effect', 'What is the strongest caution about this research?', '["The effect was strongest in the youngest pupils","The effect has not been found outside of schools","Later replications found much smaller effects","The original test scores had serious problems"]'::jsonb, '{2,3}'::smallint[], 'The original study drew serious criticism over its instruments, and follow-up work found the effect real but far more modest than the popular story. It does appear outside schools, including in military and workplace settings.', 3::smallint),
  ('the-pygmalion-effect', 'You take over a team labelled as weak by the last manager. What follows?', '["The label is evidence about their actual ability","You should tell the team about your expectations","The label may be partly producing the performance","Your own expectations will leak through behaviour"]'::jsonb, '{2,3}'::smallint[], 'An inherited reputation can be self-sustaining, and your beliefs will show in how you allocate work and attention whether or not you say anything. Announcing high expectations does not substitute for acting on them, which is where the effect actually operates.', 4::smallint),
  ('the-peak-end-rule', 'What does the peak-end rule say about how we remember experiences?', '["The beginning is the part that we remember best","Total duration weighs surprisingly little","How the experience ended weighs heavily","The single most intense moment weighs heavily"]'::jsonb, '{1,2,3}'::smallint[], 'Remembered quality is dominated by the peak and the ending, while length is largely neglected, which is called duration neglect. The opening matters for other reasons, but it is not part of this rule.', 0::smallint),
  ('the-peak-end-rule', 'A longer painful procedure was remembered as better. How?', '["The gentler ending improved the memory of the whole","The total amount of pain was in fact lower overall","Patients forgot the earlier part of the procedure","The procedure felt shorter than it actually was"]'::jsonb, '{0}'::smallint[], 'Adding a milder tail raised the ending without touching the peak, and the remembered experience improved even though total pain went up. Duration is largely neglected in the judgement, so it is not that the extra time felt short.', 1::smallint),
  ('the-peak-end-rule', 'What follows for designing a customer experience?', '["Shorten the whole experience as much as possible","Put the strongest single moment right at the end","Fix the worst moment before smoothing everything","Keep the whole experience evenly pleasant throughout"]'::jsonb, '{1,2}'::smallint[], 'Since memory samples the peak and the end, effort spent on those two points buys more than effort spread evenly. A uniformly nice experience has no memorable peak, and shortening it barely registers.', 2::smallint),
  ('the-peak-end-rule', 'What tension does the rule create between experience and memory?', '["Memory is simply an inaccurate recording of experience","The version you live and the one you keep differ","People choose to repeat the better-remembered option","More total pain sometimes makes the better memory"]'::jsonb, '{1,2,3}'::smallint[], 'Because choices are made by the remembering self, people will pick the option that felt worse overall but ended better. Calling this a fault misses the point: it is a systematic summary rule, not noise in a recording.', 3::smallint),
  ('the-peak-end-rule', 'Where should you not expect the rule to help you?', '["Choosing between similar experiences from memory","Judging how much total time something actually took","Deciding whether a holiday was worth the money spent","Rating an experience once it has finally finished"]'::jsonb, '{1}'::smallint[], 'The rule describes remembered judgements, so it tells you nothing reliable about how long something took. Retrospective evaluation is exactly where it does apply, which is why it shapes how people rate holidays and hospital stays.', 4::smallint),
  ('choice-blindness', 'What does choice blindness describe?', '["People explain a choice they did not actually make","People fail to notice that their choice was swapped","People regret decisions made under time pressure","People cannot decide when options are too similar"]'::jsonb, '{0,1}'::smallint[], 'The finding has two halves: the swap goes undetected, and the participant then argues for the outcome they never picked. It is not about indecision or regret.', 0::smallint),
  ('choice-blindness', 'In the face experiment, what did participants do after the swap?', '["Most gave reasons for the face they had rejected","They gave vaguer reasons than for genuine choices","Most people spotted the change almost immediately","They rated the swapped face far lower afterwards"]'::jsonb, '{0}'::smallint[], 'The majority accepted the substituted photo and justified it fluently, often citing features unique to the face they had turned down. Their explanations were not noticeably weaker than for real choices, which is the disturbing part.', 1::smallint),
  ('choice-blindness', 'What does the effect suggest about our reasons for decisions?', '["We have no genuine preferences of our own here","Reasons are stored at the exact moment of choosing","Choices are made more or less completely at random","Introspection reports a story rather than a cause"]'::jsonb, '{3}'::smallint[], 'The mind supplies a plausible account for whatever outcome it finds in front of it, so introspection reports a story rather than the cause. If reasons were recorded at the moment of choosing, a swapped option could not be defended so fluently.', 2::smallint),
  ('choice-blindness', 'The effect has been shown for which of these?', '["Taste preferences between two similar jams","Whether a person is left handed or right handed","Political opinions given on a questionnaire","Which of two faces is the more attractive"]'::jsonb, '{0,2,3}'::smallint[], 'Jam, faces and even stated political positions have all been swapped without detection, with participants defending the altered answer. Handedness is a stable physical fact, not the kind of momentary judgement the paradigm manipulates.', 3::smallint),
  ('choice-blindness', 'What does this imply for asking people why they chose something?', '["Self-report is worthless as a source of data","Confident explanations are not evidence of insight","The answer may be a reconstruction, not a record","People are deliberately lying about their reasons"]'::jsonb, '{1,2}'::smallint[], 'Fluency and confidence turn out to be poor guides to whether an explanation tracks the real cause. Nobody in these studies is lying, and self-report still tells you what people believe, which is useful as long as you do not mistake it for a causal account.', 4::smallint),
  ('dunbars-number', 'What does Dunbar''s number claim to be a ceiling on?', '["Names you can remember over a whole lifetime","Faces that you are able to recognise on first sight","Stable relationships you can actively maintain","People whose social context you can keep track of"]'::jsonb, '{2,3}'::smallint[], 'The limit is about maintained relationships and knowing how people relate to each other, not raw memory. You can recognise thousands of faces and still be capped at around 150 working relationships.', 0::smallint),
  ('dunbars-number', 'Where did the figure of about 150 originally come from?', '["Surveys asking people how many friends they have","Experiments on human memory for names and faces","Counting members of historical villages and armies","A correlation of brain size and group size in primates"]'::jsonb, '{3}'::smallint[], 'Dunbar extrapolated from the relationship between neocortex size and typical group size across primates, then found human groups of roughly that size in the record. The historical examples came afterwards as supporting evidence, not as the source.', 1::smallint),
  ('dunbars-number', 'What does the model say about the structure inside the number?', '["Each outer layer takes less effort per person","The layers scale by a factor of about three","The 150 relationships sit at the same closeness","Nested layers of roughly 5, 15, 50 and then 150"]'::jsonb, '{0,1,3}'::smallint[], 'The layers grow by roughly threefold and the cost per relationship drops as you move outwards, with your closest few taking most of the effort. Equal closeness is exactly what the layered model rules out.', 2::smallint),
  ('dunbars-number', 'What is the main criticism of the number?', '["It has not been tested against actual group sizes","It was measured in pre-industrial societies alone","The statistical extrapolation is highly uncertain","Other analyses give ranges from tens to hundreds"]'::jsonb, '{2,3}'::smallint[], 'Reanalyses of the primate data produce confidence intervals so wide that a single precise figure is hard to defend. The idea has been tested repeatedly, which is how the criticism arose in the first place.', 3::smallint),
  ('dunbars-number', 'Your social network shows 900 contacts. What does the theory predict?', '["Most are stored contacts rather than maintained ties","The platform has raised your own cognitive ceiling","The limit does not apply to your online connections","Your closest layer expands to match the contact list"]'::jsonb, '{0}'::smallint[], 'Studies of messaging traffic find interaction concentrated on a number close to the predicted layers, with the rest dormant. Cheap storage of contacts does not lower the cost of maintaining a relationship, so the inner layers do not grow.', 4::smallint),
  ('semantic-satiation', 'What happens during semantic satiation?', '["A repeated word temporarily stops feeling meaningful","You permanently forget what the word used to mean","The word becomes far harder to pronounce correctly aloud","You start mispronouncing the word without noticing"]'::jsonb, '{0}'::smallint[], 'Meaning drains away while the raw sound stays, so the word starts to seem like a strange noise. Nothing happens to your ability to say it, and nothing is lost permanently: the effect fades within seconds of stopping.', 0::smallint),
  ('semantic-satiation', 'What is the standard explanation?', '["Repeated activation gives a diminishing response","Attention shifts from meaning to sound deliberately","The word is deleted from memory and then reloaded","The neural pattern for the meaning simply fatigues"]'::jsonb, '{0,3}'::smallint[], 'Both correct options describe reactive inhibition: repeatedly firing the same representation makes it respond less each time. The shift to sound is a consequence of the fading meaning, not a choice you make.', 1::smallint),
  ('semantic-satiation', 'How long does the effect usually last?', '["Until the next night''s sleep","It varies wildly between people","Seconds, once you stop repeating","Several hours, sometimes longer"]'::jsonb, '{2}'::smallint[], 'Recovery happens within seconds once the repetition stops, which is what distinguishes fatigue from actual forgetting.', 2::smallint),
  ('semantic-satiation', 'Where has the effect been put to practical use?', '["Improving your recall of long lists of words","Speeding up the learning of a foreign vocabulary list","Reducing the emotional sting of a distressing word","Helping people who stutter on a specific word"]'::jsonb, '{2,3}'::smallint[], 'Draining a word of meaning has been used therapeutically to weaken its emotional charge and to loosen a stuttering block. It works against learning and recall, since a satiated word is processed less, not more.', 3::smallint),
  ('semantic-satiation', 'Which everyday experience is the same phenomenon?', '["A brand name losing sense after an advert repeats","Losing the thread of a sentence you are reading","A familiar spelling that suddenly looks wrong","No longer noticing the smell of your own home"]'::jsonb, '{0,2}'::smallint[], 'Both correct cases are repetition draining a specific representation of its normal meaning. Smell adaptation is sensory habituation in a different system, and losing your place is an attention problem rather than a fatigued meaning.', 4::smallint),
  ('base-rate-neglect', 'A test is 99 per cent accurate for a disease 1 in 10,000 people have. What holds?', '["The result is meaningless and should be ignored","Most of the positive results will be false alarms","A positive result means you almost certainly have it","The rarity matters more than the test''s accuracy"]'::jsonb, '{1,3}'::smallint[], 'In 10,000 people there is about one true case but roughly a hundred false positives, so a positive is far more likely to be an error. The result is not meaningless: it raises your odds sharply, just not to anywhere near certainty.', 0::smallint),
  ('base-rate-neglect', 'What exactly is being neglected?', '["How common the condition is before any testing","The chance that the test itself makes a mistake","The size of the population that is being tested","The number of tests the person has already taken"]'::jsonb, '{0}'::smallint[], 'The forgotten number is how common the condition is before testing, which the result updates rather than replaces. Error rates are the part people do notice, which is precisely why they overweight them.', 1::smallint),
  ('base-rate-neglect', 'Why is the mistake so natural?', '["The base rate is usually withheld from the patient","Accuracy figures sound like the answer being asked for","Percentages are inherently hard for most people to compute","The vivid case crowds out the background statistic"]'::jsonb, '{1,3}'::smallint[], 'A 99 per cent accurate test sounds like it gives a 99 per cent chance of illness, and the concrete positive result feels more informative than an abstract rate. Presenting the same problem as counts of people rather than percentages makes it far easier for most people.', 2::smallint),
  ('base-rate-neglect', 'Someone is quiet and tidy. Librarian or salesperson?', '["The stereotype is stronger evidence than the numbers","Salesperson, because there are far more of those","The description tells you nothing of any real use","Librarian, since the description fits much better"]'::jsonb, '{1}'::smallint[], 'Salespeople outnumber librarians many times over, and that gap outweighs a strong stereotype match. The description does carry some information, just far less than the difference in how many of each exist.', 3::smallint),
  ('base-rate-neglect', 'When does a positive screening result become genuinely alarming?', '["When the symptoms had already made it likely","When a second test also comes back positive","When the condition is common in the group tested","When the test''s accuracy is above 95 per cent"]'::jsonb, '{0,1,2}'::smallint[], 'Everything that raises the prior before the test raises what the positive means, and a second independent positive raises it again. Headline accuracy alone never settles it, which is the whole lesson.', 4::smallint),
  ('the-decoy-effect', 'What is a decoy in this sense?', '["An option priced exactly midway between the other two","A deliberately confusing way of pricing things","The cheapest of the options on the whole list","An option worse than one rival but not the other"]'::jsonb, '{3}'::smallint[], 'A decoy is dominated by one existing option, which makes that option look obviously better by comparison. Sitting in the middle on price is not enough: it has to be clearly worse than its target on the terms being compared.', 0::smallint),
  ('the-decoy-effect', 'Popcorn: small 3, large 7. A medium at 6.50 is added. What happens?', '["Sales of the large size go up noticeably","The large one now looks like obvious value","The medium becomes the most popular size","Sales of the small size go up noticeably"]'::jsonb, '{0,1}'::smallint[], 'The medium exists to be compared unfavourably with the large, which suddenly reads as fifty cents for a big jump in size. It is not meant to sell, and its presence pulls people away from the small.', 1::smallint),
  ('the-decoy-effect', 'What does the effect reveal about how we choose?', '["We compute the value independently for each option","Adding options leaves existing preferences intact","We look for the option that beats another clearly","Preferences are stable once a person has formed them"]'::jsonb, '{2}'::smallint[], 'Comparison is easier than valuation, so we gravitate to whichever option we can demonstrate beats another. If preferences were stable, adding an option nobody wants could not reorder the two that were already there.', 2::smallint),
  ('the-decoy-effect', 'Where would you expect to meet the effect?', '["Coffee sizes offered in a chain café","A single product with a discount code","Subscription bundles for a magazine","A three-tier software pricing page"]'::jsonb, '{0,2,3}'::smallint[], 'Anywhere a middle option exists mainly to make a target option look reasonable, the decoy is likely doing the work. A discount on a lone product has no rival to be dominated by.', 3::smallint),
  ('the-decoy-effect', 'How do you defend yourself against it?', '["Decide what you need before looking at the tiers","Take the middle option as a general rule of thumb","Compare each option against the others carefully","Ask what each option is worth to you on its own"]'::jsonb, '{0,3}'::smallint[], 'The defence is to value options against your own requirement rather than against each other, which is the comparison the decoy hijacks. Careful comparison is what the effect feeds on, and defaulting to the middle is precisely the behaviour it exploits.', 4::smallint),
  ('the-fermi-paradox', 'What is the tension the Fermi paradox points at?', '["We have found no sign of anyone despite good odds","Planets outside our own turn out to be scarce","The galaxy is too young for anyone to spread far","Radio signals from other stars are too weak for us"]'::jsonb, '{0}'::smallint[], 'The paradox is the gap between good odds and complete silence. Age works the other way round: the galaxy has been habitable for billions of years, which is exactly why the emptiness needs explaining.', 0::smallint),
  ('the-fermi-paradox', 'Why is the age of the galaxy central to the argument?', '["A few million years is short against billions","Stars have been stable for a rather short time","Life needs the full age of the galaxy just to appear","Slow ships could cross it in a few million years"]'::jsonb, '{0,3}'::smallint[], 'Sublight travel is enough to reach every star in a span that is a rounding error on galactic time, so a single expanding civilisation should already be everywhere. That is what makes the emptiness demand an explanation.', 1::smallint),
  ('the-fermi-paradox', 'What does the Great Filter idea propose?', '["Finding simple life elsewhere would be reassuring","Some step from lifeless matter to expansion is rare","Advanced civilisations choose to hide themselves","The filter may lie behind us or still ahead of us"]'::jsonb, '{1,3}'::smallint[], 'The Filter is a bottleneck somewhere in the chain, and its position determines whether we are rare survivors or approaching our own. Finding independent life nearby would be bad news, since it would push the filter towards our future.', 2::smallint),
  ('the-fermi-paradox', 'Which are serious proposed resolutions?', '["Civilisations destroy themselves before expanding","The universe is far too young for life to have formed","Intelligent life is genuinely a very rare event","Our searches have covered only a sliver of the sky"]'::jsonb, '{0,2,3}'::smallint[], 'Rarity, self-destruction and the narrowness of our search are all live candidates. Youth of the universe is not: the Earth is a latecomer, with countless older stars around.', 3::smallint),
  ('the-fermi-paradox', 'What does the silence so far actually license us to conclude?', '["No civilisation has visibly restructured our galaxy","Nobody has ever deliberately tried to contact us","Interstellar travel must therefore be impossible","We are certainly alone in this entire universe"]'::jsonb, '{0}'::smallint[], 'Non-detection rules out anyone visibly restructuring the galaxy on a large scale, which is a real but narrow constraint. It cannot tell us about intentions, and it certainly cannot establish that we are alone.', 4::smallint),
  ('time-dilation', 'What does time dilation say about a fast-moving clock?', '["The effect is symmetric: each sees the other slowed","The mechanism of the clock is disturbed by speed","It appears to slow down but in fact still runs normally","It ticks more slowly as measured from your frame"]'::jsonb, '{0,3}'::smallint[], 'The slowing is a real property of the relation between frames, not an illusion or a mechanical fault, and each observer measures the other''s clock as slow. Any clock does it, from atomic ones to your heartbeat, which is why it cannot be a defect in the device.', 0::smallint),
  ('time-dilation', 'What evidence shows the effect is measured, not merely theorised?', '["GPS satellites need continual corrections to clocks","Distant galaxies appear redder than the nearby ones","Flown atomic clocks disagree with clocks on the ground","Muons from the high atmosphere still reach the ground"]'::jsonb, '{0,2,3}'::smallint[], 'Muon survival, flown atomic clocks and satellite navigation are all everyday confirmations at very different scales. Galactic redshift is caused by expansion, a different phenomenon entirely.', 1::smallint),
  ('time-dilation', 'What else besides speed makes clocks run at different rates?', '["The temperature at which the clock is kept","The direction of motion relative to the stars","The age of the clock''s internal components","Sitting deeper inside a gravitational field"]'::jsonb, '{3}'::smallint[], 'Gravitational time dilation means a clock deeper in a gravitational well runs slower, an effect measured over height differences of a single metre. Nothing about the clock''s construction or age enters into it.', 2::smallint),
  ('time-dilation', 'GPS satellites move fast and sit high. What is the net effect?', '["Their clocks run fast overall against ground clocks","Their clocks run slow overall against ground clocks","The weaker gravity outweighs their orbital speed","The two effects cancel each other out exactly"]'::jsonb, '{0,2}'::smallint[], 'Speed slows them and weaker gravity speeds them up, and the gravitational term wins, leaving a net gain of tens of microseconds a day. Uncorrected, that turns into position errors of kilometres within a day.', 3::smallint),
  ('time-dilation', 'Why does nobody notice time dilation in daily life?', '["It needs instruments far more precise than we have","The effect cancels itself out over a whole day","The effect is negligible at any everyday speed","It appears near the speed of light and nowhere else"]'::jsonb, '{2}'::smallint[], 'The effect is real at walking pace but fantastically small, far below anything a person could notice. It does not cancel out; it simply never accumulates to a size that matters at everyday speeds.', 4::smallint),
  ('why-astronauts-float', 'Why do astronauts on the space station float?', '["The station''s great speed cancels the gravity out there","The station is beyond the reach of the atmosphere","There is almost no gravity left at that altitude","They and the station fall around the Earth together"]'::jsonb, '{3}'::smallint[], 'Gravity at 400 kilometres is about 90 per cent of its surface strength; what is missing is a floor pushing back. Everything falls together, so nothing presses on anything, and that is what weightlessness is.', 0::smallint),
  ('why-astronauts-float', 'What does an orbit really consist of?', '["Falling while moving sideways fast enough to miss","Continuous free fall along a curved path in space","Balancing gravity against a centrifugal force","Being far enough that gravity no longer reaches"]'::jsonb, '{0,1}'::smallint[], 'Orbit is free fall with enough sideways velocity that the ground curves away as fast as you drop towards it. There is no outward force doing any balancing; there is only gravity and the sideways motion it bends.', 1::smallint),
  ('why-astronauts-float', 'How could you experience weightlessness without leaving the atmosphere?', '["Inside a sealed vacuum chamber on the ground","Standing at the top of a very high mountain","Inside a lift whose cable has just been cut","Inside an aircraft flying a parabolic arc"]'::jsonb, '{2,3}'::smallint[], 'Both correct cases put you in free fall, which is the only ingredient required. Altitude and vacuum change nothing: on a mountain the ground still pushes back, and in a chamber so does the floor.', 2::smallint),
  ('why-astronauts-float', 'Why is ''zero gravity'' a misleading label for the station?', '["Without gravity the station would fly off straight","Gravity is what keeps the station in orbit at all","Microgravity is the more accurate term for it","Gravity is genuinely absent there, the term is accurate"]'::jsonb, '{0,1,2}'::smallint[], 'Gravity is not merely present, it is the force doing all the work of holding the orbit. The residual jiggle from drag and crew movement is why engineers say microgravity rather than zero.', 3::smallint),
  ('why-astronauts-float', 'Astronauts are permanently falling. Why do they never hit the ground?', '["They fall too slowly to cover any real distance","Their engines are constantly pushing them back up","They fall towards a surface that curves away below","The thin atmosphere gives them just enough lift"]'::jsonb, '{2}'::smallint[], 'They fall at full speed towards a surface that keeps curving away beneath them, which is what an orbit is. Their horizontal velocity of roughly 7.7 kilometres per second is what makes the fall never end.', 4::smallint),
  ('tidal-locking', 'Why do we always see the same side of the Moon?', '["The Moon does not rotate on its axis in space","It rotates exactly once for each orbit it makes","Earth''s gravity holds one side permanently to us","Its orbit is too slow for any rotation to show"]'::jsonb, '{1}'::smallint[], 'A non-rotating moon would show us every side over one orbit, so the Moon must be turning exactly once per circuit. Tidal forces ground its spin down until the two periods matched.', 0::smallint),
  ('tidal-locking', 'How does tidal locking come about?', '["The magnetic field couples the two bodies together","The bulge lags behind and gets pulled on, braking spin","Friction with the passing solar wind slows down rotation","Gravity stretches the whole body into a slight bulge"]'::jsonb, '{1,3}'::smallint[], 'A body in a gravitational gradient is stretched, and if it spins the bulge is dragged out of alignment, giving gravity a lever to slow the spin. It is a mechanical process, with no role for magnetism or wind.', 1::smallint),
  ('tidal-locking', 'What fraction of the lunar surface can be seen from Earth over time?', '["Exactly half of it, and no more than that","The whole surface, over the course of a year","About 75 per cent of the total lunar surface","Slightly more than half, as the Moon rocks"]'::jsonb, '{3}'::smallint[], 'Libration, caused by the tilted and slightly elliptical orbit, lets us see about 59 per cent by rocking the Moon a little either way. The far side is not the same thing as the dark side, and it stays hidden.', 2::smallint),
  ('tidal-locking', 'What else follows from the same tidal interaction?', '["Earth will eventually become locked to the Moon","The Moon''s orbit is becoming steadily more circular","Earth''s day is gradually getting longer as well","The Moon is slowly moving further away from us"]'::jsonb, '{0,2,3}'::smallint[], 'The exchange transfers angular momentum, pushing the Moon outwards while Earth''s rotation slows, and given enough time Earth would lock too. The Sun will end the story long before that happens.', 3::smallint),
  ('tidal-locking', 'Where else does tidal locking show up?', '["The solar system''s planets, relative to the Sun","Most of the large moons of the giant planets","Many planets orbiting close to red dwarf stars","Pluto and Charon, which are locked to each other"]'::jsonb, '{1,2,3}'::smallint[], 'Locking needs closeness and time, which is why big moons and tight exoplanet orbits show it, and Pluto and Charon are locked mutually. The planets orbit the Sun far too distantly for the effect to have taken hold.', 4::smallint),
  ('olbers-paradox', 'What does Olbers'' paradox ask?', '["Why the stars are not spread evenly across the sky","Why we cannot see out to the edge of the universe","Why the night sky is dark if the stars are endless","Why some stars are so much brighter than others"]'::jsonb, '{2}'::smallint[], 'In an infinite, eternal, static universe every direction would eventually meet a stellar surface and the sky would blaze. Darkness is therefore evidence that one of those assumptions must be wrong.', 0::smallint),
  ('olbers-paradox', 'Why does distance alone not solve the paradox?', '["Brightness falls with distance but star numbers grow","Dust blocks the light coming from the most distant stars","The two effects cancel out in an infinite universe","Distant stars are simply far too faint to matter"]'::jsonb, '{0,2}'::smallint[], 'Each shell of sky further out is dimmer per star but contains proportionally more stars, so every shell contributes the same. Dust was the historical answer and it fails, because absorbed light would heat the dust until it glowed.', 1::smallint),
  ('olbers-paradox', 'What is the accepted resolution?', '["Light beyond a certain distance has not arrived","The universe turns out to be finite in size","The universe turns out to have a finite age","Expansion redshifts distant light out of view"]'::jsonb, '{0,2,3}'::smallint[], 'A finite age gives a horizon beyond which nothing has reached us yet, and expansion stretches what does arrive into the infrared and beyond. Finite size is not needed and is not what current cosmology asserts.', 2::smallint),
  ('olbers-paradox', 'In what sense is the sky actually not dark?', '["The cosmic background fills every direction","Starlight scattered by dust gives a faint glow","Distant galaxies light the sky in visible light","It glows uniformly across the microwave band"]'::jsonb, '{0,3}'::smallint[], 'Every line of sight really does end in a hot surface, the early universe, but expansion has cooled that glow to microwaves. Olbers was right about the geometry and wrong only about the wavelength.', 3::smallint),
  ('olbers-paradox', 'What does the paradox demonstrate about simple observations?', '["Darkness at night rules out an infinite old universe","The result requires precise measurement to be useful","Cosmology can be done with no observations needed","Naked-eye astronomy is more reliable than telescopes"]'::jsonb, '{0}'::smallint[], 'The mere fact that night is dark excludes an entire class of universes, with no instrument required. That is an observation doing the work, which is the opposite of doing without one.', 4::smallint),
  ('quantum-entanglement', 'What is true of two entangled particles?', '["You can send a message faster than light with them","The two particles must remain physically close by","Each carried a hidden answer agreed on in advance","Measuring one instantly fixes the other''s outcome"]'::jsonb, '{3}'::smallint[], 'Measuring one fixes the outcome for the other, and the correlations are stronger than any pre-agreed instruction set could produce. Distance is irrelevant, which is precisely what made Einstein uncomfortable.', 0::smallint),
  ('quantum-entanglement', 'Why can entanglement not be used to transmit information?', '["Each individual result on its own looks random","The pair of particles decoheres too quickly to be useful","Comparing results requires an ordinary channel","The correlation appears when the results are compared"]'::jsonb, '{0,2,3}'::smallint[], 'The person holding one particle sees noise, and the pattern only emerges once both sets of results are brought together by a normal, light-speed channel. Decoherence is a practical engineering problem, not the reason the limit holds.', 1::smallint),
  ('quantum-entanglement', 'What did Bell''s theorem make possible?', '["Proof that quantum mechanics must be incomplete","A way to compute the strength of entanglement","An experimental test of local hidden variables","Turning a philosophical dispute into a measurement"]'::jsonb, '{2,3}'::smallint[], 'Bell converted the Einstein-Bohr disagreement into an inequality that experiments could violate or respect. The experiments went against local hidden variables, which is the opposite of showing quantum mechanics incomplete.', 2::smallint),
  ('quantum-entanglement', 'What does quantum teleportation actually move?', '["The original particle, destroyed in the process","A copy, which leaves the original state intact","The quantum state itself, but not any matter","Matter itself from one place to a distant one"]'::jsonb, '{2}'::smallint[], 'The quantum state is reconstructed elsewhere using entanglement plus classical bits that travel normally, so nothing outruns light. The original state is destroyed in the process: quantum states cannot be copied.', 3::smallint),
  ('quantum-entanglement', 'Where is entanglement already used in practice?', '["Instantaneous communication between two continents","Improved precision in some careful measurements","Quantum key distribution over fibre and satellite","Certain operations inside quantum computers"]'::jsonb, '{1,2,3}'::smallint[], 'Key distribution, computation and metrology all exploit entanglement in working systems today. The one thing it cannot do is deliver a message faster than light, which is the application people always assume first.', 4::smallint),
  ('lagrange-points', 'What is a Lagrange point?', '["A place where gravity and orbital motion balance","A point in space where gravity is exactly zero","A point where the two bodies pull equally hard","The exact midpoint between the two large bodies"]'::jsonb, '{0}'::smallint[], 'At these points the combined pull supplies exactly the force needed to orbit in step with the two large bodies. Equal pull is a different condition entirely, and it does not produce a co-orbiting position.', 0::smallint),
  ('lagrange-points', 'How many Lagrange points does a two-body system have?', '["Five, of which two are stable and three are not","Two of them stable and two others unstable","Seven, four stable and the other three unstable","Three, with just one of the three stable"]'::jsonb, '{0}'::smallint[], 'There are five points, labelled L1 to L5, and only L4 and L5 are stable. Spacecraft at the other three need small regular corrections to stay in place.', 1::smallint),
  ('lagrange-points', 'Why was L2 chosen for the James Webb telescope?', '["Sun, Earth and Moon stay on one side of the craft","The telescope keeps a stable and cold environment","Gravity is weakest there, so no station fuel is needed","One sunshield blocks all three heat sources at once"]'::jsonb, '{0,1,3}'::smallint[], 'Keeping all the bright, warm objects behind a single shield is what lets the mirror sit at a few tens of kelvin. Fuel is still needed, since L2 is unstable and the telescope must be nudged back regularly.', 2::smallint),
  ('lagrange-points', 'What collects naturally at the stable points L4 and L5?', '["Concentrations of drifting interplanetary dust","A few small companion objects belonging to Earth","Asteroids, called Trojans, in Jupiter''s orbit","Nothing, since material passes straight through"]'::jsonb, '{0,1,2}'::smallint[], 'Stability means objects nudged slightly away tend to circle back, so debris accumulates there over time. Jupiter''s Trojan swarm is the largest example, and Earth has a couple of tiny ones.', 3::smallint),
  ('lagrange-points', 'Why is a satellite at L1 useful for watching the Sun?', '["It is close enough to touch the Sun''s outer atmosphere","It has an uninterrupted view with no night at all","It gets early warning of solar wind heading our way","It sits between the Earth and the Sun continuously"]'::jsonb, '{1,2,3}'::smallint[], 'L1 gives a permanent upstream vantage point with no Earth in the way, which buys roughly an hour of warning for space weather. It is only about one per cent of the way to the Sun, nowhere near its atmosphere.', 4::smallint),
  ('redshift', 'What does the redshift of distant galaxies tell us?', '["They are simply cooler than the nearby galaxies","The space between us and them is itself expanding","Their light has lost energy passing through dust","They are moving away through space at high speed"]'::jsonb, '{1}'::smallint[], 'Cosmological redshift comes from space itself expanding while the light is in transit, not from galaxies flying through space. Dust reddens light by scattering, which is a different effect and does not shift spectral lines.', 0::smallint),
  ('redshift', 'What is Hubble''s key observation?', '["Nearby galaxies show no blueshift of any kind","More distant galaxies show larger redshifts still","Galaxies move away from our position in particular","Redshift is proportional to the distance away"]'::jsonb, '{1,3}'::smallint[], 'The proportional relation between distance and recession is the signature of uniform expansion, which looks the same from every galaxy. Andromeda is blueshifted, since local gravity beats expansion at short range.', 1::smallint),
  ('redshift', 'How is redshift actually measured?', '["By the overall colour that the galaxy appears","By timing how long the light took to reach us","By the shift of well-known spectral lines","By comparing brightness with nearby galaxies"]'::jsonb, '{2}'::smallint[], 'Elements produce lines at fixed known wavelengths, so the shift of the whole pattern gives an unambiguous measure. There is no way to time light that left before anyone was watching.', 2::smallint),
  ('redshift', 'Does expansion stretch everything, including us?', '["Galaxies within clusters stay bound by gravity","Only the space between clusters grows measurably","Yes, atoms and galaxies both expand at the same rate","No, bound systems are held together against it"]'::jsonb, '{0,1,3}'::smallint[], 'Gravity and electromagnetism easily overwhelm expansion on small scales, so atoms, planets and galaxy clusters do not grow. The stretching only wins in the near-empty gaps between clusters.', 3::smallint),
  ('redshift', 'What does a galaxy at redshift 7 tell us?', '["It is moving through space faster than light does","Its light has travelled for most of cosmic history","We see it as it once was, and not as it is now","It is now further away than the travel time implies"]'::jsonb, '{1,2,3}'::smallint[], 'High redshift means both great distance and great lookback time, and expansion has carried the galaxy still further away since the light left. Nothing is moving through space faster than light; the space in between simply grew.', 4::smallint),
  ('the-cosmic-microwave-background', 'What is the cosmic microwave background?', '["The combined glow of the far distant galaxies","Radiation still produced by empty space today","The explosion of the Big Bang, seen from the outside","Light released as the universe first became clear"]'::jsonb, '{3}'::smallint[], 'When electrons and nuclei combined into neutral atoms the fog cleared, and the light of that moment has been travelling ever since. Nothing is generating it now; we are seeing an event roughly 380,000 years after the Big Bang.', 0::smallint),
  ('the-cosmic-microwave-background', 'Why does it appear in microwaves rather than as visible light?', '["It was emitted as microwaves in the first place","Expansion has stretched the wavelengths hugely","Dust has absorbed away the visible component","It has cooled from thousands of kelvin to three"]'::jsonb, '{1,3}'::smallint[], 'The glow started at a few thousand kelvin, roughly the colour of a dim star, and expansion stretched it by a factor of about a thousand. What we detect is that same light, cooled to 2.7 kelvin.', 1::smallint),
  ('the-cosmic-microwave-background', 'How was it discovered?', '["By a satellite built specifically to look for it","In a deliberate search for the Big Bang''s echo","As unexplained noise in a large radio antenna","By two engineers who first suspected pigeons"]'::jsonb, '{2,3}'::smallint[], 'Penzias and Wilson were trying to eliminate persistent noise, including cleaning out the antenna, before learning that a nearby group had predicted exactly such a signal. Satellites came later to map it in detail.', 2::smallint),
  ('the-cosmic-microwave-background', 'What do the tiny temperature variations in the map represent?', '["Regions that seem to follow different physical laws","The seeds that later grew into galaxies and clusters","Slight density differences in the early universe","Errors introduced by the measuring instruments"]'::jsonb, '{1,2}'::smallint[], 'The variations are about one part in a hundred thousand and mark where matter was slightly denser, which gravity then amplified over billions of years. Everything we see today grew from that faint pattern.', 3::smallint),
  ('the-cosmic-microwave-background', 'In what sense could you once see it on a television?', '["The whole snow pattern was cosmic in its origin","Sets connected to an aerial were able to pick it up","A small part of analogue static came from this glow","The picture would have been much sharper without it"]'::jsonb, '{2}'::smallint[], 'A few per cent of the static on an untuned analogue set really was the early universe, with the rest terrestrial and thermal noise. The claim is true but routinely overstated into the whole screen being cosmic.', 4::smallint),
  ('the-light-year', 'What is a light year?', '["A very long period of time in astronomy","The time light takes to cross the galaxy","A distance of some 9.5 million kilometres away","The distance that light travels in one year"]'::jsonb, '{3}'::smallint[], 'Despite the word year in the name it is purely a distance, roughly 9.5 trillion kilometres. The unit''s name is the single most reliable source of confusion in popular astronomy.', 0::smallint),
  ('the-light-year', 'A star is 500 light years away. What follows?', '["We are seeing it as it was some 500 years ago","It takes 500 years to travel there at any speed","Its light set out before Galileo was even born","It might already have exploded without our knowing"]'::jsonb, '{0,2,3}'::smallint[], 'Distance in light years is also a delay in news: everything we observe is history. The travel time depends on your speed, and 500 years is only the minimum, achievable at light speed alone.', 1::smallint),
  ('the-light-year', 'Which of these is also a distance rather than a duration?', '["A light second, about 300,000 km","A sidereal year, used for orbits","An astronomical unit, written AU","A parsec, from stellar parallax"]'::jsonb, '{0,2,3}'::smallint[], 'Parsecs, astronomical units and light seconds all measure how far, and the Moon is about 1.3 light seconds away. A sidereal year is a genuine period of time.', 2::smallint),
  ('the-light-year', 'Why do astronomers use light years and parsecs at all?', '["They avoid having to convert between different units","A parsec follows naturally from parallax measurement","They can be measured directly with a single instrument","They are far more precise than the metric system"]'::jsonb, '{1}'::smallint[], 'A parsec is defined by the parallax angle a star shows as Earth moves around the Sun, so the unit falls straight out of how the distance is measured. Nothing about it removes conversions or makes measurement a single step.', 3::smallint),
  ('the-light-year', 'The nearest star system is 4.2 light years away. What does that mean?', '["It is the nearest star system to our own Sun","A probe at one per cent of light speed needs centuries","A reply to any signal takes 8.4 years at least","We are seeing it almost exactly as it is at the moment"]'::jsonb, '{0,1,2}'::smallint[], 'Even our nearest neighbour imposes a multi-year round trip on any conversation and centuries on any realistic probe. Four years of delay is small by astronomical standards but is not the same as seeing it live.', 4::smallint),
  ('dark-matter', 'What observation first pointed to dark matter?', '["Distant galaxies appear redder than they should","Galaxies rotate too fast at their edges to hold","Some galaxies emit no visible light of any kind","Some regions of the sky appear completely black"]'::jsonb, '{1}'::smallint[], 'Stars at the edges of galaxies orbit far too fast for the visible mass to hold them, which was the first clear signal. Dark matter is dark because it does not interact with light, not because anything looks like a dark patch.', 0::smallint),
  ('dark-matter', 'What is known about dark matter?', '["It does not emit or absorb light of any kind","It outweighs ordinary matter roughly five to one","It has been detected directly in laboratories","It clumps under gravity like ordinary matter"]'::jsonb, '{0,1,3}'::smallint[], 'We know its gravitational behaviour and its abundance quite precisely, and it forms the scaffolding galaxies grew in. Decades of increasingly sensitive direct-detection experiments have found nothing, which is the open wound of the field.', 1::smallint),
  ('dark-matter', 'Which explanations have been ruled out or made unlikely?', '["Black holes present in large enough numbers","Neutrinos of the kinds we already know about","Faint ordinary matter, like gas and dead stars","A new particle that interacts extremely weakly"]'::jsonb, '{0,1,2}'::smallint[], 'Faint ordinary matter is limited by the abundance of light elements, black holes are constrained by lensing surveys, and known neutrinos move too fast to clump properly. An undiscovered weakly interacting particle remains the leading candidate.', 2::smallint),
  ('dark-matter', 'What is the main alternative to a dark matter particle?', '["Adding a fifth fundamental force between stars","Accepting that galaxies are simply flying apart","Modifying the law of gravity at low accelerations","Assuming that our distance measurements are wrong"]'::jsonb, '{2}'::smallint[], 'Modified gravity theories change the force law rather than adding mass, and they do fit individual galaxy rotation curves well. They struggle with clusters and with the cosmic microwave background, which is why most cosmologists still prefer a particle.', 3::smallint),
  ('dark-matter', 'Why is the Bullet Cluster considered strong evidence?', '["The mass followed the galaxies, not the hot gas","The visible gas and the gravitational mass separate","It shows dark matter emitting a very faint visible glow","It disproves modified gravity once and for good"]'::jsonb, '{0,1}'::smallint[], 'In this collision the hot gas, which is most of the ordinary matter, was slowed while the gravitational mass carried straight on with the galaxies. That is hard to explain by modifying gravity, though proponents dispute how fatal it is.', 4::smallint),
  ('heisenbergs-uncertainty-principle', 'What does the uncertainty principle actually state?', '["Our instruments are simply not yet precise enough","Position and momentum cannot both be sharply defined","The limit can be beaten by a gentle enough measurement","Observing a particle disturbs it and hides the values"]'::jsonb, '{1}'::smallint[], 'A particle does not possess exact values of both quantities waiting to be found, so the limit is a property of nature rather than of instruments. Measuring more gently does not help, which is why the disturbance story is now regarded as misleading.', 0::smallint),
  ('heisenbergs-uncertainty-principle', 'Which pairs of quantities obey such a relation?', '["Energy and the time it is measured over","Two components of the same angular momentum","The position and momentum of a particle","The mass and the charge of a particle"]'::jsonb, '{0,1,2}'::smallint[], 'Conjugate pairs, including energy and time and different spin components, obey the same kind of trade-off. Mass and charge are not conjugate and can be known together exactly.', 1::smallint),
  ('heisenbergs-uncertainty-principle', 'Where does the principle come from mathematically?', '["A general property of waves, seen in sound too","The random motion of particles at small scales","The impossibility of building a perfect detector","The finite speed at which light can travel"]'::jsonb, '{0}'::smallint[], 'A wave with a definite frequency must be spread out in time, and a sharp pulse must contain many frequencies, a trade-off classical signal analysis knows well. Quantum mechanics attaches that mathematics to particles; it does not add extra randomness underneath.', 2::smallint),
  ('heisenbergs-uncertainty-principle', 'What real consequences follow from it?', '["The vacuum shows measurable fluctuation effects","Particles can tunnel straight through barriers","Nothing can ever be measured with real accuracy","Atoms have a minimum size and do not collapse"]'::jsonb, '{0,1,3}'::smallint[], 'Confining an electron more tightly raises its momentum spread, which is what keeps atoms from collapsing, and the same relation underlies tunnelling and vacuum energy effects. Individual quantities can still be measured to extraordinary precision, just not both at once.', 3::smallint),
  ('heisenbergs-uncertainty-principle', 'How is the principle most often misused?', '["As a statement about very small objects alone","As a claim that observers create reality by looking","As support for the idea that anything is possible","As a limit on knowing two conjugate quantities at once"]'::jsonb, '{0,1,2}'::smallint[], 'The relation applies to everything, but the numbers are so small that macroscopic objects are unaffected, so it is not a rule for small things alone. It constrains what can be defined, which is far narrower than the philosophical claims often hung on it.', 4::smallint),
  ('entropy', 'What is the best description of entropy?', '["The tendency of things to break down over time","A count of the arrangements that look identical","A measure of how much energy a system holds","The amount of disorder or mess in a system"]'::jsonb, '{1}'::smallint[], 'Entropy counts the microscopic arrangements consistent with what you can observe from outside. Disorder is a loose analogy that breaks down on cases like crystallisation, and total energy is a different quantity altogether.', 0::smallint),
  ('entropy', 'Why does entropy connect to the direction of time?', '["High-entropy states are overwhelmingly more numerous","The universe began in a very low-entropy state","Time is defined as the direction in which entropy grows","Most physical laws work equally well run backwards"]'::jsonb, '{0,1,3}'::smallint[], 'The fundamental laws are time-symmetric, so the arrow has to come from statistics plus a special starting condition. There are simply vastly more ways to be disordered, and the early universe was unusually ordered.', 1::smallint),
  ('entropy', 'Does entropy ever decrease locally?', '["Yes, if entropy elsewhere increases by more","No, that would violate the second law outright","Just in systems smaller than a single molecule","Yes, that is how a fridge or a living body works"]'::jsonb, '{0,3}'::smallint[], 'The second law applies to closed systems, so any local decrease is paid for with a larger increase outside. Refrigerators and organisms are the everyday demonstrations of the accounting.', 2::smallint),
  ('entropy', 'Why can''t you unscramble an egg?', '["The laws of physics forbid the reverse process","Energy itself would have to flow backwards through time","The ordered state is one of an astronomical number","The reverse would need more energy than exists"]'::jsonb, '{2}'::smallint[], 'Nothing in the microscopic laws forbids unscrambling; the ordered arrangement is simply one among an astronomical number, so it never happens by chance. Energy is not the obstacle, which is why the impossibility is practical rather than fundamental.', 3::smallint),
  ('entropy', 'What is heat death?', '["Matter collapsing back in on itself once again","The universe growing extremely hot everywhere","The universe reaching its maximum entropy","A state where no usable energy gradients are left"]'::jsonb, '{2,3}'::smallint[], 'Heat death is uniformity, not high temperature: everything at the same energy level, with no differences left to drive any process. The name misleads almost everyone who meets it for the first time.', 4::smallint),
  ('is-space-cold', 'Why is calling space ''cold'' misleading?', '["Space sits at exactly absolute zero throughout","The vacuum has a fixed temperature of about 2.7 kelvin","Space is actually rather warm near the stars","Temperature describes particles, and there are few"]'::jsonb, '{3}'::smallint[], 'Temperature is a property of matter, and a near-vacuum has too little of it to feel like anything. The 2.7 kelvin figure describes the background radiation, not a cold substance you could touch.', 0::smallint),
  ('is-space-cold', 'How does an object in space actually lose heat?', '["By radiating its infrared away into space","By conduction into the surrounding vacuum","By convection out into the surrounding space","By radiation, as other routes need a medium"]'::jsonb, '{0,3}'::smallint[], 'Conduction and convection both need something to touch or to flow, which leaves radiation as the only channel. Radiation is slow, which is why overheating rather than freezing is the standard engineering problem in orbit.', 1::smallint),
  ('is-space-cold', 'What is the bigger thermal problem for a spacecraft?', '["Huge differences between sunlit and shadowed sides","Keeping the crew from slowly freezing on board","Getting rid of waste heat from gear and sunlight","The vacuum drawing the heat out far too quickly"]'::jsonb, '{0,2}'::smallint[], 'Spacecraft carry large radiators precisely because dumping heat is hard, and the sunlit and shaded faces can differ by hundreds of degrees. The station''s cooling loops are a much bigger system than its heaters.', 2::smallint),
  ('is-space-cold', 'What would actually happen to an unprotected human in vacuum?', '["They would freeze solid within a few seconds","The blood would boil away almost instantly","The body would be crushed by the pressure drop","Consciousness would be lost in fifteen seconds"]'::jsonb, '{3}'::smallint[], 'The immediate dangers are lack of oxygen and expanding gas, with unconsciousness in roughly fifteen seconds. One atmosphere of pressure difference is not enough to crush anyone, and freezing would take a long time.', 3::smallint),
  ('is-space-cold', 'Why must a thermos flask have a vacuum gap?', '["The silvered surface reduces heat lost by radiation","It is the same principle as insulating a spacecraft","The vacuum blocks conduction and convection","The vacuum is much colder than the surrounding space"]'::jsonb, '{0,1,2}'::smallint[], 'Removing the medium kills two of the three heat paths, and the mirror finish attacks the third. A thermos is a small model of the thermal problem every spacecraft faces.', 4::smallint),
  ('the-doppler-effect', 'Why does an ambulance change pitch as it passes?', '["The siren is turned down as the van drives away","The sound gets quieter, which we hear as lower","The siren automatically lowers its own pitch","Sound waves bunch ahead of it and stretch behind"]'::jsonb, '{3}'::smallint[], 'Motion compresses the waves in front and stretches them behind, so the frequency reaching your ear changes while the siren stays exactly the same. Loudness and pitch are separate, which is why a fading sound does not drop in pitch.', 0::smallint),
  ('the-doppler-effect', 'What does the driver of the ambulance hear?', '["A constant, unchanging pitch throughout","A higher pitch than the bystanders can hear","The same shift that the bystanders hear","No shift, as there is no relative motion"]'::jsonb, '{0,3}'::smallint[], 'The effect depends entirely on relative motion between source and receiver, and the driver moves with the siren. That is the cleanest way to see that the sound itself is unchanged.', 1::smallint),
  ('the-doppler-effect', 'Where is the effect used in practice?', '["Measuring blood flow with medical ultrasound","Speed cameras and hand-held radar guns","Detecting exoplanets by their stellar wobble","Measuring the distance to the Moon by laser"]'::jsonb, '{0,1,2}'::smallint[], 'Radar, medical ultrasound and radial-velocity planet hunting all read speed from frequency shifts. Lunar laser ranging measures a round-trip time instead, which is timing rather than Doppler.', 2::smallint),
  ('the-doppler-effect', 'How does the effect differ for light compared with sound?', '["Light shows no measurable Doppler effect of any kind","The shift for light also depends on time dilation","Only relative velocity matters for light waves","For light there is no medium and no absolute frame"]'::jsonb, '{1,2,3}'::smallint[], 'Sound has a medium, so motion of the source and of the observer give slightly different results, while for light only the relative velocity counts and relativity adds a transverse term. Light very much shows the effect, which is how we measure stellar motion.', 3::smallint),
  ('the-doppler-effect', 'A star''s spectral lines shift back and forth every few days. What holds?', '["The star is rotating rapidly on its own axis","Something is orbiting it and tugging it about","The star is changing temperature periodically","The star is pulsing steadily in brightness"]'::jsonb, '{1}'::smallint[], 'A periodic wobble along our line of sight is the classic signature of an unseen companion pulling the star around their shared centre of mass. Rotation broadens spectral lines rather than shifting them back and forth.', 4::smallint),
  ('kessler-syndrome', 'What does Kessler syndrome describe?', '["Collisions creating debris that causes more collisions","Interference between the satellites'' radio signals","Satellites falling out of orbit onto populated areas","A single collision destroying an entire orbital shell"]'::jsonb, '{0}'::smallint[], 'The scenario is a runaway chain reaction in which each collision multiplies the debris that causes the next. It is a cascade over years or decades, not one catastrophic event, and it threatens access to orbit rather than anyone on the ground.', 0::smallint),
  ('kessler-syndrome', 'Why is a one-centimetre fragment dangerous?', '["It is far too small to be tracked from the ground","It can chemically dissolve most spacecraft materials","Closing speeds can exceed ten kilometres per second","The kinetic energy is comparable to a hand grenade"]'::jsonb, '{0,2,3}'::smallint[], 'Energy scales with the square of speed, so even a fleck carries enormous punch, and objects this small mostly fall below tracking thresholds. There is no chemical mechanism involved.', 1::smallint),
  ('kessler-syndrome', 'Which events have made the problem substantially worse?', '["A collision between Iridium and Cosmos satellites","Several later tests of anti-satellite weapons","The loss of a space shuttle high above the Earth","A Chinese anti-satellite weapon test in 2007"]'::jsonb, '{0,1,3}'::smallint[], 'Deliberate destruction tests and the 2009 accidental collision each added thousands of trackable fragments in long-lived orbits. Shuttle losses were tragedies, but they did not seed debris clouds at those altitudes.', 2::smallint),
  ('kessler-syndrome', 'Why do lower orbits pose less of a long-term risk?', '["Collisions are simply impossible below a certain height","Debris there is much easier to track and avoid","Far fewer satellites are placed at that height","Residual atmosphere drags debris down within years"]'::jsonb, '{3}'::smallint[], 'Thin atmosphere at low altitude drags fragments down within years, acting as a slow self-cleaning mechanism. Tracking is no easier down there, and low orbits are in fact the most crowded, which is why the drag matters so much.', 3::smallint),
  ('kessler-syndrome', 'What are the proposed responses?', '["Better tracking and collision avoidance manoeuvres","Requiring satellites to deorbit at end of life","Pushing debris to higher orbits to clear the way","Active removal missions with nets or harpoons"]'::jsonb, '{0,1,3}'::smallint[], 'Prevention, removal and avoidance are the three practical strands, and disposal rules are already being tightened. Raising debris only moves it into orbits where it survives longer.', 4::smallint),
  ('why-rockets-do-not-fly-straight-up', 'What actually puts a spacecraft into orbit?', '["Reaching a sufficiently great altitude quickly","Reaching a sufficiently great sideways speed","Reaching the point where gravity is negligible","Escaping the atmosphere of the Earth entirely"]'::jsonb, '{1}'::smallint[], 'Orbit is a speed problem: about 7.8 kilometres per second sideways turns a fall into an orbit. Gravity at orbital altitude is nearly as strong as on the ground, so there is no height at which it stops mattering.', 0::smallint),
  ('why-rockets-do-not-fly-straight-up', 'What is the gravity turn and why is it used?', '["It converts vertical climb into horizontal speed","It is a safety manoeuvre to avoid populated areas","It keeps the vehicle aligned with the air flow","The rocket pitches over gradually after launch"]'::jsonb, '{0,2,3}'::smallint[], 'Tilting early and letting gravity do the steering avoids wasting fuel fighting the vehicle''s own structure and the air. The trajectory looks like an arc because that is the cheapest path to sideways speed.', 1::smallint),
  ('why-rockets-do-not-fly-straight-up', 'A rocket goes straight up and stops at 200 kilometres. What happens?', '["It drifts sideways into a slow low orbit","It stays up there as gravity is negligible","It falls straight back down to the ground","It enters a stable orbit around the Earth"]'::jsonb, '{2}'::smallint[], 'With no sideways speed the vehicle simply comes back down, which is exactly what a suborbital hop is. Crossing the boundary of space and staying there are two completely different achievements.', 2::smallint),
  ('why-rockets-do-not-fly-straight-up', 'Why do most launch sites sit near the equator and fire eastwards?', '["Earth''s rotation donates hundreds of metres a second","It reduces the sideways speed the rocket must supply","The atmosphere is considerably thinner at the equator","The weather near the equator is more predictable"]'::jsonb, '{0,1}'::smallint[], 'The ground itself is already moving east at nearly half a kilometre per second at the equator, and the rocket keeps that for free. Since orbit is a speed problem, anything that donates speed is worth a great deal.', 3::smallint),
  ('why-rockets-do-not-fly-straight-up', 'Why does reaching orbit cost so much more than reaching space?', '["Suborbital flight needs only a fraction of the velocity","Orbital speed needs many times the energy of the climb","Orbital vehicles must also survive re-entry heating","The atmosphere is much harder to cross than people expect"]'::jsonb, '{0,1,2}'::smallint[], 'The kinetic energy of orbital velocity dwarfs the potential energy of the altitude, and coming back from that speed means shedding it as heat. The atmosphere is a nuisance, but it is not the dominant cost.', 4::smallint),
  ('the-roche-limit', 'What is the Roche limit?', '["The boundary of a planet''s gravitational influence","The distance inside which tidal forces tear a body apart","The distance at which a moon stops orbiting entirely","The closest orbit that is not affected by atmosphere"]'::jsonb, '{1}'::smallint[], 'Inside the limit, the difference in gravitational pull across a body exceeds the body''s own self-gravity and it comes apart. Orbiting continues perfectly well inside it; what fails is the body''s ability to hold together.', 0::smallint),
  ('the-roche-limit', 'What does the Roche limit help explain about rings?', '["Ring material usually predates the planet''s formation","Ring material cannot coalesce into a single moon","Rings sit inside the limit and moons outside it","A moon straying too close can be shredded to a ring"]'::jsonb, '{1,2,3}'::smallint[], 'The limit acts as a boundary: inside it, tides prevent lumps from gathering, so debris stays a ring. Ring material can be primordial or the remains of a destroyed body, and both are consistent with the picture.', 1::smallint),
  ('the-roche-limit', 'What does the limit depend on?', '["The colour and composition of the surface","The densities of the two bodies involved","The orbital speed of the smaller body alone","The total mass of the smaller body by itself"]'::jsonb, '{1}'::smallint[], 'The comparison is between the tidal stretch and the body''s own binding, so the densities of both bodies set the limit. Surface appearance tells you nothing about how tightly the interior is held together.', 2::smallint),
  ('the-roche-limit', 'Why does a spacecraft not break up when it orbits close to a planet?', '["The limit assumes a body held by its own gravity","It orbits far too fast for tidal forces to act","Its mass is far too small to feel tidal forces","It is held by material strength, not self-gravity"]'::jsonb, '{0,3}'::smallint[], 'The standard limit assumes a body held together only by gravity, which is a fair model for a large moon and useless for a bolted structure. Tidal forces still act on a spacecraft, they are simply far weaker than its bolts.', 3::smallint),
  ('the-roche-limit', 'Comet Shoemaker-Levy 9 broke apart before hitting Jupiter. What holds?', '["It was torn apart by Jupiter''s own atmospheric drag","The fragments then struck the planet in a chain","It had passed inside Jupiter''s own Roche limit","It was a loosely bound body with little strength"]'::jsonb, '{1,2,3}'::smallint[], 'A close approach in 1992 tore the fragile comet into a train of pieces that struck the planet two years later. Break-up happened well outside the atmosphere, which is why the fragments arrived in sequence.', 4::smallint),
  ('antimatter', 'What is antimatter?', '["Ordinary matter travelling backwards in time","Matter that carries a negative amount of mass","Particles with the same mass but opposite charge","A purely theoretical construct, not yet observed"]'::jsonb, '{2}'::smallint[], 'An antiparticle matches its partner''s mass and reverses charge and certain other quantum numbers. The backwards-in-time picture is a calculational device in particle physics, not a description of what antimatter is.', 0::smallint),
  ('antimatter', 'What happens when matter and antimatter meet?', '["They cancel out and leave nothing behind them","The reaction is far more efficient than fission","The energy released equals mass times c squared","They annihilate one another into pure energy"]'::jsonb, '{1,2,3}'::smallint[], 'The entire rest mass converts to energy, mostly as gamma rays, which is orders of magnitude beyond fission or fusion. Nothing vanishes: energy is conserved, and it leaves as radiation.', 1::smallint),
  ('antimatter', 'What is the puzzle of baryon asymmetry?', '["The Big Bang should have made equal amounts of both","Antimatter is hidden in distant parts of the universe","A tiny early imbalance left behind the matter we see","Almost nothing but ordinary matter survives today"]'::jsonb, '{0,2,3}'::smallint[], 'Symmetric production should have annihilated everything, so a small excess of matter must have existed, and we are its leftovers. Searches for antimatter regions find no sign of the boundaries such regions would produce.', 2::smallint),
  ('antimatter', 'Where does antimatter appear outside particle accelerators?', '["In the decay of ordinary uranium metal","In the light given off by the Sun itself","In medical PET scanning of patients","In ordinary everyday chemical reactions"]'::jsonb, '{2}'::smallint[], 'Positrons from beta-plus decay are used routinely in PET imaging, which is antimatter at work in a hospital. Only some decays produce it, and sunlight is ordinary electromagnetic radiation containing none.', 3::smallint),
  ('antimatter', 'Why is antimatter not a practical fuel?', '["Global production amounts to tiny fractions of a gram","It can slowly decay back into ordinary matter in seconds","It cannot be stored inside ordinary containers","Producing it costs vastly more energy than it releases"]'::jsonb, '{0,2,3}'::smallint[], 'It is an energy store, not a source, and an extraordinarily inefficient one to fill, with storage requiring magnetic traps in vacuum. Antimatter does not decay into matter; it simply annihilates on contact.', 4::smallint),
  ('the-twin-paradox', 'One twin travels at high speed and returns. What is true?', '["The traveller''s clocks changed, but not their body","Both have aged the same, since motion is relative","The traveller has aged less than the other twin","The difference vanishes once they are together again"]'::jsonb, '{2}'::smallint[], 'The returning twin is genuinely younger, and the gap is permanent once the journey ends. Every process ages at the same rate, so biology tracks the clocks exactly rather than snapping back.', 0::smallint),
  ('the-twin-paradox', 'Why is the situation not symmetric between the two twins?', '["The Earth twin is truly at rest in the universe","Only the traveller switches between the frames","The traveller changes direction and feels the push","The traveller''s path through spacetime is shorter"]'::jsonb, '{1,2,3}'::smallint[], 'The turnaround breaks the symmetry: only one twin experiences acceleration and changes reference frames. There is no absolute rest frame, so the asymmetry cannot come from the Earth being ''really'' stationary.', 1::smallint),
  ('the-twin-paradox', 'In what sense is it not really a paradox?', '["It remains untested by any real experiment up to now","It seems paradoxical only if you assume symmetry","The contradiction rests on ignoring the turnaround","Relativity gives one single unambiguous answer"]'::jsonb, '{1,2,3}'::smallint[], 'The theory predicts a single definite outcome once you account for the change of frame. Flown atomic clocks and particle lifetimes confirm it, so it is settled experimentally as well.', 2::smallint),
  ('the-twin-paradox', 'What has actually been measured that supports this?', '["Atomic clocks flown around the world","Clock differences aboard the space station","Astronauts visibly ageing more slowly","Muons living longer when moving fast"]'::jsonb, '{0,1,3}'::smallint[], 'Flown clocks, particle lifetimes and orbital clock rates all match prediction to high precision. The effect on astronauts is real but measured in milliseconds over months, so nothing is visible.', 3::smallint),
  ('the-twin-paradox', 'A trip at 99 per cent of light speed lasts ten ship years. What holds?', '["The traveller returns to the same year they left","About ten years pass on Earth as well as on ship","The traveller feels the journey pass in slow motion","About seventy years pass on Earth in the meantime"]'::jsonb, '{3}'::smallint[], 'At 99 per cent of light speed the time factor is roughly seven, so a decade aboard corresponds to about seventy years at home. Nothing feels slow to the traveller, whose own experience is entirely normal.', 4::smallint),
  ('where-heavy-elements-come-from', 'Where were the atoms in your body made?', '["Carbon and oxygen were forged deep inside stars","The heavier elements were formed during the Big Bang","Hydrogen dates from the universe''s first minutes","Iron came from massive stars and their explosions"]'::jsonb, '{0,2,3}'::smallint[], 'The Big Bang made hydrogen, helium and traces of lithium, and everything heavier was built later by stars. That is why the phrase about being made of star stuff is literally accurate for most of your mass.', 0::smallint),
  ('where-heavy-elements-come-from', 'Why does normal stellar fusion stop at iron?', '["Stars run out of fuel long before reaching iron","Iron nuclei are simply far too large to collide","Iron is the heaviest element found inside a star","Fusing beyond iron consumes energy, not releases it"]'::jsonb, '{3}'::smallint[], 'Binding energy per nucleon peaks at iron, so fusing past it consumes energy instead of releasing it and cannot sustain a star. Heavier elements do exist in stars; they are just made by neutron capture rather than fusion.', 1::smallint),
  ('where-heavy-elements-come-from', 'How are elements heavier than iron produced?', '["By rapid neutron capture during violent events","In mergers between a pair of neutron stars","By slow neutron capture inside ageing stars","By ordinary fusion in the cores of large stars"]'::jsonb, '{0,1,2}'::smallint[], 'Heavy elements are built by soaking nuclei in neutrons, either slowly over thousands of years in red giants or in seconds during violent events. Ordinary fusion cannot climb past iron, which is why neutron capture is needed.', 2::smallint),
  ('where-heavy-elements-come-from', 'What did the 2017 neutron star merger confirm?', '["Gold and platinum have a plausible cosmic source","Gravitational waves and light can be observed together","Supernovae can play no part in making the heavy elements","Such mergers produce large amounts of heavy elements"]'::jsonb, '{0,1,3}'::smallint[], 'The event was seen in gravitational waves and across the spectrum, and its afterglow carried the signature of freshly made heavy elements. It weakened rather than confirmed the idea that supernovae alone do this job.', 3::smallint),
  ('where-heavy-elements-come-from', 'What follows from this for the composition of the Earth?', '["The Sun is at least a second generation star","Heavy elements are still being made inside the Earth","Earth''s heavy elements formed after the Sun did","Our solar system formed from primordial gas alone"]'::jsonb, '{0}'::smallint[], 'A rocky planet needs elements that only earlier generations of stars could have made, so the Sun is at least a second-generation star. Those elements were made before the solar system existed, not inside it.', 4::smallint),
  ('schroedingers-cat', 'What was Schrödinger''s original purpose in describing the cat?', '["To ridicule an interpretation he found unacceptable","To illustrate how strange quantum superposition is","To demonstrate that the cat is genuinely both at once","To prove that observation itself creates reality"]'::jsonb, '{0}'::smallint[], 'Schrödinger intended a reduction to absurdity aimed at an interpretation he rejected. Today the story is routinely quoted as though he were endorsing the very picture he was mocking.', 0::smallint),
  ('schroedingers-cat', 'What does the thought experiment actually connect?', '["A radioactive decay to a device that kills the cat","A microscopic random event to a macroscopic outcome","Two entangled particles held far apart in space","Human consciousness to the world''s physical reality"]'::jsonb, '{0,1}'::smallint[], 'The device chains an undecided quantum event to an unmistakably classical consequence, which is the whole point. Consciousness enters only in some interpretations and is not part of the setup.', 1::smallint),
  ('schroedingers-cat', 'What does decoherence contribute to the puzzle?', '["It explains why cat-sized superpositions are unseen","Contact with the environment destroys superposition","Large objects lose quantum behaviour almost instantly","It proves the cat is alive throughout the whole time"]'::jsonb, '{0,1,2}'::smallint[], 'A system entangled with countless air molecules and photons stops showing interference far faster than any measurement could occur. Decoherence explains the absence of the effect without settling what happens at the moment of measurement.', 2::smallint),
  ('schroedingers-cat', 'How is the story most commonly misused?', '["As a metaphor for any sort of undecided situation","As a claim that merely looking changes the world","As evidence that quantum theory endorses the paradox","As a pointer to a genuine, unsolved measurement problem"]'::jsonb, '{0,1,2}'::smallint[], 'The cat became shorthand for anything indeterminate and for a mystical role for observers, neither of which Schrödinger intended. The measurement problem it points at, however, is real and still open.', 3::smallint),
  ('schroedingers-cat', 'Have superpositions been demonstrated on larger objects?', '["No, nothing larger than an atom has shown it","Yes, with objects large enough to see unaided","Yes, with molecules containing thousands of atoms","Yes, with living cats under laboratory conditions"]'::jsonb, '{2}'::smallint[], 'Interference has been demonstrated for molecules containing thousands of atoms, pushing the boundary steadily upwards. Nothing visible to the naked eye has been put into a superposition, and decoherence makes anything animal-sized unimaginable.', 4::smallint),
  ('the-planck-length', 'What is the Planck length?', '["A scale derived from the size of a nucleus","The size of the smallest known particle","About 1.6 times ten to the minus 35 metres","The pixel size of the observable universe"]'::jsonb, '{2}'::smallint[], 'It falls out of combining gravity, quantum theory and the speed of light into a quantity with units of length, about twenty orders of magnitude below a proton. It is not measured from anything, and calling it a pixel imports a picture the physics does not supply.', 0::smallint),
  ('the-planck-length', 'What does the Planck scale actually mark?', '["Where gravity and quantum effects both matter","A proven minimum distance existing in nature","Where relativity has been confirmed by experiment","The limit of what any experiment might ever probe"]'::jsonb, '{0}'::smallint[], 'The scale marks where general relativity and quantum mechanics can no longer be used separately, so we simply do not know what happens there. It is the frontier of the theories, not a place where either has been tested.', 1::smallint),
  ('the-planck-length', 'Why can we not probe the Planck scale experimentally?', '["Smaller distances need higher energies to resolve","It would take a machine of truly astronomical size","The instruments themselves would simply be destroyed","The energy needed is beyond any conceivable machine"]'::jsonb, '{0,1,3}'::smallint[], 'Resolution scales with energy, and reaching Planck energies would require a collider of roughly galactic dimensions. It is a limit of practicality and physics, not of instrument durability.', 2::smallint),
  ('the-planck-length', 'Which other Planck units exist?', '["Planck charge, which equals that of an electron","Planck mass, about the weight of a speck of dust","Planck temperature, around ten to the 32 kelvin","Planck time, light crossing a single Planck length"]'::jsonb, '{1,2,3}'::smallint[], 'The system builds time, mass and temperature from the same constants, and the mass is famously the one that lands at a human-visible scale. A Planck charge exists as a unit but is not equal to the electron''s charge.', 3::smallint),
  ('the-planck-length', 'What role does the scale play in current theory?', '["It is used as a natural unit system in theoretical work","It is where a theory of quantum gravity is needed","It sets the resolution limit of astronomical observation","Some approaches suggest spacetime is not smooth there"]'::jsonb, '{0,1,3}'::smallint[], 'It marks the target for quantum gravity and serves as the natural unit system for that work, with some approaches predicting a granular spacetime. It has no bearing whatsoever on telescope resolution.', 4::smallint),
  ('solar-sails-and-light-pressure', 'How can light push a sail if photons have no rest mass?', '["The heat of the light provides the actual push","Photons turn out to carry a tiny rest mass","Photons gain mass at the moment of absorption","Photons still carry momentum of their own"]'::jsonb, '{3}'::smallint[], 'A photon''s momentum is its energy divided by the speed of light, which is nonzero even with no rest mass. Reflecting the light reverses that momentum and pushes the sail; no mass is gained anywhere.', 0::smallint),
  ('solar-sails-and-light-pressure', 'Why is a reflective sail better than a black one?', '["A black sail receives no push from the light","A black sail absorbs and gets one unit of momentum","Reflection avoids heating the sail quite so much","Reflection reverses momentum, doubling the push"]'::jsonb, '{1,2,3}'::smallint[], 'Absorbing gives you the incoming momentum once, while reflecting takes it in and sends it back, for nearly twice the effect. Absorption also dumps the energy as heat, which a thin film has to survive.', 1::smallint),
  ('solar-sails-and-light-pressure', 'What is the practical character of solar sail propulsion?', '["High thrust delivered in a number of short bursts","Very low thrust, but continuous and without fuel","Acceleration builds up over months and years","It works far better closer in towards the Sun"]'::jsonb, '{1,2,3}'::smallint[], 'The pressure is minuscule, but with no propellant to run out it can accumulate indefinitely, and it grows as you approach the Sun. Nothing about it resembles a burst of thrust.', 2::smallint),
  ('solar-sails-and-light-pressure', 'Which missions have actually flown solar sails?', '["The two Voyager probes to the outer planets","IKAROS, which sailed towards Venus in 2010","The New Horizons probe on its way to Pluto","The Parker Solar Probe close to the Sun"]'::jsonb, '{1}'::smallint[], 'Japan''s IKAROS was the first spacecraft to demonstrate controlled thrust from sunlight on an interplanetary trajectory. The other missions listed used conventional propulsion and gravity assists.', 3::smallint),
  ('solar-sails-and-light-pressure', 'What else shows that light exerts pressure?', '["Optical tweezers hold particles with laser beams","Sunlight feels distinctly warm on your bare skin","Spacecraft trajectories drift measurably in sunlight","Comet dust tails always point away from the Sun"]'::jsonb, '{0,2,3}'::smallint[], 'Comet dust tails, radiation-pressure corrections in navigation and laser trapping in laboratories all demonstrate the force directly. Warmth is energy transfer, which is a different quantity from momentum.', 4::smallint),
  ('neutrinos', 'What is true of neutrinos passing through you?', '["Almost none of them interact with your atoms","They are stopped high up in the upper atmosphere","They would pass through a light year of lead","Trillions pass through your body every second"]'::jsonb, '{0,2,3}'::smallint[], 'Neutrinos interact only via the weak force, so ordinary matter is effectively transparent to them. Nothing about the atmosphere slows them, which is why detectors have to be buried, not shielded.', 0::smallint),
  ('neutrinos', 'Why are neutrino detectors built deep underground?', '["Rock blocks neutrinos from unwanted directions","Rock filters out cosmic rays and other background","Neutrinos are easier to detect at high pressure","Detectors must be kept at a constant temperature"]'::jsonb, '{1}'::smallint[], 'The rock overhead removes cosmic rays and other background while neutrinos pass through it unhindered. It is shielding against noise, not against the particles being studied.', 1::smallint),
  ('neutrinos', 'What was the solar neutrino problem?', '["It was resolved by neutrinos changing type in flight","The Sun appeared to be producing no neutrinos","Far more neutrinos arrived than the Sun could produce","The models of the Sun turned out to be wrong"]'::jsonb, '{0}'::smallint[], 'Detectors sensitive to one flavour saw only about a third of the expected count, and the missing ones turned out to have oscillated into flavours those experiments could not see. Solar models were vindicated; particle physics had to change instead.', 2::smallint),
  ('neutrinos', 'What does neutrino oscillation imply?', '["Neutrinos must have a small but nonzero mass","Neutrinos travel a little slower than light","The Standard Model needed to be extended","Neutrinos can be created and destroyed at will"]'::jsonb, '{0,1,2}'::smallint[], 'Oscillation only works if the flavour states are mixtures of states with different masses, which means neutrinos are not massless and therefore not quite at light speed. The Standard Model originally assumed they were massless.', 3::smallint),
  ('neutrinos', 'Why are neutrinos useful for astronomy?', '["They can be focused using a set of very large mirrors","They escape directly from inside stellar cores","They arrive from a supernova before the light","They travel unblocked through dust and gas clouds"]'::jsonb, '{1,2,3}'::smallint[], 'Because they barely interact, they carry information straight out of regions light cannot leave, and they outrun the shockwave in a supernova. That same indifference to matter means they cannot be focused by anything.', 4::smallint),
  ('endosymbiotic-theory', 'What does endosymbiotic theory claim about mitochondria?', '["They descend from free-living bacteria taken inside a cell","They evolved gradually as folds of the cell membrane","They were acquired from viruses early in evolution","They were designed for energy production from the start"]'::jsonb, '{0}'::smallint[], 'The theory says an ancestral cell took in a bacterium that was never digested and became permanent. Viruses insert genes but do not become organelles, and membrane infolding is the rival hypothesis this replaced.', 0::smallint),
  ('endosymbiotic-theory', 'What evidence supports the theory?', '["They divide independently of the host cell","They carry their own loop of circular DNA","They have a double membrane around them","They can be removed and cultured on their own"]'::jsonb, '{0,1,2}'::smallint[], 'Their own bacteria-like genome, their independent division and their double membrane all point to a captured cell. They cannot live alone any more, because most of their genes have migrated to the nucleus.', 1::smallint),
  ('endosymbiotic-theory', 'Which other organelle has the same origin story?', '["The ribosome, which assembles proteins","The nucleus, which holds most of the DNA","The chloroplast, from a photosynthetic microbe","The Golgi apparatus, sorting proteins for export"]'::jsonb, '{2}'::smallint[], 'Chloroplasts came from cyanobacteria in a separate later event, and they show the same signatures. The nucleus and the Golgi are membrane systems of the host cell itself.', 2::smallint),
  ('endosymbiotic-theory', 'Why is mitochondrial DNA useful for tracing ancestry?', '["It is inherited only from the mother","It mutates at a fairly steady rate","It does not recombine between parents","It contains most of the cell''s genes"]'::jsonb, '{0,1,2}'::smallint[], 'A non-recombining, maternally inherited molecule gives a clean single-line record, which is why it underlies work on human maternal lineages. It is tiny, holding only a few dozen genes.', 3::smallint),
  ('endosymbiotic-theory', 'What does the theory suggest about the origins of complex life?', '["Complexity arose before the first cells existed","Cooperation matters as much as competition does","Bacteria and eukaryotes evolved entirely separately","A rare merger event may have been a key step"]'::jsonb, '{1,3}'::smallint[], 'The origin of complex cells looks less like slow improvement and more like a merger of separate lineages, which is biology''s strongest case that symbiosis drives major transitions. Eukaryotes are descended from that merger, so the lineages are anything but separate.', 4::smallint),
  ('trees-are-made-of-air', 'Where does most of a tree''s dry mass come from?', '["Carbon dioxide taken straight from the air","Minerals drawn up from the surrounding soil","Nutrients absorbed in through the roots","Sunlight, turned directly into solid mass"]'::jsonb, '{0}'::smallint[], 'The carbon skeleton of wood is built from atmospheric carbon dioxide, so most of a trunk is assembled out of thin air. Sunlight supplies the energy for the reaction but contributes no matter at all.', 0::smallint),
  ('trees-are-made-of-air', 'What is soil actually needed for?', '["Providing the carbon that becomes the tree''s wood","Anchoring the tree physically in the ground","Holding the water for the roots to take up","Supplying trace nutrients such as nitrogen"]'::jsonb, '{1,2,3}'::smallint[], 'Soil supplies water, minerals and support, all of which the tree needs. Carbon is the one thing it does not provide, which is the whole surprise.', 1::smallint),
  ('trees-are-made-of-air', 'Van Helmont grew a willow in weighed soil for five years. What did he find?', '["He correctly identified the air as the main source","The tree gained kilograms, the soil lost almost none","The soil lost exactly as much as the tree gained","The tree gained nothing that could be measured"]'::jsonb, '{1}'::smallint[], 'The willow gained about 75 kilograms while the soil lost only a few grams, which is the whole point of the experiment. Carbon dioxide had not yet been identified as a substance, so he concluded, wrongly, that water alone made the wood.', 2::smallint),
  ('trees-are-made-of-air', 'What follows for how forests affect the atmosphere?', '["Growing wood is simply stored atmospheric carbon","Mature forests absorb carbon at a constant rate","A tree''s mass is set mainly by available nutrients","Burning or rotting wood returns that carbon again"]'::jsonb, '{0,3}'::smallint[], 'Wood is essentially solidified carbon dioxide, so growth stores it and burning or decay releases it again. Nutrients limit how fast a tree grows but supply almost none of its mass.', 3::smallint),
  ('trees-are-made-of-air', 'Which everyday observation fits this picture?', '["A tree in a pot does not empty the pot of soil","Ash weighs far less than the wood it came from","A wood fire releases most of its mass as gas","Trees grow faster in noticeably heavier, richer soils"]'::jsonb, '{0,1,2}'::smallint[], 'Soil level barely moves as a tree grows, and burning sends most of the mass back into the air as gas. Soil weight has nothing to do with growth rate.', 4::smallint),
  ('the-amazon-is-not-the-lungs-of-the-earth', 'Why is ''lungs of the Earth'' a poor description of the Amazon?', '["It produces almost no oxygen of its own at any time","Its trees photosynthesise mainly in the dry season","Its net contribution to atmospheric oxygen is tiny","Lungs take in oxygen rather than producing any"]'::jsonb, '{2}'::smallint[], 'A mature forest is close to balance: the oxygen its plants produce is nearly all consumed again by respiration and decay, leaving a net contribution near zero. Photosynthesis runs year-round there, which is not the issue.', 0::smallint),
  ('the-amazon-is-not-the-lungs-of-the-earth', 'Where does most of the oxygen actually entering the atmosphere come from?', '["The world''s grasslands and croplands","Tropical rainforests around the equator","Phytoplankton drifting in the oceans","Ancient organic matter buried before decay"]'::jsonb, '{2,3}'::smallint[], 'Marine plankton drive about half of global photosynthesis, and the oxygen we breathe accumulated over hundreds of millions of years because some organic carbon got buried instead of rotting. Current forests are close to net neutral.', 1::smallint),
  ('the-amazon-is-not-the-lungs-of-the-earth', 'So why does protecting the Amazon still matter?', '["It drives regional rainfall over a continent","It would cause serious oxygen shortages if it went","It stores an enormous quantity of carbon","It holds a large share of the planet''s species"]'::jsonb, '{0,2,3}'::smallint[], 'Carbon storage, rainfall generation and biodiversity are the real stakes, and burning the forest releases its stored carbon rapidly. Atmospheric oxygen is so abundant that even losing every forest would barely move the percentage.', 2::smallint),
  ('the-amazon-is-not-the-lungs-of-the-earth', 'What are flying rivers?', '["Rivers of meltwater flowing down from the Andes","The Amazon river''s huge seasonal flood cycle","Water vapour pumped out by the forest''s trees","Ocean currents that feed into the Amazon basin"]'::jsonb, '{2}'::smallint[], 'Trees pump groundwater into the air as vapour, which travels and falls again, so the forest recycles its own rainfall across the continent. The flying rivers are airborne, which is exactly what the name is pointing at.', 3::smallint),
  ('the-amazon-is-not-the-lungs-of-the-earth', 'What would happen to oxygen if all photosynthesis stopped tomorrow?', '["It would take thousands of years to become serious","Levels would fall noticeably within a few years","We would suffocate within a matter of months","The atmosphere holds a vast reservoir of oxygen"]'::jsonb, '{0,3}'::smallint[], 'Oxygen makes up about a fifth of the atmosphere, a stock so large that consumption would take millennia to dent it. Everything else in the food web would collapse long before breathing became difficult.', 4::smallint),
  ('mycorrhizal-networks', 'What is a mycorrhiza?', '["A root that hosts nitrogen-fixing bacteria","A kind of plant root that grows unusually long","A partnership of fungal threads and plant roots","A fungal disease that attacks the roots of trees"]'::jsonb, '{2}'::smallint[], 'A mycorrhiza is a partnership in which fungal threads reach water and minerals the root cannot and receive sugars in return. Nitrogen-fixing nodules are a different symbiosis, with bacteria rather than fungi.', 0::smallint),
  ('mycorrhizal-networks', 'What can move through such a network?', '["Nerve impulses travelling between the trees","Carbon compounds passing between plants","Chemical signals warning of insect attack","Nitrogen and phosphorus for the plants"]'::jsonb, '{1,2,3}'::smallint[], 'Nutrients and some signalling molecules have been traced moving through fungal connections. Plants have no nerves, and calling this a wood wide web borrows a metaphor that the biology does not support.', 1::smallint),
  ('mycorrhizal-networks', 'What is the main scientific caution about the popular version?', '["The fungi may act for themselves, not for the trees","Field evidence for deliberate sharing is quite weak","Transfers may be incidental rather than cooperative","Mycorrhizal fungi are a recent laboratory finding"]'::jsonb, '{0,1,2}'::smallint[], 'Recent reviews found that popular claims about mother trees feeding seedlings outrun the field data considerably. The fungi themselves are extremely well documented; it is the cooperative narrative that is disputed.', 2::smallint),
  ('mycorrhizal-networks', 'How old is this partnership?', '["It is a recent adaptation to very poor soils","It evolved well after flowering plants first appeared","It may have helped plants colonise land at all","It appears in fossils of the earliest land plants"]'::jsonb, '{2,3}'::smallint[], 'Fossils from over four hundred million years ago show fungal associations in early land plants, before true roots existed. The relationship may have been a precondition for life leaving the water.', 3::smallint),
  ('mycorrhizal-networks', 'What proportion of plant species form these associations?', '["Trees and woody shrubs, but nothing else","A small and specialised minority of them","Roughly 10 per cent of land plant species","The great majority of land plant species"]'::jsonb, '{3}'::smallint[], 'Around nine in ten land plant species form these associations, far beyond forests. It is the normal condition for plants rather than a specialised exception.', 4::smallint),
  ('why-chilli-tastes-hot', 'What does capsaicin actually do?', '["It slightly burns the tissue of the mouth","It temporarily numbs the taste buds instead","It binds a receptor that normally detects heat","It stimulates the taste buds for bitterness"]'::jsonb, '{2}'::smallint[], 'Capsaicin activates TRPV1, the receptor that normally responds to temperatures above about 43 degrees, so the brain receives a heat and pain signal. Taste is unaffected, which is why spiciness is not one of the taste categories.', 0::smallint),
  ('why-chilli-tastes-hot', 'Why does water fail to relieve the burn?', '["The burn is caused by acid that water dilutes","Capsaicin does not dissolve well in water","It dissolves in fat and alcohol instead","Water spreads the compound around the mouth"]'::jsonb, '{1,2,3}'::smallint[], 'Being oil-soluble, capsaicin is not washed away by water and can be spread further, which is why milk and yoghurt work better. Acidity is a separate quality and is not what produces the heat.', 1::smallint),
  ('why-chilli-tastes-hot', 'What does menthol do by comparison?', '["It activates a cold receptor without any cooling","It lowers the temperature of the whole mouth slightly","It numbs the pain receptors lining the mouth","It cools the mouth down by rapid evaporation"]'::jsonb, '{0}'::smallint[], 'Menthol binds TRPM8, the cold sensor, producing a sensation of cold with no temperature change at all. It is the capsaicin trick running in the opposite direction.', 2::smallint),
  ('why-chilli-tastes-hot', 'Why would a plant evolve to produce capsaicin?', '["Birds lack the receptor and are unaffected","It deters mammals, which chew and destroy seeds","It kills the insects that attack the fruit","Birds spread the seeds intact over long distances"]'::jsonb, '{0,1,3}'::smallint[], 'The compound is a targeted deterrent: mammals are punished, birds are not, and birds happen to be the better dispersers. Anti-fungal effects exist too, but insect killing is not the main story.', 3::smallint),
  ('why-chilli-tastes-hot', 'Why do regular chilli eaters tolerate more?', '["Repeated exposure desensitises the receptors","Their receptors are genetically rather different","They lose the ability to taste altogether","The pain response weakens with habituation"]'::jsonb, '{0,3}'::smallint[], 'Repeated activation depletes and desensitises the nerve endings, which is also why capsaicin creams are used for chronic pain. Ordinary taste is unaffected, since a different system is involved.', 4::smallint),
  ('convergent-evolution', 'Why do dolphins and sharks look so similar?', '["Water pushes fast swimmers into a shared ancestry","Similar selection pressures produced similar shapes","They share a reasonably recent common ancestor","Dolphins evolved from an ancestor of the sharks"]'::jsonb, '{1}'::smallint[], 'Similar selection pressures produce similar shapes in unrelated lineages, which is what convergence means. A dolphin''s closest relatives are hoofed land mammals, so ancestry is exactly what the two do not share.', 0::smallint),
  ('convergent-evolution', 'Which are examples of convergent evolution?', '["Wings in birds, bats and insects","Forelimbs of humans, whales and bats","Eyes in vertebrates and octopuses","Echolocation in bats and dolphins"]'::jsonb, '{0,2,3}'::smallint[], 'Each of these solved the same problem separately from different starting material. The forelimb set is the opposite case, homology: one inherited structure modified in different directions.', 1::smallint),
  ('convergent-evolution', 'How can you tell convergence from shared ancestry?', '["By where the trait sits on the family tree","By counting how many species share that one trait","By comparing underlying structure and development","By how similar the finished organs look"]'::jsonb, '{0,2}'::smallint[], 'Convergent structures are built differently underneath and appear scattered across the family tree rather than in one branch. How many species have a trait says nothing about whether they inherited it or arrived at it separately.', 2::smallint),
  ('convergent-evolution', 'What does the octopus eye reveal about convergence?', '["It focuses light using exactly the same lens design","It develops from the same tissue as a vertebrate eye","It proves octopuses and vertebrates are closely related","It performs the same task with a different internal layout"]'::jsonb, '{3}'::smallint[], 'The octopus retina is wired the other way round from ours, so it performs the same task with a completely different internal layout. Same function, different engineering, and no close kinship.', 3::smallint),
  ('convergent-evolution', 'What broader conclusion does convergence support?', '["Evolution can repeat the same path exactly each time","Physics and chemistry constrain which solutions work","Evolution can be partly predictable in its outcomes","Similar environments tend to produce similar forms"]'::jsonb, '{1,2,3}'::smallint[], 'There are only so many workable ways to swim fast or focus light, so similar environments push lineages towards similar answers. The paths differ in detail every time, which is precisely what lets us identify convergence.', 4::smallint),
  ('why-water-is-densest-at-4-degrees', 'What is unusual about water''s density?', '["It peaks at about 4 degrees Celsius, not at freezing","Water below 4 degrees starts to become lighter","Ice is noticeably less dense than liquid water","It becomes denser as it freezes, like most substances"]'::jsonb, '{0,1,2}'::smallint[], 'Most substances get denser all the way down and are denser as solids, and water breaks both rules. Its maximum density sits a few degrees above freezing.', 0::smallint),
  ('why-water-is-densest-at-4-degrees', 'What causes this behaviour?', '["Water molecules shrink when cooled below 4 degrees","Water molecules repel each other more when cold","Cooling normally packs molecules closer together","Air dissolved in the water expands as it cools"]'::jsonb, '{2}'::smallint[], 'Two effects compete: ordinary contraction on cooling, which normally packs molecules closer, and hydrogen bonding pushing them into a spacious crystal. Below 4 degrees the lattice-building wins, so the water expands again.', 1::smallint),
  ('why-water-is-densest-at-4-degrees', 'What does this mean for a lake in winter?', '["Lakes freeze from the bottom upwards","The whole lake cools evenly to freezing point","Water at 4 degrees sinks to the bottom","The coldest water sinks to the lake bed"]'::jsonb, '{2}'::smallint[], 'Water at 4 degrees is densest, so it settles at the bottom while colder water stays above and freezes at the surface. Bottom-up freezing is the intuitive picture and exactly what does not happen.', 2::smallint),
  ('why-water-is-densest-at-4-degrees', 'Why does this matter for life?', '["Aquatic ecosystems would be destroyed each winter","It keeps the lake water warm right through the winter","Fish survive winter in liquid water under the ice","Deep lakes very rarely freeze right through"]'::jsonb, '{0,2,3}'::smallint[], 'The anomaly leaves a liquid refuge under an insulating lid, which is why temperate lakes keep their life through winter. It does not make the water warm, only unfrozen.', 3::smallint),
  ('why-water-is-densest-at-4-degrees', 'What other everyday consequences does the expansion on freezing have?', '["Filled bottles crack open in the freezer","Water pipes burst open in a hard frost","Metal contracts and snaps in cold weather","Icebergs sit entirely below the waterline"]'::jsonb, '{0,1}'::smallint[], 'Ice takes up more room than the water it came from, and the expansion generates enough pressure to split pipes and bottles. Metal failure in the cold is ordinary contraction and brittleness, not water expanding.', 4::smallint),
  ('the-mpemba-effect', 'What does the Mpemba effect claim?', '["Hot water reaches freezing point sooner than cold","The effect usually needs distilled water to appear","Hot water freezes at a higher temperature than cold","Hot water can freeze faster than cold in some setups"]'::jsonb, '{3}'::smallint[], 'The claim is conditional rather than universal, depending on the container, the cooling method and how freezing is defined. Water purity is one of many variables and is not the deciding one.', 0::smallint),
  ('the-mpemba-effect', 'Which explanations have been proposed?', '["Hot water has a lower specific heat capacity","Evaporation reduces the mass of the hot sample","Dissolved gases behave differently after heating","Hot water conducts its heat better than cold water"]'::jsonb, '{1,2}'::smallint[], 'Evaporative loss of mass and differences in dissolved gas are the two most cited mechanisms, alongside convection and supercooling behaviour. Thermal conductivity barely changes over that range.', 1::smallint),
  ('the-mpemba-effect', 'Why is the effect so hard to pin down?', '["Nobody has ever managed to reproduce it","Supercooling makes freezing times erratic","Defining the moment of freezing is ambiguous","Results depend on the container and the freezer"]'::jsonb, '{1,2,3}'::smallint[], 'Whether you time the first ice crystal or complete solidification changes the answer, and supercooling adds large random variation. It has been reproduced many times, which is why the debate continues rather than closing.', 2::smallint),
  ('the-mpemba-effect', 'Who is the effect named after?', '["A physicist who first modelled it mathematically","An ancient philosopher who first wrote it down","The schoolteacher who dismissed his observation at first","A Tanzanian schoolboy who noticed it making ice cream"]'::jsonb, '{3}'::smallint[], 'Erasto Mpemba noticed the effect in a school kitchen and persisted despite ridicule, later publishing with a visiting physicist. Aristotle and others had described something similar centuries earlier, but the name is Mpemba''s.', 3::smallint),
  ('the-mpemba-effect', 'What is the current status of the effect?', '["Likely a mix of several ordinary mechanisms","Still debated, some careful studies fail to find it","Rejected as impossible by basic thermodynamics","Conclusively proven and fully explained by now"]'::jsonb, '{0,1}'::smallint[], 'Modern controlled experiments give mixed results, and most physicists regard any real instances as a mix of mundane effects rather than new physics. Nothing about it violates thermodynamics.', 4::smallint),
  ('tardigrades', 'What can tardigrades survive?', '["Extremely high doses of radiation","Being boiled in hot water for an hour","The vacuum of space for several days","Decades without a drop of water"]'::jsonb, '{0,2,3}'::smallint[], 'Vacuum, radiation and long desiccation have all been survived in experiments, and low temperatures near absolute zero as well. Sustained heat is their weak point: prolonged temperatures above roughly 80 degrees kill them, which is why ''indestructible'' is an exaggeration.', 0::smallint),
  ('tardigrades', 'What state must a tardigrade enter to survive these extremes?', '["A hard protective shell it grows on demand","A dehydrated barrel state called a tun","It seals itself inside a waterproof cocoon","It survives them while still fully active"]'::jsonb, '{1}'::smallint[], 'Cryptobiosis means expelling most of its water and curling into a barrel shape called a tun. There is no cocoon and no shell: the protection comes from the dehydrated state itself.', 1::smallint),
  ('tardigrades', 'How does the tun state protect the animal?', '["It halts its chemistry permanently, not reversibly","Special proteins turn the cell contents glassy","It repairs DNA damage efficiently on rehydration","Water is replaced by sugars and proteins"]'::jsonb, '{1,2,3}'::smallint[], 'Removing water and vitrifying the cell interior stops molecules from moving and being damaged, and repair machinery deals with the rest when water returns. The shutdown is deep but reversible, not permanent.', 2::smallint),
  ('tardigrades', 'Where do tardigrades normally live?', '["In damp moss and lichen almost everywhere","In extreme environments such as hot springs","In deep space, drifting between planets","In the upper atmosphere, carried by wind"]'::jsonb, '{0}'::smallint[], 'They are common animals of damp mosses and lichens, needing a film of water to be active. Their fame comes from what they can endure, not from where they choose to live.', 3::smallint),
  ('tardigrades', 'What is commonly overstated about them?', '["That they thrive in the most extreme conditions","That they are essentially indestructible animals","That they endure more than most animals tested","That exposure kills many even in the tun state"]'::jsonb, '{0,1}'::smallint[], 'They endure extremes rather than living in them, and survival rates in space or radiation experiments are often far from total. Toughness in survival trials is real; invulnerability is a meme.', 4::smallint),
  ('petrichor', 'Where does the smell of rain come from?', '["The rainwater itself as it comes down","Ozone produced by lightning overhead","Pollen washed out of the air by the rain","A compound made by bacteria in the soil"]'::jsonb, '{3}'::smallint[], 'The main component is geosmin, produced by soil bacteria, together with plant oils that build up in dry ground. Rain water itself is odourless, which is why the smell needs an explanation at all.', 0::smallint),
  ('petrichor', 'What is geosmin?', '["The compound that gives beetroot its earthy taste","Detectable by humans at extremely low concentrations","A mineral that dissolves into the rainwater as it falls","A compound produced by bacteria such as Streptomyces"]'::jsonb, '{0,1,3}'::smallint[], 'Geosmin is a bacterial product that our noses detect at a few parts per trillion, and it also gives beetroot and some tap water their earthy character. It is organic in origin, not mineral.', 1::smallint),
  ('petrichor', 'How does the smell get into the air?', '["Wind lifts fine dust up from the soil surface","High-speed photography revealed the mechanism","Raindrops trap air bubbles that burst and spray out","The compounds evaporate when warmed by the rain"]'::jsonb, '{1,2}'::smallint[], 'Slow-motion imaging showed drops trapping bubbles that fizz upwards and launch tiny droplets carrying the compounds. It is a mechanical spray, not evaporation.', 2::smallint),
  ('petrichor', 'Why might humans be so sensitive to geosmin?', '["It warns of spoiled food and contaminated water","It is chemically very similar to the smoke of wood fires","Sensitivity is stronger than for many toxic compounds","It may have signalled water sources to ancestors"]'::jsonb, '{0,2,3}'::smallint[], 'Our threshold for it is lower than for many genuinely dangerous substances, which suggests it mattered, plausibly as a cue to water or to spoilage. It bears no chemical resemblance to smoke.', 3::smallint),
  ('petrichor', 'What is the sharp smell before a thunderstorm?', '["Dust lifted by the approaching gust front","Ozone carried down to us by downdrafts","Petrichor arriving a few minutes early","Geosmin blown along ahead of the rain"]'::jsonb, '{1}'::smallint[], 'Electrical discharge produces ozone, which downdrafts carry to ground level ahead of the rain. That sharp smell is a different one from petrichor, which needs rain to actually land on soil.', 4::smallint),
  ('clouds-weigh-tonnes', 'Roughly how much does an average cumulus cloud weigh?', '["No more than a few kilograms","Nothing, given that it floats","Around 500 tonnes of water","Roughly 100 kilograms in total"]'::jsonb, '{2}'::smallint[], 'A typical fair-weather cumulus holds hundreds of tonnes of water spread across a cubic kilometre. Floating is not the same as weighing nothing.', 0::smallint),
  ('clouds-weigh-tonnes', 'Why does something that heavy stay in the air?', '["The water is in gas form and has no weight","The cloud is lighter than the surrounding air","The droplets are so small they fall extremely slowly","The droplets are lighter than the air around them"]'::jsonb, '{2}'::smallint[], 'Individual droplets are microscopic, so air resistance almost cancels their fall and gentle updraughts supply the rest. Liquid water is far denser than air; it is the size of the droplets that matters.', 1::smallint),
  ('clouds-weigh-tonnes', 'Why is warm moist air actually lighter than dry air?', '["Water molecules are lighter than nitrogen and oxygen","Water vapour displaces heavier air molecules","Warm air carries its moisture in much heavier droplets","Humid air feels heavier, so it must be heavier"]'::jsonb, '{0,1}'::smallint[], 'A water molecule weighs less than the nitrogen or oxygen it displaces, so humid air is genuinely less dense than dry air. Vapour is not droplets, and the everyday sense of heavy humid air is about comfort rather than physics.', 2::smallint),
  ('clouds-weigh-tonnes', 'What has to happen before droplets fall as rain?', '["The whole cloud must be cooled below freezing","Ice crystals form and then melt on the way down","Growth by collision and coalescence in the cloud","They must merge into very much larger drops"]'::jsonb, '{1,2,3}'::smallint[], 'Droplets have to grow by roughly a million times in volume before gravity beats air resistance, either by colliding or via the ice process in colder clouds. Freezing helps but is not required, as tropical warm rain shows.', 3::smallint),
  ('clouds-weigh-tonnes', 'What does a cloud consist of?', '["Ice crystals in the colder, higher clouds","Condensation nuclei such as dust or salt","Enormous numbers of tiny water droplets","Water vapour, which is entirely invisible"]'::jsonb, '{0,1,2}'::smallint[], 'The visible cloud is condensed droplets or crystals, each formed around a microscopic particle. Vapour is genuinely invisible, which is why the air between clouds looks empty.', 4::smallint),
  ('the-square-cube-law', 'What does the square-cube law state?', '["Larger animals grow stronger in exact proportion","Volume grows faster than surface area with size","Area grows with the square, volume with the cube","Doubling the length multiplies the mass by four"]'::jsonb, '{1,2}'::smallint[], 'Area rises with the square of length while volume and mass rise with the cube, so doubling length multiplies mass by eight. That mismatch is why proportionally larger creatures are relatively weaker.', 0::smallint),
  ('the-square-cube-law', 'Why can an ant lift many times its weight but an elephant cannot?', '["Ant muscle is a fundamentally different kind of tissue","Small animals simply have denser muscle fibres","Weight depends on the animal''s total surface area","Muscle strength depends on cross-sectional area"]'::jsonb, '{3}'::smallint[], 'Muscle force scales with cross-sectional area while weight scales with volume, so shrinking improves the ratio automatically. Ant muscle is not special tissue and weight is not a surface property; the geometry does all the work.', 1::smallint),
  ('the-square-cube-law', 'Why would a spider the size of a car be impossible?', '["Gravity would be too strong at that size","It would need proportionally much thicker limbs","Its breathing system does not scale up","Its legs would snap under its own weight"]'::jsonb, '{1,2,3}'::smallint[], 'Mass rises with the cube while leg strength and the surface used for gas exchange rise with the square, so the legs and the breathing system both fail. Gravity is exactly the same for a big spider as for a small one; what changes is the ratio of load to supporting area.', 2::smallint),
  ('the-square-cube-law', 'What else does the law explain?', '["Why small animals live longer than large ones","Why small animals lose their heat far faster","Why large animals need less food in total","Why big animals have proportionally thinner legs"]'::jsonb, '{1}'::smallint[], 'Heat is generated by volume and lost through surface, so a small body cools far faster than a large one. Large animals need more food overall and thicker limbs, not less and thinner.', 3::smallint),
  ('the-square-cube-law', 'How do real large animals cope with the constraint?', '["Growing a lighter, hollow skeleton like a bird''s","Disproportionately thick, pillar-like limbs","Simply having far stronger muscle tissue overall","Living in water, where buoyancy takes the load"]'::jsonb, '{1,3}'::smallint[], 'Elephants carry their weight on columnar legs, and whales exceed any land size limit because water supports them. Hollow bones save weight for flight but do nothing for the load problem on the ground.', 4::smallint),
  ('epigenetics', 'What does epigenetics study?', '["Changes in gene activity, not in the DNA sequence","Mutations caused by the wider surrounding environment","Errors that creep in when the DNA is copied","The way that new genes evolve over long periods"]'::jsonb, '{0}'::smallint[], 'Epigenetic marks such as methylation change which genes get read while leaving the underlying letters untouched. Copying errors are mutations, which alter the sequence itself.', 0::smallint),
  ('epigenetics', 'Why is epigenetics essential to normal development?', '["Each cell has the same DNA but different active genes","It lets cells remember their identity as they divide","It repairs damaged DNA strands inside the cell","It explains how a liver cell differs from a neuron"]'::jsonb, '{0,1,3}'::smallint[], 'A body is one genome expressed in hundreds of ways, and the marks are what keep each cell type on its script through division. Repair is handled by separate machinery.', 1::smallint),
  ('epigenetics', 'What did studies of the Dutch Hunger Winter suggest?', '["The effects faded away within a single generation","The findings prove inheritance across generations","Methylation differences were found decades later","Famine exposure had no measurable later effects"]'::jsonb, '{2}'::smallint[], 'People exposed in the womb showed measurable differences in methylation decades afterwards, alongside health patterns later in life. Whether such effects genuinely pass to further generations in humans is still contested.', 2::smallint),
  ('epigenetics', 'What is the main caution about transgenerational claims?', '["Confounds like shared environment are hard to exclude","Evidence in humans is much weaker than in some animals","Most marks are erased and reset between generations","Epigenetic marks are inferred rather than directly measured"]'::jsonb, '{0,1,2}'::smallint[], 'Reprogramming wipes most marks in the germline, so inheritance past one generation is difficult to establish, especially when families share environments. The marks themselves are measured routinely.', 3::smallint),
  ('epigenetics', 'Which factors can alter epigenetic marks?', '["Deliberate positive thinking alone","Chronic stress over long periods","Diet and nutrition over the years","Choosing a different career path"]'::jsonb, '{1,2}'::smallint[], 'Nutrition and stress hormones both have documented effects on methylation patterns, as do toxins such as tobacco smoke. Life choices with no chemical or hormonal pathway are a different kind of claim entirely.', 4::smallint),
  ('why-antibiotics-do-not-work-on-viruses', 'Why are antibiotics useless against a virus?', '["Viruses are destroyed by the immune system instead","They target structures bacteria have and viruses lack","Viruses have no cell wall or bacterial ribosomes","Viruses are too small for the drug to reach"]'::jsonb, '{1,2}'::smallint[], 'Antibiotics attack bacterial cell walls, ribosomes and enzymes, none of which a virus possesses. What your immune system does is true but is not the reason the drug fails.', 0::smallint),
  ('why-antibiotics-do-not-work-on-viruses', 'Which common illnesses are viral?', '["Tuberculosis of the lung","A bout of bacterial pneumonia","A bad case of strep throat","An ordinary winter cold"]'::jsonb, '{3}'::smallint[], 'The common cold is viral, which is why antibiotics do nothing for it. Tuberculosis, bacterial pneumonia and strep throat are all bacterial and do respond to the right antibiotic.', 1::smallint),
  ('why-antibiotics-do-not-work-on-viruses', 'Why does taking antibiotics unnecessarily cause harm?', '["It disrupts the useful bacteria you carry","It selects for resistant bacteria","It weakens your immune system permanently","It carries side effects with no benefit"]'::jsonb, '{0,1,3}'::smallint[], 'Every unnecessary course applies selection pressure that favours resistant strains and damages your own microbial community for no gain. There is no permanent immune damage, but the resistance cost is shared by everyone.', 2::smallint),
  ('why-antibiotics-do-not-work-on-viruses', 'Why do people believe antibiotics cured their cold?', '["Treatment usually starts near the worst point","Antibiotics can have a mild antiviral effect too","Colds clear up once they have been treated","Antibiotics shorten a cold by a day or two"]'::jsonb, '{0}'::smallint[], 'You start the pills when you feel worst and recover naturally soon after, so the timing manufactures a false cause. Colds resolve on their own in about a week and antibiotics change that not at all.', 3::smallint),
  ('why-antibiotics-do-not-work-on-viruses', 'What does treat a viral infection?', '["Broad-spectrum antibiotics at higher doses","Your own immune system in most cases","Specific antiviral drugs, where they exist","Antiseptic mouthwash and gargles"]'::jsonb, '{1,2}'::smallint[], 'A handful of targeted antiviral drugs exist, and otherwise recovery is your own immune system''s work. Gargles may soothe a throat but do nothing to a systemic viral infection.', 4::smallint),
  ('the-portuguese-man-o-war', 'What is a Portuguese man o'' war?', '["A floating plant covered in stinging cells","A single very large jellyfish of the open sea","A jellyfish with unusually long tentacles","A colony of specialised organisms living as one"]'::jsonb, '{3}'::smallint[], 'It is a colonial siphonophore whose parts, called zooids, cannot survive independently but grew from a single larva. Despite appearances it is not a jellyfish at all.', 0::smallint),
  ('the-portuguese-man-o-war', 'What roles are divided among its parts?', '["A brain zooid that coordinates the other parts","Zooids that digest the food it captures","A gas-filled float holding it at the surface","Tentacle zooids that capture passing prey"]'::jsonb, '{1,2,3}'::smallint[], 'Float, tentacles, digestive and reproductive zooids each do one job and cannot survive alone, which is what makes the colony function as an animal. There is no central controller: coordination comes from simple nerve nets and chemistry.', 1::smallint),
  ('the-portuguese-man-o-war', 'How does it move?', '["It steers by angling its tentacles like rudders","It drifts along with the wind and the current","It swims using muscular contractions of the float","It can inflate itself to rise above the waves"]'::jsonb, '{1}'::smallint[], 'It has no propulsion of its own and drifts wherever wind and current take it, with a crest that catches the wind. Its only manoeuvre is to deflate briefly and sink below rough water.', 2::smallint),
  ('the-portuguese-man-o-war', 'What is true of its sting?', '["It can become harmless once the animal dies","Detached tentacles on a beach can still sting","Fresh water can make stinging cells fire","Its venom is dangerous but rarely fatal to humans"]'::jsonb, '{1,2,3}'::smallint[], 'Stinging cells are mechanical and fire independently of whether the colony is alive, which is why beached specimens are still hazardous. Rinsing with fresh water triggers more of them, so seawater or vinegar is used instead.', 3::smallint),
  ('the-portuguese-man-o-war', 'Why is it a useful example in biology?', '["It shows that colonies will outcompete solitary animals","It shows division of labour without separate bodies","It proves that jellyfish are colonial animals","It blurs the line between individual and colony"]'::jsonb, '{1,3}'::smallint[], 'The colony functions as one animal while being made of many specialised parts, which makes the idea of an individual awkward to define. Nothing about it establishes that colonial life is generally superior.', 4::smallint),
  ('why-stars-twinkle-and-planets-do-not', 'Why do stars twinkle?', '["They emit their light in irregular pulses","Their light crosses more atmosphere than a planet''s","They vary in their brightness very rapidly","Turbulent air bends their light unpredictably"]'::jsonb, '{3}'::smallint[], 'Pockets of air at different temperatures bend the light unpredictably, and because a star is an unresolvable point the whole image jumps. The stars themselves are not changing at all.', 0::smallint),
  ('why-stars-twinkle-and-planets-do-not', 'Why do planets appear steadier?', '["They are closer, so their light is stronger","They show a small disc rather than a point","They shine by reflected rather than emitted light","Reflected light is steadier than emitted light"]'::jsonb, '{1}'::smallint[], 'A planet shows a tiny disc made of many points whose independent flickers average out, leaving a steady glow. Where the light originally came from makes no difference to the effect.', 1::smallint),
  ('why-stars-twinkle-and-planets-do-not', 'When do planets twinkle too?', '["When the atmosphere is especially turbulent","When they are at their brightest in the sky","They do not twinkle under any conditions","When they sit low down near the horizon"]'::jsonb, '{0,3}'::smallint[], 'Near the horizon the light crosses far more air, and strong turbulence can overwhelm the averaging effect. Brightness has nothing to do with it.', 2::smallint),
  ('why-stars-twinkle-and-planets-do-not', 'What do astronomers do about atmospheric distortion?', '["Observe on the nights when the Moon is full","Increase exposure time to average out the blur","Use deformable mirrors that correct in real time","Place telescopes on high, dry mountain sites"]'::jsonb, '{2,3}'::smallint[], 'High dry sites reduce the turbulence in the first place, and adaptive optics correct what remains in real time. Moonlight makes conditions worse rather than better, and longer exposures only accumulate the blur.', 3::smallint),
  ('why-stars-twinkle-and-planets-do-not', 'What is the same effect on a hot day near the ground?', '["A rainbow appearing just after the rain","Heat haze shimmering on the horizon","The distorted view over a hot barbecue","Shimmering air above hot summer tarmac"]'::jsonb, '{1,2,3}'::smallint[], 'All three are refraction through air of varying temperature and density, the same mechanism as twinkling. A rainbow is refraction and reflection inside water droplets, a different process.', 4::smallint),
  ('bioluminescence', 'How is bioluminescent light produced?', '["By tiny electrical discharges in the tissue","By burning stored fat at a high temperature","By absorbing sunlight and re-emitting it later","By a reaction between luciferin and an enzyme"]'::jsonb, '{3}'::smallint[], 'A substrate called luciferin is oxidised with the help of an enzyme, releasing energy as light with almost no heat. Storing and re-emitting sunlight is fluorescence, which is a different phenomenon.', 0::smallint),
  ('bioluminescence', 'What is it used for by the organisms that have it?', '["Startling or distracting a predator","Communicating with and finding mates","Seeing in the dark, much like a torch","Attracting prey close enough to eat"]'::jsonb, '{0,1,3}'::smallint[], 'Lures, defensive flashes and mating signals cover most known uses. Very few species use it for illumination, since a light that reveals you is generally a liability in the deep sea.', 1::smallint),
  ('bioluminescence', 'What is counter-illumination?', '["A way of signalling to others of the same species","Producing a bright flash to blind a predator","Lighting up the seafloor to hunt for food","Glowing on the underside to match light from above"]'::jsonb, '{3}'::smallint[], 'Seen from below, an animal is a dark shape against faint surface light, so glowing on the underside erases the silhouette. It is camouflage by producing light, which is a thoroughly counterintuitive idea.', 2::smallint),
  ('bioluminescence', 'Where is bioluminescence common?', '["In freshwater fish, which rely on it constantly","In the deep ocean, where most species have it","In fireflies and a few other insect groups","In several fungi and in many bacteria"]'::jsonb, '{1,2,3}'::smallint[], 'It is overwhelmingly a marine phenomenon, plus a scattering of insects, fungi and bacteria. Freshwater bioluminescence is remarkably rare, which is itself an open puzzle.', 3::smallint),
  ('bioluminescence', 'How has this chemistry been useful to science?', '["It has replaced electric lighting in some buildings","Luciferase is used to detect bacterial contamination","Genes for light production are used as reporters","Green fluorescent protein revolutionised cell imaging"]'::jsonb, '{1,2}'::smallint[], 'Attaching a light-producing gene to another gene makes its activity visible, and luciferase assays detect living cells in hygiene testing. GFP is genuinely transformative but it fluoresces under light rather than producing its own.', 4::smallint),
  ('birds-flying-in-v-formation', 'Why do birds fly in a V?', '["It keeps the whole flock together socially","It cuts air resistance by drafting directly behind","It lets each bird keep the leader clearly in sight","Each bird catches the upwash from the one ahead"]'::jsonb, '{3}'::smallint[], 'A wing sheds a rising vortex off its tip, and a follower slightly off to the side rides that upward push. Sitting directly behind would put a bird in the downwash, which is why the shape is a V rather than a line.', 0::smallint),
  ('birds-flying-in-v-formation', 'What did tracking of ibises in flight reveal?', '["They timed their wingbeats to match the vortices","The bird in the lead position works hardest","Birds positioned themselves precisely for upwash","Position was random within the whole formation"]'::jsonb, '{0,1,2}'::smallint[], 'Loggers showed remarkably precise spacing and wingbeat phasing to catch the rising air. The bird in front gets no benefit, which is why the position rotates.', 1::smallint),
  ('birds-flying-in-v-formation', 'How do flocks handle the cost of the lead position?', '["The flock flies slowly enough to spare the leader","The birds take turns at the front of the V","The youngest birds are kept up at the front","The strongest bird leads for the whole journey"]'::jsonb, '{1}'::smallint[], 'Studies of ibis flocks found birds swapping in and out of the lead in a reciprocal pattern, since the front position gets no aerodynamic benefit. Flying slower would cost the whole flock rather than help the leader.', 2::smallint),
  ('birds-flying-in-v-formation', 'Which birds use V or line formations?', '["Starlings in their evening murmurations","Cranes and long-distance ibises","Geese and swans flying on migration","Pelicans flying over coastal water"]'::jsonb, '{1,2,3}'::smallint[], 'Large, heavy birds with long migrations are the ones that benefit enough to bother. Starling murmurations are dense three-dimensional swarms serving a completely different purpose, mostly predator avoidance.', 3::smallint),
  ('birds-flying-in-v-formation', 'Where has the same principle been applied by engineers?', '["Cyclists riding in the shelter of a peloton","Trials of aircraft flying in formation to save fuel","Winglets on aircraft, managing the same vortices","Truck platooning along the long stretches of motorway"]'::jsonb, '{1,2}'::smallint[], 'Formation flight trials and wingtip devices both address wingtip vortices directly. Trucks and cyclists save energy by slipstreaming, which is drag reduction rather than riding an upwash.', 4::smallint),
  ('the-eel', 'What remains unknown about European eels?', '["Nobody has observed them spawning in the wild","Where exactly they spend their adult lives","Whether they reproduce sexually or otherwise","How long the larvae survive in the open ocean"]'::jsonb, '{0}'::smallint[], 'Adults are tracked in rivers and coastal waters, but no one has ever seen a wild eel spawn. Larval drift times have been estimated from catches, so that part is not the mystery.', 0::smallint),
  ('the-eel', 'Where are eels believed to spawn?', '["The deep eastern Mediterranean basin","The Sargasso Sea, in the mid-Atlantic","European river mouths and estuaries","Confirmed by tracking tagged adults"]'::jsonb, '{1}'::smallint[], 'Johannes Schmidt mapped larval sizes across the Atlantic and followed the smallest ones to the Sargasso Sea. The location is an inference from that gradient; tagged adults have never been followed all the way there.', 1::smallint),
  ('the-eel', 'What is unusual about the eel life cycle?', '["Adults stop feeding and digest their own organs","Larvae drift for years before reaching the coast","Eels spawn repeatedly right through their adult life","It changes body form dramatically several times"]'::jsonb, '{0,1,3}'::smallint[], 'From transparent leaf-shaped larvae to glass eels to yellow and finally silver eels, the animal is repeatedly rebuilt, and the final migration is one-way. They breed once and die.', 2::smallint),
  ('the-eel', 'What did Aristotle and later Freud have to do with eels?', '["Aristotle thought they arose spontaneously from mud","Aristotle correctly described their migration","Roman writers first located the spawning ground","Freud dissected hundreds looking for testes and failed"]'::jsonb, '{0,3}'::smallint[], 'Ancient writers proposed spontaneous generation from mud, and a young Freud spent months failing to find male reproductive organs. Those organs only develop during the final migration, which is why river-caught eels appear to have none.', 3::smallint),
  ('the-eel', 'What is the conservation status of the European eel?', '["Threatened by dams, fishing and parasites","Stable overall, but reduced in some places","Numbers have fallen by over 90 per cent","Now listed as critically endangered"]'::jsonb, '{0,2,3}'::smallint[], 'Recruitment of young eels collapsed dramatically over recent decades, and the species is listed as critically endangered. Migration barriers, trafficking of glass eels and an introduced parasite are the main pressures.', 4::smallint),
  ('extremophiles-at-black-smokers', 'What powers life at deep-sea hydrothermal vents?', '["Chemical energy from compounds like sulphide","Organic debris sinking down from the surface","Sunlight filtering down from the surface above","Heat converted directly into food energy"]'::jsonb, '{0}'::smallint[], 'Microbes oxidise chemicals emerging from the vents to build organic matter, in place of photosynthesis. Marine snow feeds much of the deep sea but is not what makes vent communities remarkable.', 0::smallint),
  ('extremophiles-at-black-smokers', 'Why was the 1977 discovery so significant?', '["It revealed the deepest point of the ocean","It suggested where life might exist on other worlds","It showed a whole ecosystem independent of sunlight","It was found by geologists not looking for life"]'::jsonb, '{1,2,3}'::smallint[], 'Geologists studying spreading ridges stumbled on dense communities that nothing in biology predicted, and it reframed where life could exist. The deepest ocean point had been reached long before.', 1::smallint),
  ('extremophiles-at-black-smokers', 'What is unusual about the giant tube worms found there?', '["They filter feed on the drifting plankton","Their red plumes are used to absorb sunlight","They house symbiotic bacteria that feed them","They digest sulphide directly in a specialised gut"]'::jsonb, '{2}'::smallint[], 'The worm is essentially a container for chemosynthetic bacteria, which it supplies with sulphide and oxygen. It has no mouth or gut as an adult, and no light reaches those depths to absorb.', 2::smallint),
  ('extremophiles-at-black-smokers', 'What conditions do vent organisms endure?', '["Complete darkness at those depths","Pressures of hundreds of atmospheres","Water emerging at over 300 degrees Celsius","Body temperatures above 300 degrees Celsius"]'::jsonb, '{0,1,2}'::smallint[], 'The vent fluid is superheated and the surroundings are dark, crushing and chemically hostile, and the animals live in the steep gradient beside the flow. No organism tolerates hundreds of degrees internally; the known upper limit for life is around 120 degrees.', 3::smallint),
  ('extremophiles-at-black-smokers', 'Why do these communities interest astrobiologists?', '["Life may not require a star''s light directly","Vent organisms could survive on the Moon''s surface","Similar chemistry could exist under the ice of Europa","They prove that life exists on other worlds"]'::jsonb, '{0,2}'::smallint[], 'If chemistry rather than sunlight can sustain an ecosystem, subsurface oceans on icy moons become plausible habitats. A dry airless surface offers none of the conditions these organisms depend on.', 4::smallint),
  ('the-foehn-wind', 'What happens to air forced over a mountain range?', '["It arrives on the far side both dry and warm","It cools as it rises and drops moisture as rain","It gains extra moisture on the way up the slope","It warms again as it descends the far side"]'::jsonb, '{0,1,3}'::smallint[], 'Rising air expands and cools until water condenses out, then the drier air compresses and warms on the way down. The wind that arrives on the far side is both warmer and drier than the air that started.', 0::smallint),
  ('the-foehn-wind', 'Why is the descending air warmer than the air at the same height upwind?', '["The descending air is squeezed by the mountain itself","Condensation released latent heat during the ascent","Friction with the mountain slope heats the air","Sunlight falling on the lee slope heats it up"]'::jsonb, '{1}'::smallint[], 'Water condensing on the way up releases latent heat into the air, which is why the descending air is warmer than air at the same height upwind. Compression happens because the air sinks into denser atmosphere, not because a wall squeezes it.', 1::smallint),
  ('the-foehn-wind', 'What is a rain shadow?', '["A shaded valley that stays permanently cold","The dry region on the lee side of a mountain range","A cloud that blocks sunlight from a valley","A band of permanent cloud over a mountain ridge"]'::jsonb, '{1}'::smallint[], 'Moisture is wrung out on the windward side, leaving a dry region in the lee, which is how ranges create deserts behind them. It is about what does not fall, not about what hangs overhead.', 2::smallint),
  ('the-foehn-wind', 'What effects are attributed to foehn winds in Alpine regions?', '["Rapid temperature rises of ten degrees or more","Sudden snowmelt and a rise in avalanche risk","Persistent heavy fog filling the valleys","Unusually clear long-distance visibility"]'::jsonb, '{0,1,3}'::smallint[], 'The warm dry air raises temperatures sharply, melts snow and produces famously clear air. Fog is what the wind clears away.', 3::smallint),
  ('the-foehn-wind', 'What are the local names for the same phenomenon?', '["The monsoon across South Asia","The Santa Ana in California","The Chinook in North America","The Zonda wind in Argentina"]'::jsonb, '{1,2,3}'::smallint[], 'Chinook, Zonda and Santa Ana are all downslope warm dry winds by another name. The monsoon is a seasonal reversal of wind direction driven by land and sea heating, a completely different mechanism.', 4::smallint),
  ('plate-tectonics', 'What drives the movement of tectonic plates?', '["Subducting slabs pulling the plates along","Convection currents deep in the mantle","The rotation of the Earth on its axis","Tidal forces exerted by the distant Moon"]'::jsonb, '{0,1}'::smallint[], 'Slab pull from sinking plates is thought to dominate, aided by ridge push and mantle convection beneath. Neither Earth''s rotation nor lunar tides supply meaningful force at these scales.', 0::smallint),
  ('plate-tectonics', 'Why are the Himalayas still growing?', '["India is still pushing northwards into Asia","Erosion is much slower there than elsewhere","The range grows by several metres each year","The collision ended about a million years ago"]'::jsonb, '{0}'::smallint[], 'The Indian plate has never stopped pushing north, so crust keeps thickening and rising by a few centimetres a year. Erosion there is extremely rapid and offsets part of that growth.', 1::smallint),
  ('plate-tectonics', 'What evidence convinced geologists that continents move?', '["Matching coastlines and rocks across the oceans","Magnetic stripes running across the seafloor","Fossils of one species on separated continents","Written records of continents moving in history"]'::jsonb, '{0,1,2}'::smallint[], 'Matching geology, shared fossils and the magnetic striping of the seafloor built the case, and satellites now measure the motion directly. Movement of a few centimetres a year is far too slow to have been noticed in any historical record.', 2::smallint),
  ('plate-tectonics', 'Why was Wegener''s continental drift rejected at first?', '["His evidence was considered to be fabricated","He could not propose any workable mechanism","No fossil evidence existed back at the time","The forces he suggested were simply implausible"]'::jsonb, '{1,3}'::smallint[], 'Wegener''s data was largely accepted, including the fossil matches, but the forces he proposed were physically implausible and he had no workable mechanism. Seafloor spreading supplied one decades later.', 3::smallint),
  ('plate-tectonics', 'What happens at the different plate boundaries?', '["Plates grinding past each other create volcanic arcs","Crust is destroyed along the spreading ridges","New crust forms where two plates collide head on","One plate dives beneath another where they converge"]'::jsonb, '{3}'::smallint[], 'At convergent boundaries one plate dives beneath the other and crust is consumed. New crust forms at spreading ridges, and transform boundaries produce earthquakes rather than volcanoes.', 4::smallint),
  ('karst-and-sinkholes', 'How does karst landscape form?', '["Wind slowly erodes the soft rock into hollows","Frost gradually shatters the rock into rubble","Rainwater picks up CO2 and becomes a weak acid","Slightly acidic water dissolves limestone slowly"]'::jsonb, '{2,3}'::smallint[], 'Rain absorbs carbon dioxide, becomes mildly acidic and slowly dissolves soluble rock over long periods. Frost weathering breaks rock apart mechanically and produces nothing like a cave system.', 0::smallint),
  ('karst-and-sinkholes', 'Why do sinkholes appear suddenly?', '["The rock dissolves instantly during heavy rain","Surface soil is washed away in a single storm","The collapse begins hours before it is visible","The cavity forms slowly but the roof fails all at once"]'::jsonb, '{3}'::smallint[], 'The cavity grows invisibly over years or decades and the roof then fails all at once. Nothing dissolves quickly, so the suddenness is purely mechanical.', 1::smallint),
  ('karst-and-sinkholes', 'What can trigger a collapse?', '["Groundwater being pumped out, removing support","A long dry spell with hardly any rainfall","Leaking water mains washing sediment away","Heavy rain adding weight to the soil above"]'::jsonb, '{0,2,3}'::smallint[], 'Adding load, removing supporting groundwater and washing out sediment from below all push a weakened roof past its limit, which is why sinkholes cluster around building works and burst mains. Drought alone does not trigger collapse, though the drop in groundwater during one can.', 2::smallint),
  ('karst-and-sinkholes', 'What features are typical of karst regions?', '["Wide floodplains built by slow surface rivers","Springs where the water re-emerges again","Caves and underground drainage systems","Deep layers of rich and fertile topsoil"]'::jsonb, '{1,2}'::smallint[], 'Water disappears underground rather than running over the surface, producing caves, springs and dry valleys. Broad floodplains are what you get where water stays on top of the rock.', 3::smallint),
  ('karst-and-sinkholes', 'Why does karst matter for water supply?', '["Karst aquifers supply just a few small regions","Contaminants travel fast through open conduits","The rock filters pollutants very effectively","Pollution stays trapped in the rock for decades"]'::jsonb, '{1}'::smallint[], 'Karst behaves like plumbing rather than a filter, so contaminants travel fast through open conduits and can surface at a spring kilometres away within hours. These aquifers supply roughly a quarter of the world''s drinking water.', 4::smallint),
  ('there-is-no-such-thing-as-cold-blooded', 'Why is ''cold-blooded'' a misleading term?', '["A lizard in the sun can be warmer than you are","Their blood can stay cold whatever the weather","The correct term is simply warm-blooded in reverse","Such animals regulate temperature by behaviour"]'::jsonb, '{0,3}'::smallint[], 'Ectotherms take heat from their surroundings and regulate it by moving, so a basking lizard often runs hotter than you do. The label describes where the heat comes from, which is not captured by inverting warm-blooded.', 0::smallint),
  ('there-is-no-such-thing-as-cold-blooded', 'What is the actual difference between ectotherms and endotherms?', '["Endotherms have a much higher tolerance of pain","Endotherms need far less food per unit of body mass","Ectotherms cannot control their own temperature","Ectotherms rely on external sources of heat"]'::jsonb, '{3}'::smallint[], 'The distinction is the source of the heat: ectotherms take it from outside, endotherms burn food to make it. Internal heating is expensive, so an endotherm needs many times the food of a comparable ectotherm.', 1::smallint),
  ('there-is-no-such-thing-as-cold-blooded', 'How does a lizard regulate its temperature?', '["Shivering hard in order to generate heat","Changing its body posture towards the sun","Moving between patches of sun and shade","Panting hard to raise its core temperature"]'::jsonb, '{1,2}'::smallint[], 'Behavioural thermoregulation, moving between sun and shade and angling the body, can hold temperature within a couple of degrees all day. Panting sheds heat rather than adding it.', 2::smallint),
  ('there-is-no-such-thing-as-cold-blooded', 'What advantages does ectothermy bring?', '["Far lower food requirements than mammals","More energy left for growth from the same food","Ability to survive long periods without eating","Full activity even in very cold conditions"]'::jsonb, '{0,1,2}'::smallint[], 'Not paying for a furnace means less food, longer fasting and more of each meal going into body mass. The trade-off is exactly the cold, where ectotherms become sluggish.', 3::smallint),
  ('there-is-no-such-thing-as-cold-blooded', 'Which cases blur the distinction?', '["Amphibians producing heat chemically like mammals","Hibernating mammals hold a constant temperature","Bees warm the hive by vibrating their flight muscles","Some fish cool their muscles below water temperature"]'::jsonb, '{2}'::smallint[], 'Bees vibrate their flight muscles to warm the hive, which is heat generation by an insect. Tuna and some sharks warm their muscles rather than cooling them, and hibernating mammals let their temperature fall dramatically.', 4::smallint),
  ('why-leaves-change-colour', 'Where do autumn colours come from?', '["The leaf can manufacture new colours in autumn","Chlorophyll breaks down and stops masking them","Reds are often newly produced in autumn","Yellow and orange pigments were present all along"]'::jsonb, '{1,2,3}'::smallint[], 'Carotenoids sit in the leaf all summer, hidden by green chlorophyll, and appear when it is withdrawn. Reds are the exception: anthocyanins are typically made fresh as the leaf shuts down.', 0::smallint),
  ('why-leaves-change-colour', 'Why does the tree break down its chlorophyll at all?', '["To trigger the colour display for seed dispersal","Because chlorophyll turns toxic in the winter","To recover nitrogen before the leaf is dropped","Because chlorophyll cannot survive below freezing"]'::jsonb, '{2}'::smallint[], 'Leaves are expensive to build, so the tree salvages nitrogen and other valuable material before abandoning them. Chlorophyll is dismantled deliberately as part of that recycling, not destroyed by cold.', 1::smallint),
  ('why-leaves-change-colour', 'What makes some autumns more colourful than others?', '["Warm sunny days followed by cool, clear nights","Drought stress, which dulls the display","Early hard frosts, which improve colour","Adequate rainfall through the growing season"]'::jsonb, '{0,1,3}'::smallint[], 'Bright days and cool but frost-free nights favour anthocyanin production and slow the leaf''s decline. A hard frost tends to end the display abruptly rather than enhance it.', 2::smallint),
  ('why-leaves-change-colour', 'How does the leaf actually fall?', '["The stalk dries out until it becomes brittle","A special layer of cells forms at the stalk base","The leaf dies and dries out until it snaps off","The wind eventually tears it off the branch"]'::jsonb, '{1}'::smallint[], 'An abscission layer of cells forms at the base of the stalk, cutting the connection and sealing the scar. The fall is controlled by the tree rather than being the result of drying or wind.', 3::smallint),
  ('why-leaves-change-colour', 'Why do evergreen conifers keep their needles?', '["Keeping them avoids rebuilding leaves each spring","Needles lose less water thanks to their coating","They can hold the same needles for their whole life","They can photosynthesise on mild days in winter"]'::jsonb, '{0,1,3}'::smallint[], 'A thick waxy needle survives frost and drought cheaply, so a conifer keeps its investment for several years and works whenever conditions allow. Needles are shed, just gradually rather than all at once.', 4::smallint),
  ('vikings-did-not-wear-horned-helmets', 'Where does the horned Viking helmet actually come from?', '["Roman descriptions of northern warriors","Medieval Icelandic sagas describing helmets","Costume design for a Wagner opera in the 1870s","Archaeological finds from Scandinavian war graves"]'::jsonb, '{2}'::smallint[], 'The horned helmet was invented by Carl Emil Doepler for the costumes of Wagner''s Ring cycle in 1876. The sagas describe helmets but never horned ones, and no Viking-age burial has produced one.', 0::smallint),
  ('vikings-did-not-wear-horned-helmets', 'What do we actually know about Viking helmets?', '["Only one reasonably complete example has been found","Dozens of decorated helmets survive in museums","Helmets were normally buried with their owners","It is a simple iron cap fitted with a nose guard"]'::jsonb, '{0,3}'::smallint[], 'The Gjermundbu helmet is essentially our only complete Viking-age specimen, a plain iron cap with a nose guard. Iron was expensive and helmets were valuable enough to be reused rather than routinely buried.', 1::smallint),
  ('vikings-did-not-wear-horned-helmets', 'Why would horns be a bad idea in combat?', '["They can deflect a blow into the neck, not away","They can rust faster than the helmet itself","They make the helmet heavier and unbalanced","They give an opponent something to grab hold of"]'::jsonb, '{0,2,3}'::smallint[], 'A smooth curved surface is designed to shed blows, and anything protruding does the opposite. Corrosion is not the issue; the physics of glancing impacts is.', 2::smallint),
  ('vikings-did-not-wear-horned-helmets', 'Are there any horned helmets from the region at all?', '["Yes, from the Bronze Age, far earlier than Vikings","Yes, though from Anglo-Saxon England instead","No, not one has ever turned up in Scandinavia","Yes, from several Viking-age warrior graves"]'::jsonb, '{0}'::smallint[], 'Horned helmets such as the Veksø find are real but Bronze Age, predating the Vikings by well over a thousand years. Confusing them with Viking gear is part of how the myth stuck.', 3::smallint),
  ('vikings-did-not-wear-horned-helmets', 'What does this example illustrate about popular history?', '["Nineteenth-century art shaped how we picture the past","Archaeology usually confirms the popular imagery","A vivid image can outlive the evidence completely","Repetition in film and branding entrenches it"]'::jsonb, '{0,2,3}'::smallint[], 'A costume choice became the default mental picture of an entire culture, reinforced by every later depiction. Archaeology in this case flatly contradicts it, which is exactly why the case is instructive.', 4::smallint),
  ('the-potato-changed-europe', 'Why was the potato so consequential in Europe?', '["It replaced bread entirely across the continent","It produced far more calories per hectare than grain","It could be stored for several years without spoiling","It grew in soils and climates where wheat struggled"]'::jsonb, '{1,3}'::smallint[], 'More calories per hectare and tolerance of poor northern soils are what made the potato transformative. Potatoes actually store badly compared with grain, which is one reason a bad year was so dangerous.', 0::smallint),
  ('the-potato-changed-europe', 'What have historians attributed to its spread?', '["A sharp fall in European birth rates","The decline of Europe''s growing cities","The end of feudalism across Europe","A clear drop in the frequency of famine"]'::jsonb, '{3}'::smallint[], 'The clearest attributed effect is a reduction in the frequency of famine, which in turn supported population and urban growth. The potato is credited with more people and bigger cities, not fewer.', 1::smallint),
  ('the-potato-changed-europe', 'Why was the potato resisted at first?', '["It was unfamiliar and not mentioned in the Bible","It tasted far worse than the grains it replaced","It was widely thought to cause disease in people","It belongs to the same family as deadly nightshade"]'::jsonb, '{0,2,3}'::smallint[], 'Suspicion came from its novelty, its poisonous relatives and rumours about illness, which is why rulers had to promote it actively. Taste was not the objection.', 2::smallint),
  ('the-potato-changed-europe', 'What made the Irish famine so severe?', '["The blight arrived a decade after the famine began","The blight was introduced to Ireland deliberately","Dependence on a single crop for much of the population","Very little genetic variety among the potatoes grown"]'::jsonb, '{2,3}'::smallint[], 'A near-monoculture of closely related plants collapsed all at once when blight arrived. The blight struck across Europe and arrived by accident; what made Ireland different was dependence and policy.', 3::smallint),
  ('the-potato-changed-europe', 'What general lesson does the potato''s history offer?', '["New foods spread quickly once they prove to be better","Crops rarely affect politics in any direct way","Monoculture creates fragility alongside abundance","Exchange of crops between continents was rare"]'::jsonb, '{2}'::smallint[], 'The same crop that supported a population boom also created a catastrophic single point of failure. That is the general lesson: abundance from monoculture comes with fragility attached.', 4::smallint),
  ('the-emu-war', 'What was the Emu War of 1932?', '["A conflict between farmers and the government","A campaign to protect an endangered bird","A military operation against emus damaging crops","A wartime programme to hunt emus for meat"]'::jsonb, '{2}'::smallint[], 'Veteran farmers facing crop destruction persuaded the government to send soldiers with Lewis guns against emu flocks. It was pest control conducted as a military operation, not a food scheme.', 0::smallint),
  ('the-emu-war', 'Why did the operation fail?', '["The terrain made sustained targeting difficult","They ran fast and absorbed hits without dropping","The soldiers refused to shoot the birds","Emus scattered into small groups when fired on"]'::jsonb, '{0,1,3}'::smallint[], 'The birds behaved like guerrillas: dispersing, running at speed and proving remarkably hard to kill outright. There was no reluctance to fire; the shooting simply did not work.', 1::smallint),
  ('the-emu-war', 'Why were there so many emus in the wheat belt?', '["Drought pushed them inland towards farmland","They had been deliberately introduced","They had lost their natural predators","A wet season had boosted their numbers"]'::jsonb, '{0}'::smallint[], 'Drought drove the birds inland towards the wheat belt, where cleared land and stock water suited them well. Emus are native and their predators were not the variable that changed.', 2::smallint),
  ('the-emu-war', 'What was the outcome?', '["A bounty system was used afterwards instead","The operation was called off after poor results","The commander compared them to a well-drilled army","The emu population was largely destroyed by it"]'::jsonb, '{0,1,2}'::smallint[], 'Withdrawal came after a few thousand rounds and comparatively few birds, and bounties later proved more effective than soldiers. Meredith''s remark about their military qualities is the line the story is remembered for.', 3::smallint),
  ('the-emu-war', 'Why is the episode still told today?', '["It changed Australian wildlife law permanently","It caused a major political scandal at the time","It is an unusually literal case of losing to wildlife","It shows military tools suit ecology very badly"]'::jsonb, '{2,3}'::smallint[], 'The absurdity of the framing preserved the story, and it makes a real point about applying force to an ecological problem. Bounties, not legislation, were what eventually worked.', 4::smallint),
  ('the-library-of-alexandria', 'How did the Library of Alexandria end?', '["It declined gradually over several centuries","One catastrophic fire brought it to an end","Funding, patronage and scholars fell away slowly","It was closed by imperial decree in one year"]'::jsonb, '{0,2}'::smallint[], 'There was no single ending: fires, upheaval and above all the loss of royal patronage wore it down across centuries. No decree closed it, and the one dramatic night is a later simplification.', 0::smallint),
  ('the-library-of-alexandria', 'Which events are associated with damage to the library?', '["A Persian siege in the sixth century BC","The eruption of Vesuvius in AD 79","A volcanic eruption burying the city","Caesar''s fire in the harbour in 48 BC"]'::jsonb, '{3}'::smallint[], 'Caesar''s harbour fire in 48 BC is the incident most often linked to damage, though its extent is disputed. Vesuvius buried Pompeii, and Alexandria did not exist in the sixth century BC.', 1::smallint),
  ('the-library-of-alexandria', 'What is a common exaggeration about the library?', '["That it contained the sum of ancient knowledge","That it was a research centre as well as a collection","That it held the only copies of most ancient works","That its loss set science back by many centuries"]'::jsonb, '{0,2,3}'::smallint[], 'Texts circulated in many copies across many cities, so most losses came from the slow attrition of not being copied. The Mouseion genuinely was a research centre, which is the part that is true.', 2::smallint),
  ('the-library-of-alexandria', 'How were ancient texts actually lost?', '["Texts survived mainly because they were on parchment","Works nobody chose to copy simply disappeared","Papyrus decays and needs constant recopying","Deliberate destruction accounted for most losses"]'::jsonb, '{1,2}'::smallint[], 'Papyrus decays, so a text stayed alive only as long as someone kept copying it, and works nobody wanted simply vanished. Parchment helped but plenty of parchment texts were lost too.', 3::smallint),
  ('the-library-of-alexandria', 'Why does the myth persist so strongly?', '["It offers a clean explanation for the gaps we see","It was the largest library the world had seen","Slow decay is easier to picture than a single loss","Contemporary sources describe it in vivid detail"]'::jsonb, '{0}'::smallint[], 'The myth survives because it offers one clean explanation for the gaps in what antiquity left us. A dramatic fire is far easier to picture than centuries of neglect, and Alexandria was one of many libraries.', 4::smallint),
  ('tulip-mania', 'What was tulip mania?', '["One of the earliest documented speculative bubbles","The cause of a lasting Dutch economic depression","A rapid rise and collapse in bulb prices in the 1630s","A trade run through the Amsterdam stock exchange"]'::jsonb, '{0,2}'::smallint[], 'Prices for rare bulbs rose and collapsed in early 1637, in what is usually called the first documented speculative bubble. Trading happened in taverns through informal futures contracts, not on any exchange.', 0::smallint),
  ('tulip-mania', 'Why were certain bulbs so valuable?', '["Rare varieties could be reproduced within a few months","The patterns came from a virus, unknown at the time","The bulbs were prized as a rare edible delicacy","The bulbs had to be imported afresh each year"]'::jsonb, '{1}'::smallint[], 'The prized broken colours were caused by a mosaic virus nobody understood at the time, which also weakened the plant and made the varieties slow to propagate. That slowness is why supply could not answer demand.', 1::smallint),
  ('tulip-mania', 'What do modern historians say about the traditional account?', '["Most contracts were annulled rather than enforced","Later moralising accounts exaggerated the ruin","Trading was concentrated among a fairly small group","Prices stayed close to ordinary bulb prices"]'::jsonb, '{0,1,2}'::smallint[], 'Much of the familiar story comes from later pamphlets with a moral point to make, and the courts largely let the contracts lapse. Prices really did reach extraordinary heights, which is the part that holds up.', 2::smallint),
  ('tulip-mania', 'What features does it share with later bubbles?', '["Purchases that had to be paid in full immediately","New participants entering as the prices climbed","Government guarantees that encouraged risk-taking","Buyers who mainly wanted the flowers themselves"]'::jsonb, '{1}'::smallint[], 'New participants pouring in as prices climbed is the pattern every later bubble repeats. Buying for use rather than resale, and paying in full, are precisely what a bubble does not involve.', 3::smallint),
  ('tulip-mania', 'Why is the episode still invoked today?', '["As a warning applied to each new asset class","Because it is the best-documented bubble in history","Because the economics of it are fully understood","As convenient shorthand for irrational speculation"]'::jsonb, '{0,3}'::smallint[], 'It has become a rhetorical label attached to whatever is currently rising fast. The documentary record is actually thin and heavily contested, which is why the comparison is often looser than it sounds.', 4::smallint),
  ('the-year-without-a-summer', 'What caused the year without a summer in 1816?', '["A shift in Atlantic ocean circulation","The eruption of Mount Tambora in 1815","Volcanic ash blocking sunlight for a year","A sudden dip in solar output alone"]'::jsonb, '{1}'::smallint[], 'Tambora''s 1815 eruption injected enormous quantities of sulphur into the stratosphere, where reflective droplets cooled the planet. Ocean circulation changes far too slowly to produce a single cold summer worldwide.', 0::smallint),
  ('the-year-without-a-summer', 'What happened in 1816?', '["Food prices rose sharply and riots followed","Snow fell across New England in the June","Global temperatures fell by about five degrees","Crops failed across Europe and North America"]'::jsonb, '{0,1,3}'::smallint[], 'Frosts through the growing season destroyed harvests, driving prices up and unrest with them. The global average fell by roughly half a degree to one degree, which was enough to do all this.', 1::smallint),
  ('the-year-without-a-summer', 'What cultural consequences are attributed to that summer?', '["The first photographs recorded the dark skies","Frankenstein was begun during a rain-bound holiday","The steam locomotive was invented in response","The waltz was invented during that same year"]'::jsonb, '{1}'::smallint[], 'Mary Shelley began Frankenstein during a rain-bound holiday on Lake Geneva that summer. Photography was two decades away, and the locomotive predates the eruption.', 2::smallint),
  ('the-year-without-a-summer', 'What does the episode demonstrate about the climate system?', '["The system responds to relatively modest forcings","A small average change can have severe local effects","Volcanic cooling can last for decades afterwards","Cooling was limited to the tropical regions"]'::jsonb, '{0,1}'::smallint[], 'A global average drop of well under a degree was enough to destroy harvests across two continents, which shows how sensitive the system is to modest forcing. Effects were felt worldwide, not only near the equator.', 3::smallint),
  ('the-year-without-a-summer', 'How do we know about Tambora''s effects today?', '["Tree rings showing suppressed growth","Written records of weather and harvests","Satellite measurements of the eruption","Sulphate layers preserved in ice cores"]'::jsonb, '{0,1,3}'::smallint[], 'Ice cores date and size the eruption, tree rings register the cold summers, and diaries and price records fill in the human side. Satellites came a century and a half later.', 4::smallint),
  ('the-silk-road-was-not-a-road', 'What was the Silk Road?', '["A system where goods changed hands many times","A single paved road running from China to Rome","A shifting network of overlapping trade routes","Largely regional trade, not end-to-end journeys"]'::jsonb, '{0,2,3}'::smallint[], 'Goods passed through many intermediaries over short legs, so almost nobody travelled the whole distance. There was never one road, and much of it was not road at all but steppe, desert and sea.', 0::smallint),
  ('the-silk-road-was-not-a-road', 'Where does the name come from?', '["It was used by merchants travelling at the time","It first appeared in Marco Polo''s own account","A German geographer coined the term in 1877","Chinese records used the term from the Han dynasty"]'::jsonb, '{2}'::smallint[], 'Ferdinand von Richthofen coined Seidenstrasse in 1877, long after the trade itself had ended. Nobody travelling those routes would have recognised the name, Marco Polo included.', 1::smallint),
  ('the-silk-road-was-not-a-road', 'What besides silk moved along these routes?', '["Technologies including paper and gunpowder","The greater part of Rome''s grain supply","A common written language used by merchants","Standardised weights used along the whole route"]'::jsonb, '{0}'::smallint[], 'Paper and gunpowder are the classic examples of technologies that travelled west along these networks, alongside religions and diseases. There was no shared script and no common system of weights.', 2::smallint),
  ('the-silk-road-was-not-a-road', 'Why is the road framing misleading?', '["It suggests a fixed route, not a changing network","It implies direct contact between the two ends","It downplays the sea routes carrying most bulk trade","It exaggerates how dangerous the journey really was"]'::jsonb, '{0,1,2}'::smallint[], 'The image of a highway hides the sea routes, the constant rerouting and the chains of middlemen. Danger is one thing the framing does not overstate.', 3::smallint),
  ('the-silk-road-was-not-a-road', 'What conditions allowed the trade to flourish?', '["A common currency accepted along the whole route","Large empires providing security across long stretches","A treaty guaranteeing safe passage for merchants","Oasis cities and caravanserai supporting travellers"]'::jsonb, '{1,3}'::smallint[], 'Trade surged when large empires secured long stretches of the route and oasis cities supplied travellers, which is why the Mongol period was a high point. No treaty ever covered the whole network.', 4::smallint),
  ('the-vasa', 'What happened to the Vasa in 1628?', '["It caught fire at its moorings in Stockholm","It was sunk in battle against a Danish fleet","It capsized on its maiden voyage after 1,300 metres","It struck a rock on the way out of Stockholm harbour"]'::jsonb, '{2}'::smallint[], 'A modest gust heeled the ship far enough for water to pour through the open lower gun ports, and she sank after about 1,300 metres. Nothing was struck and no enemy was involved.', 0::smallint),
  ('the-vasa', 'Why was the ship so unstable?', '["There was not enough ballast to compensate","The timber used in the hull was far too heavy","Two gun decks put too much weight high up","The hull was much too narrow for its height"]'::jsonb, '{0,2,3}'::smallint[], 'The design put heavy guns and ornamentation high while the hull could not carry enough ballast to balance them. The wood itself was ordinary oak.', 1::smallint),
  ('the-vasa', 'What is known about the warnings before the launch?', '["Nobody on the project suspected any problem","The admiral cancelled the launch after the test","The king had ordered a slower, careful build","A stability test was stopped as the ship rocked"]'::jsonb, '{3}'::smallint[], 'Thirty men running from side to side nearly rolled her at the quay, and the test was stopped rather than the ship. Royal pressure for speed and a hierarchy in which nobody would deliver bad news did the rest.', 2::smallint),
  ('the-vasa', 'Why is the Vasa so well preserved today?', '["It was encased in silt that kept water out","It was raised almost fully intact in 1961","The Baltic is too brackish for the shipworm","Cold, low-salinity water slowed the decay"]'::jsonb, '{1,2,3}'::smallint[], 'The organism that normally eats submerged wood cannot tolerate the Baltic''s low salinity, so the hull survived over three centuries. Silt helped but the ship was not sealed off from the water.', 3::smallint),
  ('the-vasa', 'Why is the Vasa used as a case study in project management?', '["The shipbuilders were largely untrained men","The design was copied from a rival foreign navy","Requirements changed during the construction","Nobody was willing to tell the king it was unsafe"]'::jsonb, '{2,3}'::smallint[], 'Requirements changed mid-construction and nobody was willing to tell the king his prestige ship was unsafe, a recognisably modern pattern. The design was Swedish and the builders were experienced; the process around them failed.', 4::smallint),
  ('the-little-ice-age', 'What was the Little Ice Age?', '["A true glacial period covering Europe in ice","Cooler climate from about the 14th to 19th century","About a degree of cooling, varying by region","A cooling confined to northern Europe alone"]'::jsonb, '{1,2}'::smallint[], 'It was a modest, uneven cooling of roughly a degree spread across several centuries, not a glaciation. Effects were recorded well beyond northern Europe, including in Asia and the Americas.', 0::smallint),
  ('the-little-ice-age', 'What likely contributed to the cooling?', '["A single catastrophic event that started it","A sudden shift in the Earth''s axial tilt","A measurable increase in the solar output","Repeated large-scale volcanic eruptions"]'::jsonb, '{3}'::smallint[], 'Repeated large volcanic eruptions are the best-supported contributor, alongside a period of reduced solar activity and ocean circulation changes. Solar output fell rather than rose, and axial tilt changes over tens of thousands of years.', 1::smallint),
  ('the-little-ice-age', 'What consequences have historians linked to it?', '["An intensification of witch trials in some regions","The final fall of the western Roman Empire","The abandonment of Norse settlements in Greenland","Failed harvests and famines across Europe"]'::jsonb, '{0,2,3}'::smallint[], 'Cold years, hunger and the search for someone to blame ran together, and marginal settlements failed first. Rome fell roughly a thousand years earlier.', 2::smallint),
  ('the-little-ice-age', 'What everyday evidence of the period survives?', '["Frost fairs held on a frozen Thames","Dutch winter landscape paintings","Ice cores drilled at the time","Photographs of frozen harbours"]'::jsonb, '{0,1}'::smallint[], 'Frost fairs on a frozen Thames and Dutch winter landscapes are the vivid everyday traces of colder decades. Ice cores are a modern method applied to old ice, not a contemporary record.', 3::smallint),
  ('the-little-ice-age', 'What caution do historians attach to climate explanations?', '["Climate creates pressure but does not decide outcomes","Cooling was uniform right across the continent","Social factors made little difference to outcomes","The period explains most of early modern history"]'::jsonb, '{0}'::smallint[], 'Climate created pressure, but similar cold years produced famine in one place and none in another depending on institutions and trade. Treating climate as the master key is exactly the overreach specialists warn against.', 4::smallint),
  ('the-dark-ages', 'Where does the term Dark Ages come from?', '["Contemporary chroniclers of the period itself","Enlightenment philosophers attacking the church","Renaissance writers contrasting their age with it","Nineteenth-century archaeologists in Europe"]'::jsonb, '{2}'::smallint[], 'The label is polemical, coined by Renaissance writers who wanted to present themselves as reviving antiquity. Petrarch is usually credited with the image, well before the Enlightenment.', 0::smallint),
  ('the-dark-ages', 'What developments happened in the supposedly dark centuries?', '["The first universities being founded","The invention of the printing press itself","The heavy plough and the horse collar","Water mills spreading across Europe"]'::jsonb, '{0,2,3}'::smallint[], 'Agricultural and mechanical innovation and the first universities all belong to the medieval period. Printing came in the fifteenth century, at the boundary of the era the term was aimed at.', 1::smallint),
  ('the-dark-ages', 'In what limited sense is the term defensible?', '["Knowledge from antiquity was lost everywhere","Written sources are sparse for many regions","The whole of Europe stagnated intellectually","Literacy disappeared completely across Europe"]'::jsonb, '{1}'::smallint[], 'Some historians use dark to mean poorly documented rather than backward, and for certain regions and centuries the written record really is thin. Literacy persisted in monasteries, courts and Byzantium throughout.', 2::smallint),
  ('the-dark-ages', 'How do historians refer to the period now?', '["The early Middle Ages period","The Dark Ages, the standard term","Late antiquity, for the earlier part","The migration period in Europe"]'::jsonb, '{0,2,3}'::smallint[], 'Neutral, descriptive labels have replaced the value judgement in academic use. The old term survives mainly in popular writing.', 3::smallint),
  ('the-dark-ages', 'What does the term''s history illustrate?', '["Historical periods have clear objective boundaries","Periodisation carries its arguments inside it","Labels are revised as soon as the evidence changes","Later ages define themselves against a made-up past"]'::jsonb, '{1,3}'::smallint[], 'Naming an era is an interpretive act, and the Renaissance needed a dark background to stand against. The term outlived the scholarship that justified it by centuries, which is the opposite of prompt revision.', 4::smallint),
  ('napoleon-was-not-short', 'How tall was Napoleon?', '["Around 1.68 metres, about average for the time","Roughly 1.55 metres, which is unusually short","Slightly above average for a Frenchman of his era","Recorded as five foot two in English units"]'::jsonb, '{0}'::smallint[], 'His height of about 168 centimetres was unremarkable for the period. The five foot two figure was in French inches, which were longer than English ones, and reading it as English is where the myth begins.', 0::smallint),
  ('napoleon-was-not-short', 'Where did the myth of his shortness come from?', '["Contemporary medical records describing dwarfism","Confusion between French and English inches","British caricatures that depicted him as tiny","He was surrounded by unusually tall guardsmen"]'::jsonb, '{1,2,3}'::smallint[], 'A measurement error, hostile cartoons and his tall Imperial Guard escort reinforced one another. No medical source suggests anything unusual about his stature.', 1::smallint),
  ('napoleon-was-not-short', 'What was the nickname ''le petit caporal'' about?', '["An insult coined by his political enemies","A reference to his actual physical height","An affectionate term used by his soldiers","A rank he actually held early in his career"]'::jsonb, '{2}'::smallint[], 'Le petit caporal was an affectionate term from his soldiers expressing familiarity, not a description of his body or his rank. Read literally by later generations, it fed the myth.', 2::smallint),
  ('napoleon-was-not-short', 'What is the Napoleon complex?', '["A term built on a false premise about Napoleon","The idea that short men overcompensate by aggression","A well-supported finding in modern psychology","A concept named after someone of average height"]'::jsonb, '{0,1,3}'::smallint[], 'The term rests on a factual error and the underlying psychological claim has weak and mixed evidence. It is a case of a myth becoming a diagnostic label.', 3::smallint),
  ('napoleon-was-not-short', 'What does the case show about historical propaganda?', '["Caricature can outlast the conflict that produced it","Propaganda works while the war is still going on","Contemporary evidence usually corrects such myths","A measurement error can become common knowledge"]'::jsonb, '{0,3}'::smallint[], 'Gillray''s caricatures shaped the picture of Napoleon for two centuries after Waterloo, helped by a units error that became common knowledge. Accurate records existed the whole time and changed nothing.', 4::smallint),
  ('the-spanish-flu-did-not-come-from-spain', 'Why was the 1918 pandemic called Spanish flu?', '["Warring countries suppressed news of sick troops","Spain was neutral and did not censor reports of it","The first outbreak clearly began in Madrid","Spanish doctors were the first to identify the virus"]'::jsonb, '{0,1}'::smallint[], 'Spain was neutral and did not censor its press, while the warring powers suppressed news of illness among their troops. The virus itself was not identified until decades later.', 0::smallint),
  ('the-spanish-flu-did-not-come-from-spain', 'What is known about where it actually started?', '["The true origin remains uncertain even now","Portugal and Italy are the leading candidates","Troop movements had little effect on its spread","It definitely began inside Spain itself"]'::jsonb, '{0}'::smallint[], 'Kansas, northern France and China have all been proposed and none is settled, so the origin remains genuinely uncertain. Mass wartime troop movement is agreed to have driven the global spread.', 1::smallint),
  ('the-spanish-flu-did-not-come-from-spain', 'What was unusual about who died?', '["Mortality peaked among healthy young adults","The age pattern formed a W shape rather than a U","It mainly killed the very old, as flu usually does","An overreacting immune response may be involved"]'::jsonb, '{0,1,3}'::smallint[], 'Unlike typical influenza, it killed people in their twenties and thirties heavily, producing a distinctive three-peaked age curve. A strong immune reaction in healthy adults is one proposed explanation.', 2::smallint),
  ('the-spanish-flu-did-not-come-from-spain', 'How severe was the pandemic?', '["It infected roughly a third of the world''s population","Estimated deaths run from 50 million people upwards","It killed fewer people than the First World War","Deaths were concentrated in Europe and America"]'::jsonb, '{0,1}'::smallint[], 'Estimates run from about 50 million deaths upwards, with roughly a third of the world infected, which exceeds the war''s toll. Mortality was heaviest in India and other regions outside Europe.', 3::smallint),
  ('the-spanish-flu-did-not-come-from-spain', 'What does the naming controversy illustrate?', '["Disease names usually reflect the true origin","Censorship distorts the whole historical record","The name was chosen by the medical authorities","Place names in disease naming are now compulsory"]'::jsonb, '{1}'::smallint[], 'Censorship distorted the record so thoroughly that a neutral country was blamed for a century. That experience is part of why the WHO now discourages geographic disease names rather than requiring them.', 4::smallint),
  ('the-bronze-age-collapse', 'What happened around 1200 BC in the eastern Mediterranean?', '["Writing was first invented in the aftermath of it","One single empire conquered the whole region","Cities were destroyed or abandoned over a wide area","Several major civilisations declined within decades"]'::jsonb, '{2,3}'::smallint[], 'Mycenaean Greece, the Hittite empire and others unravelled within decades, with cities destroyed or abandoned across a wide region. Writing was lost in some areas rather than gained, which is part of why the period is so dark to us.', 0::smallint),
  ('the-bronze-age-collapse', 'Which causes have been proposed?', '["A single enormous volcanic eruption","An asteroid impact in the Mediterranean","Prolonged drought and repeated crop failure","A pandemic recorded in Egyptian sources"]'::jsonb, '{2}'::smallint[], 'Climate evidence for prolonged drought and crop failure is among the best-supported contributors, alongside the Sea Peoples and internal upheaval. No impact or documented pandemic features in current accounts.', 1::smallint),
  ('the-bronze-age-collapse', 'What is the systems-collapse explanation?', '["Bronze needed tin brought from distant sources","Each civilisation failed for its own separate reasons","Interdependent states failed when trade broke down","One shock cascaded through a connected network"]'::jsonb, '{0,2,3}'::smallint[], 'Bronze needed copper and tin from separate regions, so the whole system depended on long-distance trade continuing. Cutting those links could bring down states that were individually strong.', 2::smallint),
  ('the-bronze-age-collapse', 'What followed the collapse?', '["The gradual spread of iron working everywhere","Centuries with far fewer written records in Greece","An immediate return to earlier levels of prosperity","The rapid founding of much larger empires"]'::jsonb, '{0,1}'::smallint[], 'Recovery took centuries, with far fewer written records in Greece and a gradual shift to iron, whose ore is available almost everywhere. Larger empires came much later, not immediately.', 3::smallint),
  ('the-bronze-age-collapse', 'Why is the collapse discussed so often today?', '["It shows collapse is impossible in modern states","The causes are fully established and agreed","It combines climate stress with political fragility","It shows isolated states are the most fragile"]'::jsonb, '{2}'::smallint[], 'The combination of climate stress and political fragility bringing down connected states is what makes the period so widely discussed. Interconnection was the vulnerability here, and complexity was lost rather than gained.', 4::smallint),
  ('stanislav-petrov', 'What did Stanislav Petrov do in 1983?', '["Did not pass the warning up the chain as required","Judged a missile launch alert to be a false alarm","Ordered an approaching counterstrike cancelled","Shut down the whole satellite warning system"]'::jsonb, '{0,1}'::smallint[], 'As duty officer he judged the alert spurious and did not pass it up the chain as procedure required, reporting a malfunction instead. He had no authority to shut down systems or order any strike.', 0::smallint),
  ('stanislav-petrov', 'Why did he doubt the warning?', '["A real first strike would use far more missiles","He had been told the system was offline","Ground radar had not confirmed anything","He distrusted the new satellite system"]'::jsonb, '{0,2,3}'::smallint[], 'The small number of missiles made no strategic sense, corroboration was missing, and he knew the system was newly deployed. Nobody had told him it was down.', 1::smallint),
  ('stanislav-petrov', 'What had actually triggered the alert?', '["A software error in the ground station","A faulty sensor that was later replaced","An actual missile test being carried out","Sunlight reflecting off high-altitude clouds"]'::jsonb, '{3}'::smallint[], 'The satellite mistook sunlight glinting off high-altitude clouds for launch plumes, in an alignment nobody had anticipated. The hardware worked as designed on data that was misleading.', 2::smallint),
  ('stanislav-petrov', 'What was the wider context of September 1983?', '["The Cold War was essentially over by that point","A NATO exercise later that year raised alarm further","Tension was high after a Korean airliner was downed","Soviet leaders genuinely feared a first strike"]'::jsonb, '{1,2,3}'::smallint[], 'The incident fell in one of the tensest stretches of the entire Cold War, which is precisely why an automatic response would have been plausible. The Cold War had six years still to run.', 3::smallint),
  ('stanislav-petrov', 'What is the lesson usually drawn from the episode?', '["He was rewarded and promoted for his decision","Human judgement in the loop catches what systems miss","Following procedure exactly is the safe choice","Automated systems should make the final decision"]'::jsonb, '{1}'::smallint[], 'Procedure said to pass the alert on, and doing so could have been catastrophic, which is the uncomfortable core of the story. It is the standard argument for keeping a human in the loop, not for removing one.', 4::smallint),
  ('the-hanseatic-league', 'What was the Hanseatic League?', '["A kingdom with its own clearly defined borders","An alliance with no state and no standing army","A guild controlled by one single ruling family","An association of merchant towns around the Baltic"]'::jsonb, '{1,3}'::smallint[], 'It was a league of merchant towns around the Baltic and North Sea with no territory, no ruler and no standing army. Power came from collective commercial leverage rather than sovereignty or dynasty.', 0::smallint),
  ('the-hanseatic-league', 'How did the League enforce its interests?', '["Trade embargoes against uncooperative rulers","Issuing its own law across member territories","Levying taxes directly on its member cities","Maintaining a permanent professional army"]'::jsonb, '{0}'::smallint[], 'Trade embargoes were the League''s main weapon, backed occasionally by fleets raised ad hoc from members. It had no territory to tax or legislate over, which is what makes it unusual among the era''s powers.', 1::smallint),
  ('the-hanseatic-league', 'Which cities were central to the League?', '["Novgorod and Bergen, as trading posts","Hamburg and Bremen on the North Sea","Lübeck, the League''s leading member city","Venice and Genoa in the wider Mediterranean"]'::jsonb, '{0,1,2}'::smallint[], 'Lübeck led a northern network with major counters, or Kontore, at Novgorod, Bergen, Bruges and London. Venice and Genoa dominated Mediterranean trade in an entirely separate system.', 2::smallint),
  ('the-hanseatic-league', 'What did the League trade?', '["Salted herring and bulk cargoes of salt","Gold and silver mined in Scandinavia","Silk and spices arriving from Asia","Grain, timber and furs from the east"]'::jsonb, '{0,3}'::smallint[], 'Bulk staples were the basis of Hanseatic wealth: grain, timber and furs from the east, and above all salted herring and salt. Precious metals played no significant part.', 3::smallint),
  ('the-hanseatic-league', 'Why did the League decline?', '["It was destroyed in one decisive war at sea","Member cities were conquered by the Ottomans","Atlantic routes shifted commerce from the Baltic","Its own members were forbidden to trade abroad"]'::jsonb, '{2}'::smallint[], 'New Atlantic routes shifted European commerce away from the Baltic, while centralising monarchies and sharper competitors eroded the League''s privileges. There was no dramatic end and no conquest.', 4::smallint),
  ('the-fall-of-the-aztecs', 'What killed most people during the Spanish conquest of Mexico?', '["Starvation caused by the long siege alone","Spanish steel weapons, armour and horses","Epidemic disease, and smallpox above all","Famine after the maize harvest was destroyed"]'::jsonb, '{2}'::smallint[], 'Old World diseases, above all smallpox, killed on a scale no army could match in populations with no prior exposure. Weapons and hunger mattered in the campaign but not in the demographic outcome.', 0::smallint),
  ('the-fall-of-the-aztecs', 'What else was decisive besides disease?', '["A naval blockade mounted from the Atlantic coast","Control of the causeways and lake at Tenochtitlan","Resentment of Aztec tribute among subject peoples","Large numbers of indigenous allies against them"]'::jsonb, '{1,2,3}'::smallint[], 'Cortés commanded a coalition in which Spaniards were a small minority, exploiting existing grievances, and the siege turned on cutting the city off. Framing it as a technological victory erases the tens of thousands of indigenous fighters.', 1::smallint),
  ('the-fall-of-the-aztecs', 'Why were the epidemics so devastating?', '["The Americas were isolated from Old World disease","The population was already weakened by famine","Adults had already met these diseases in trade","Indigenous people were biologically far weaker"]'::jsonb, '{0}'::smallint[], 'Long isolation from Old World pathogens meant no prior exposure anywhere in the population. Adults died alongside children, which is exactly why leadership and food production collapsed together.', 2::smallint),
  ('the-fall-of-the-aztecs', 'What is questionable in the traditional narrative?', '["That a few hundred Spaniards defeated an empire","That Moctezuma believed Cortés was a returning god","That smallpox reached Tenochtitlan during the conflict","That indigenous accounts were written long afterwards"]'::jsonb, '{0,1,3}'::smallint[], 'The god story appears in sources written decades later and is now widely doubted, and the small-band version omits the allies entirely. The smallpox outbreak during the war is well attested.', 3::smallint),
  ('the-fall-of-the-aztecs', 'What was the scale of population loss in the century after contact?', '["It happened within one single epidemic year","It was one of the largest collapses in history","A loss of around 20 per cent of the people","Estimates commonly range from 80 to 95 per cent"]'::jsonb, '{1,3}'::smallint[], 'Estimates of 80 to 95 per cent loss over a century make this one of the largest demographic collapses on record. It came in successive waves of different diseases rather than one outbreak.', 4::smallint),
  ('easter-island', 'What is the popular collapse narrative about Easter Island?', '["The statues were carved after European contact","Islanders deforested the island and society collapsed","The islanders abandoned the island completely","It is told as a parable of ecological self-destruction"]'::jsonb, '{1,3}'::smallint[], 'The familiar story has the islanders felling every tree and collapsing into famine and warfare, and it is told as a parable of ecological self-destruction. The island was never abandoned.', 0::smallint),
  ('easter-island', 'What do critics of that narrative point to?', '["Evidence of continued farming and stable population","No real deforestation ever occurred there","Rats brought by the settlers ate palm seeds","Slave raids and disease after European contact"]'::jsonb, '{0,2,3}'::smallint[], 'Introduced rats plausibly prevented forest regeneration, and archaeological evidence suggests adaptation rather than collapse, with the real catastrophe arriving with Europeans. The forest loss itself is not disputed.', 1::smallint),
  ('easter-island', 'How were the statues probably moved?', '["Floated along a canal system running around the island","Rocked upright from side to side, effectively walked","Rolled on log rollers, requiring vast timber","Dragged by many thousands of workers on sledges"]'::jsonb, '{1}'::smallint[], 'Experiments have shown that teams with ropes can walk a moai upright by rocking it side to side, which matches the islanders'' own tradition. There were no canals, and the log-roller version is what made deforestation seem central.', 2::smallint),
  ('easter-island', 'What happened to the island''s population in the 1860s?', '["Peruvian slave raids took a large share of the people","The decline was complete before any outsiders arrived","Smallpox and tuberculosis followed soon after","The islanders were resettled onto the mainland"]'::jsonb, '{0,2}'::smallint[], 'Peruvian slave raids removed a large share of the population and imported disease followed, leaving roughly a hundred people. Nobody was resettled, and that timing is the strongest objection to a purely self-inflicted collapse.', 3::smallint),
  ('easter-island', 'Why is the debate significant beyond the island?', '["Colonial contact made almost no real difference","Which story is true changes the moral we draw","The island is too small to serve as any model","The evidence is now settled in favour of collapse"]'::jsonb, '{1}'::smallint[], 'The island became a stand-in for humanity on a finite planet, so whether the collapse was self-inflicted or imported changes the moral entirely. Colonial contact is precisely the factor the revised account emphasises.', 4::smallint),
  ('the-longitude-problem', 'Why was longitude at sea so hard to determine?', '["It requires knowing the time at a reference place","Latitude came from the Sun, longitude did not","Existing pendulum clocks failed badly at sea","The stars are not visible from the open ocean"]'::jsonb, '{0,2}'::smallint[], 'Longitude is a time difference, so it needed a clock that kept reference time through months of motion and damp, and pendulum clocks were useless at sea. Stars are perfectly visible offshore, which is how latitude was found.', 0::smallint),
  ('the-longitude-problem', 'What were the consequences of not knowing longitude?', '["Ships could not find their way north or south","Ships ran aground and were lost with their crews","Voyages took longer as captains sailed a latitude","The Scilly disaster of 1707 killed some 1,500 men"]'::jsonb, '{1,2,3}'::smallint[], 'Navigators fell back on running down a known latitude, which was slow and predictable to enemies, and errors put fleets on rocks. Latitude was never the problem.', 1::smallint),
  ('the-longitude-problem', 'Who solved it and how?', '["The Astronomer Royal, using lunar tables","A single prototype that worked immediately","John Harrison, a self-taught clockmaker","An astronomical rather than mechanical solution"]'::jsonb, '{2}'::smallint[], 'John Harrison, a self-taught clockmaker, solved it through a sequence of chronometers ending in the compact H4. Lunar distances were the competing astronomical method, championed by his rivals.', 2::smallint),
  ('the-longitude-problem', 'What was the rival method?', '["Lunar distances, using the Moon against the stars","Dead reckoning from the speed and compass heading","It was abandoned as soon as chronometers appeared","It could be done in minutes by almost any sailor"]'::jsonb, '{0}'::smallint[], 'Lunar distances worked by measuring the Moon against the stars, and remained a backup for decades because chronometers were expensive. The method demanded hours of computation and clear skies, which is why a clock was so attractive.', 3::smallint),
  ('the-longitude-problem', 'Why is the story remembered as more than a technical one?', '["An outsider beat the scientific establishment","The Board of Longitude accepted it immediately","The prize board plainly favoured the rival method","Harrison struggled for many years to be paid"]'::jsonb, '{0,2,3}'::smallint[], 'A Yorkshire carpenter solved a problem the astronomers had claimed, and then had to fight the people judging him. Payment came only after royal intervention, decades later.', 4::smallint),
  ('the-battle-of-cannae', 'What made Cannae a famous victory?', '["The Roman force was surrounded and annihilated","Hannibal had superior numbers on the day","Hannibal attacked at night without warning","A smaller army destroyed a much larger one"]'::jsonb, '{0,3}'::smallint[], 'An outnumbered army surrounded and annihilated a much larger one by letting its centre give way while the flanks held. The battle was fought in daylight in open ground.', 0::smallint),
  ('the-battle-of-cannae', 'Why was being surrounded so catastrophic?', '["The Romans had no commander on the field","The Romans ran out of arrows and javelins","Packed soldiers could not use their weapons","Their numerical superiority proved decisive"]'::jsonb, '{2}'::smallint[], 'Compression turned the larger army into a crowd in which most men could neither fight nor flee. Their numbers became a liability rather than an advantage, which is the whole point of the encirclement.', 1::smallint),
  ('the-battle-of-cannae', 'What role did the cavalry play?', '["It closed the trap that the infantry had opened","It broke the Roman centre by charging head-on","It defeated the Roman horse on the wings first","It then attacked the Roman infantry from behind"]'::jsonb, '{0,2,3}'::smallint[], 'Winning the flanks and returning to the rear is what converted an encirclement into a massacre. A frontal charge against formed infantry was precisely what they avoided.', 2::smallint),
  ('the-battle-of-cannae', 'What happened after the battle?', '["Rome refused to negotiate at any price","Rome immediately sought another pitched battle","Hannibal did not march on Rome itself","Rome surrendered before the year was out"]'::jsonb, '{0,2}'::smallint[], 'Despite losing tens of thousands of men, Rome refused to negotiate and Hannibal never marched on the city. The strategy that followed was attrition and the avoidance of pitched battles.', 3::smallint),
  ('the-battle-of-cannae', 'Why is Cannae still taught in military academies?', '["It is the classic model of a frontal assault","It turns an enemy''s own numbers into a liability","It proves that the bigger army wins the battle","It proves a perfect battle wins the whole war"]'::jsonb, '{1}'::smallint[], 'Cannae is studied as the model of turning an enemy''s numbers against them through double envelopment. Hannibal won the battle almost perfectly and still lost the war, which is the other lesson.', 4::smallint),
  ('the-berlin-conference', 'What happened at the Berlin Conference of 1884 to 1885?', '["Existing colonial borders were simply confirmed","A few African rulers attended it as observers","Africa was formally divided among the powers there","European powers agreed rules for claiming territory"]'::jsonb, '{3}'::smallint[], 'The conference agreed principles such as effective occupation for making claims, rather than drawing a complete partition. No African representatives were present in any capacity.', 0::smallint),
  ('the-berlin-conference', 'Why are so many African borders straight lines?', '["They follow lines of latitude and longitude","They were drawn on maps of poorly known interiors","They were negotiated between European capitals","They follow existing rivers and mountain ranges here"]'::jsonb, '{0,1,2}'::smallint[], 'Boundaries were agreed in Europe using meridians and parallels over territory the negotiators had rarely seen. Where borders do follow rivers, that is the exception rather than the rule.', 1::smallint),
  ('the-berlin-conference', 'What were the consequences of those borders?', '["Groups were carefully kept within single states","Each new state was given access to the sea","Borders that were redrawn at independence","Ethnic and linguistic groups split between states"]'::jsonb, '{3}'::smallint[], 'Boundaries agreed in European capitals split ethnic and linguistic groups between states and forced rivals together. Several countries were left landlocked by exactly the same process.', 2::smallint),
  ('the-berlin-conference', 'What was the effective occupation principle?', '["It protected African states from annexation","A power had to demonstrate control to keep a claim","It required approval from other European powers","It accelerated the physical scramble for territory"]'::jsonb, '{1,3}'::smallint[], 'Requiring a power to demonstrate control turned a paper race into a rush of expeditions, forts and imposed treaties. Its effect was to speed up conquest rather than restrain it.', 3::smallint),
  ('the-berlin-conference', 'What is often overstated about the conference?', '["That it set procedural rules for an ongoing process","That colonisation began with the conference","That fourteen delegations attended, the US included","That the map of Africa was drawn there in one go"]'::jsonb, '{1,3}'::smallint[], 'The conference regulated a scramble that was already under way and continued for decades afterwards. The delegation count and the procedural character are accurate.', 4::smallint),
  ('witch-hunts-were-early-modern', 'When did European witch trials peak?', '["Roughly between 1560 and 1630 in Europe","In the century after the French Revolution","During the very height of the Middle Ages","In the twelfth and thirteenth centuries"]'::jsonb, '{0}'::smallint[], 'The great persecutions peaked roughly between 1560 and 1630, in the age of the Reformation and the scientific revolution. Placing them in the Middle Ages is one of the most common chronological errors in popular history.', 0::smallint),
  ('witch-hunts-were-early-modern', 'What was the medieval church''s typical position on witchcraft?', '["Prosecution was mostly secular in the peak period","Belief in night-flying witches counted as superstition","Church texts denied that such flights really happened","The church organised the largest trials itself"]'::jsonb, '{0,1,2}'::smallint[], 'Earlier canon law treated belief in witches'' flights as a delusion to be corrected, and the later trials were largely run by secular courts. The image of a medieval church burning witches is close to the reverse of the record.', 1::smallint),
  ('witch-hunts-were-early-modern', 'What conditions fed the persecutions?', '["Religious conflict after the Reformation","A centralised international inquisition","Unusually warm and prosperous decades","A papal ban on witchcraft accusations"]'::jsonb, '{0}'::smallint[], 'Confessional conflict after the Reformation was a major driver, alongside climatic stress and printed manuals spreading the stereotype. Hardship, not prosperity, fed the trials.', 2::smallint),
  ('witch-hunts-were-early-modern', 'What is known about the numbers?', '["Around three quarters of the victims were women","Most accusations came from within local communities","Several million people were killed across Europe","Estimates of executions cluster near 40,000-60,000"]'::jsonb, '{0,1,3}'::smallint[], 'The figure of millions comes from nineteenth-century polemic and has no documentary basis. Accusations typically arose from neighbours in village disputes rather than from distant authorities.', 3::smallint),
  ('witch-hunts-were-early-modern', 'Where were trials comparatively rare?', '["Regions with strong central judicial control","Spain and Italy, where the Inquisition was sceptical","Germany, which was the worst-affected region","Areas that lacked a written legal code entirely"]'::jsonb, '{0,1}'::smallint[], 'Trials stayed rare where trained courts reviewed cases and limited torture, which is why the Spanish Inquisition executed remarkably few witches. Fragmented Germany, with the weakest central review, saw the highest death tolls.', 4::smallint),
  ('the-terracotta-army', 'How was the Terracotta Army found?', '["During construction of a railway line","By farmers digging a well there in 1974","By satellite imaging of the whole site","Through a planned archaeological excavation"]'::jsonb, '{1}'::smallint[], 'Local farmers digging a well near Xi''an in 1974 hit fragments, and archaeologists followed. Nobody was looking for it, though the emperor''s tomb mound had been known for centuries.', 0::smallint),
  ('the-terracotta-army', 'What is true of the figures?', '["Each was sculpted entirely by hand from scratch","They were made from a limited set of moulded parts","Faces show extensive individual variation","There are roughly 8,000 warriors in total"]'::jsonb, '{1,2,3}'::smallint[], 'Heads, torsos and limbs came from moulds and were then combined and finished individually, producing variety from standard components. It is early mass production, not eight thousand unique sculptures.', 1::smallint),
  ('the-terracotta-army', 'What did the figures originally look like?', '["They were the same grey colour we see today","They carried wooden replicas of real weapons","They were once painted in bright colours","The pigment survives well once exposed to air"]'::jsonb, '{2}'::smallint[], 'The army was originally brightly painted, and the lacquer layer beneath the paint curls within minutes of excavation, which is why so much colour was lost. The weapons were functional bronze, some still sharp.', 2::smallint),
  ('the-terracotta-army', 'What was the purpose of the army?', '["To replace human sacrifice with clay figures","To accompany and protect the emperor after death","Part of an enormous underground tomb complex","A monument built for the living to come and visit"]'::jsonb, '{0,1,2}'::smallint[], 'The figures were buried to serve the emperor in the afterlife, in a complex covering many square kilometres. They were never meant to be seen by anyone.', 3::smallint),
  ('the-terracotta-army', 'Why has the emperor''s actual tomb not been excavated?', '["Its exact location is still not known today","Concerns that digging would destroy fragile contents","Ancient accounts describe rivers of mercury inside","Chinese law forbids excavating any imperial tomb"]'::jsonb, '{1,2}'::smallint[], 'The mound''s location is well known, but archaeologists judge preservation technology inadequate, and ancient accounts of rivers of mercury are supported by unusually high mercury readings in the soil. Waiting is a deliberate choice, not a legal bar.', 4::smallint),
  ('the-black-death', 'What is disputed about how the Black Death spread?', '["Whether the pandemic reached western Europe","The speed of spread fits rat populations poorly","Whether human parasites or people spread it mostly","Whether rat fleas were the main transmission route"]'::jsonb, '{2,3}'::smallint[], 'Modelling and the sheer speed of spread have led some researchers to favour human fleas, lice or person-to-person transmission over rat fleas. That the disease reached western Europe is not in any doubt.', 0::smallint),
  ('the-black-death', 'How severe was the fourteenth-century pandemic?', '["It was confined to the continent of Europe","Perhaps a third to half of Europe''s population died","Mortality was almost identical everywhere","It originated somewhere in western Europe"]'::jsonb, '{1}'::smallint[], 'Perhaps a third to half of Europe''s population died, with enormous variation between places. It arrived from Central Asia and swept across Asia, the Middle East and North Africa as well.', 1::smallint),
  ('the-black-death', 'What were the longer-term consequences in Europe?', '["Serfdom weakened in parts of western Europe","Labour became scarce and wages rose sharply","Population recovered within a single decade","Landholding patterns changed across Europe"]'::jsonb, '{0,1,3}'::smallint[], 'A shortage of workers strengthened the bargaining position of those who survived, with lasting social effects. Population took well over a century to recover.', 2::smallint),
  ('the-black-death', 'What confirmed the identity of the pathogen?', '["Comparison with modern plague outbreaks","Surviving samples preserved in laboratories","Descriptions of symptoms in chronicles","DNA recovered from teeth in plague burials"]'::jsonb, '{3}'::smallint[], 'Ancient DNA recovered from teeth in plague burial pits identified Yersinia pestis and settled an argument that written symptom descriptions could not. No physical samples survived from the period to compare.', 3::smallint),
  ('the-black-death', 'What did contemporaries believe caused it?', '["Unfavourable alignments of the planets","Fleas carried by rats and other rodents","Corrupted air, which they called miasma","Divine punishment for the sins of people"]'::jsonb, '{0,2,3}'::smallint[], 'Bad air, astrology and divine anger were the standard explanations, and they shaped responses such as aromatic remedies and flight from cities. The role of fleas and rodents was not identified until the 1890s.', 4::smallint),
  ('the-zimmermann-telegram', 'What did the Zimmermann telegram propose?', '["German troops to be stationed inside Mexico","An immediate German attack on the United States","A negotiated peace settlement with Britain","An alliance with Mexico if the US entered the war"]'::jsonb, '{3}'::smallint[], 'Germany proposed an alliance in which Mexico would open a second front if the United States entered the war, in exchange for support in reclaiming lost territory. No German troops were offered.', 0::smallint),
  ('the-zimmermann-telegram', 'How did the British handle the intercepted message?', '["They invented a cover story about a copy in Mexico","They delayed release to disguise how they got it","They passed it to the Americans straight away","They decrypted it in the codebreaking unit Room 40"]'::jsonb, '{0,1,3}'::smallint[], 'Revealing the telegram risked exposing that Britain was reading both German and American diplomatic traffic. A fabricated route of acquisition protected the source.', 1::smallint),
  ('the-zimmermann-telegram', 'Why did the telegram have such an impact in the United States?', '["It was the sole cause of the American war entry","Germany publicly denied the message was genuine","It arrived during a lull in submarine attacks","It suggested a direct threat to American territory"]'::jsonb, '{3}'::smallint[], 'The suggestion of a direct territorial threat to American states is what moved public opinion. Zimmermann confirmed the telegram was authentic, and it landed alongside resumed unrestricted submarine warfare.', 2::smallint),
  ('the-zimmermann-telegram', 'How did Mexico respond?', '["A military assessment judged it unworkable","It doubted Germany could deliver on its promises","Mexico declined the German proposal outright","It began mobilising troops against the United States"]'::jsonb, '{0,1,2}'::smallint[], 'Mexican officials concluded they could neither win such a war nor govern the territory, and doubted German support would materialise. The offer was never close to being accepted.', 3::smallint),
  ('the-zimmermann-telegram', 'What broader lesson does the episode carry?', '["Using intelligence risks revealing its source","Intercepted messages are usually ignored anyway","Public opinion is unaffected by such revelations","Signals intelligence can change the course of a war"]'::jsonb, '{0,3}'::smallint[], 'The telegram is a founding case in signals intelligence changing a war, and in the tension between using intelligence and protecting its source. Britain invented a cover story precisely because the interception mattered so much.', 4::smallint),
  ('the-mercator-projection', 'What was the Mercator projection designed for?', '["Showing the shortest route between two ports","Showing the true relative sizes of countries","Navigation at sea using a compass bearing","Teaching geography in school classrooms"]'::jsonb, '{2}'::smallint[], 'Its single purpose was marine navigation: a course of constant compass bearing appears as a straight line on the chart. The shortest route on a globe is a great circle, which Mercator draws as a curve.', 0::smallint),
  ('the-mercator-projection', 'How does the projection distort the world?', '["Greenland looks comparable in size to Africa","Areas near the poles are enormously inflated","Shapes are preserved locally on the map","Distances near the equator are exaggerated"]'::jsonb, '{0,1,2}'::smallint[], 'Stretching grows with latitude, so polar regions balloon while shapes stay locally correct, which is why it looks plausible. Africa is about fourteen times the area of Greenland.', 1::smallint),
  ('the-mercator-projection', 'Why can no flat map be free of distortion?', '["Very large maps can be made fully accurate","A sphere cannot be flattened without stretching","A projection can preserve both area and angles","Printing limits how accurate a map can be"]'::jsonb, '{1}'::smallint[], 'A sphere cannot be flattened without stretching or tearing, so every projection sacrifices something. No flat map can preserve both area and angle, and the size of the paper is irrelevant.', 2::smallint),
  ('the-mercator-projection', 'What alternatives exist?', '["Compromise projections such as the Robinson","The Mercator, which many web maps still use","Equal-area projections such as Gall-Peters","A projection with no distortion of any kind"]'::jsonb, '{0,1,2}'::smallint[], 'Each alternative trades distortion differently, and web mapping still uses a Mercator variant because it preserves local shape when you zoom. A distortion-free flat map does not exist.', 3::smallint),
  ('the-mercator-projection', 'What is the criticism of using Mercator as a world map?', '["It shrinks Africa and South America by comparison","It was designed as deliberate political propaganda","It was banned from schools in several countries","It visually enlarges Europe and North America"]'::jsonb, '{0,3}'::smallint[], 'The distortion inflates high-latitude regions such as Europe and North America while shrinking Africa and South America, which shapes how people picture the world. Mercator was solving a navigation problem in 1569, not making a political argument.', 4::smallint),
  ('why-the-keyboard-is-laid-out-that-way', 'What is the usual story told about the QWERTY layout?', '["It separated letter pairs to stop typebars jamming","It arranged the letters alphabetically at first","It was designed to speed up experienced typists","It was chosen by a committee of expert typists"]'::jsonb, '{0}'::smallint[], 'The standard account is that common letter pairs were separated so the typebars would jam less often. The extra claim that the layout was meant to slow typists down has no supporting evidence and is the part historians reject outright.', 0::smallint),
  ('why-the-keyboard-is-laid-out-that-way', 'What alternative explanations have historians proposed?', '["The layout suited telegraph operators taking Morse","It can be traced to minimising finger travel","It grouped letters often confused in transcription","It emerged through revisions with early customers"]'::jsonb, '{0,2,3}'::smallint[], 'Research on the machine''s development points to telegraphy and iterative feedback rather than a single design principle. Minimising finger travel is what later layouts aimed at, and QWERTY does it badly.', 1::smallint),
  ('why-the-keyboard-is-laid-out-that-way', 'What happened with the Dvorak layout?', '["Independent trials confirmed it is much faster","It replaced QWERTY on most typewriters by 1950","It was adopted as a US government standard","It was designed for efficiency and for comfort"]'::jsonb, '{3}'::smallint[], 'Dvorak was genuinely designed around letter frequency for efficiency and comfort. It never displaced QWERTY, and the famous speed advantages trace back to studies run by Dvorak himself.', 2::smallint),
  ('why-the-keyboard-is-laid-out-that-way', 'Why is QWERTY used as an economics example?', '["The example itself is contested by some economists","As the classic case of economic path dependence","An early choice locking in through switching costs","As proof that markets pick the better technology"]'::jsonb, '{0,1,2}'::smallint[], 'It became the standard illustration of an inferior standard persisting, then the standard counterexample when others argued QWERTY is not clearly inferior. The dispute is part of what makes it interesting.', 3::smallint),
  ('why-the-keyboard-is-laid-out-that-way', 'What keeps QWERTY in place today, with no typebars left?', '["Retraining costs fall on users, not manufacturers","It is measurably the fastest layout available","Manufacturers are legally required to use it","Everyone already knows this particular layout"]'::jsonb, '{0,3}'::smallint[], 'The layout survives purely on installed knowledge: everyone already knows it, and the cost of retraining falls on individuals rather than on the companies making keyboards. Nothing requires it, and touchscreens have no mechanical constraint at all.', 4::smallint),
  ('the-streisand-effect', 'What is the Streisand effect?', '["Attempts to suppress information spread it further","Content that goes viral for no obvious reason","Celebrities attracting far more coverage than others","Celebrities dominating the online discussion"]'::jsonb, '{0}'::smallint[], 'The effect is specifically about an attempt at suppression backfiring and spreading the material further. Ordinary celebrity attention has nothing to do with it.', 0::smallint),
  ('the-streisand-effect', 'What was the original incident?', '["A lawsuit over an aerial photograph of a house","The photo had been downloaded a handful of times","A record label suing over some leaked music","It was viewed hundreds of thousands of times after"]'::jsonb, '{0,1,3}'::smallint[], 'The image was part of a coastal erosion survey and almost nobody had seen it until the case made news. The lawsuit turned an ignored photograph into a famous one.', 1::smallint),
  ('the-streisand-effect', 'Why does suppression backfire so reliably online?', '["The attempt at suppression is itself newsworthy","Search engines automatically boost banned content","Platforms are paid to keep the content online","Courts publish the material as part of the record"]'::jsonb, '{0}'::smallint[], 'The suppression attempt is itself a story, and that story reaches far more people than the original material ever did. Copies also spread faster than any legal process can move, but no platform is paid to host them.', 2::smallint),
  ('the-streisand-effect', 'When does suppression actually work?', '["When enforcement reaches across the platforms","When no one has reason to publicise the request","When it happens quietly and early enough","When the material is already very widely known"]'::jsonb, '{1,2}'::smallint[], 'Quiet removal before anyone notices is the only version that reliably succeeds, which is why lawyers now weigh publicity risk explicitly. Once the material is widespread, removal is hopeless.', 3::smallint),
  ('the-streisand-effect', 'What should someone consider before demanding a takedown?', '["Whether the request is legally justified","Whether the content is flattering or not","Whether the request itself will attract coverage","How many people have already seen it so far"]'::jsonb, '{2,3}'::smallint[], 'The practical calculation is about reach and attention: how many people have already seen it, and whether the request will itself become news. A completely justified request can still be the thing that makes the content famous.', 4::smallint),
  ('the-y2k-bug', 'What was the Y2K problem?', '["A hidden virus set to activate at midnight","Years stored as two digits could roll over to 1900","Clocks would stop working entirely at midnight","Computers would physically shut down in 2000"]'::jsonb, '{1}'::smallint[], 'Storage was expensive for decades, so years were kept as two digits, making 2000 indistinguishable from 1900 in comparisons and arithmetic. Nothing was going to stop; the risk was wrong answers, not dead hardware.', 0::smallint),
  ('the-y2k-bug', 'Why did so little go wrong on the night?', '["Years of remediation work had preceded it","Critical systems were audited and patched early","The problem had been exaggerated from the start","Hundreds of billions were spent worldwide on fixes"]'::jsonb, '{0,1,3}'::smallint[], 'A quiet night was the product of an enormous, largely invisible engineering effort. Concluding from the calm that the risk was imaginary inverts the causation.', 1::smallint),
  ('the-y2k-bug', 'What evidence suggests the risk was real?', '["Regulators found no faults during testing","Systems that were not fixed did fail","No errors were reported after the date","Entire national power grids collapsed"]'::jsonb, '{1}'::smallint[], 'Systems that were not remediated did produce genuine faults, which is the direct evidence that the risk was real. Testing beforehand and error reports afterwards both turned up plenty.', 2::smallint),
  ('the-y2k-bug', 'What is the general problem this illustrates?', '["Preventive work is hard to justify afterwards","Successful prevention looks like nothing happening","Absence of disaster reads as proof of overreaction","Warnings of this kind are usually exaggerated"]'::jsonb, '{0,1,2}'::smallint[], 'Prevention destroys its own evidence, which makes funding it politically difficult in every domain from public health to security. The pattern applies whether or not any particular warning was overstated.', 3::smallint),
  ('the-y2k-bug', 'Which similar date problems exist?', '["The leap second, causing outages in some systems","GPS week number rollovers in 1999 and 2019","The 2038 problem in 32-bit Unix timestamps","The year 2000, which was not a leap year"]'::jsonb, '{0,1,2}'::smallint[], 'Fixed-width counters and calendar edge cases keep producing the same class of bug: 32-bit time runs out in 2038, GPS week numbers have rolled over twice, and leap seconds have crashed real services. The year 2000 was a leap year, and code that assumed otherwise caused its own small crop of failures.', 4::smallint),
  ('moores-law', 'What did Moore''s law originally state?', '["Chip prices halve at the same regular interval","Transistors on a chip double at a regular interval","It was derived from the physics of the semiconductor","Computer speed doubles each eighteen months"]'::jsonb, '{1}'::smallint[], 'Moore described transistor counts doubling at a regular interval, not speed or price. It was an extrapolation from a handful of data points, and nothing in physics requires it to continue.', 0::smallint),
  ('moores-law', 'In what sense did the law become self-fulfilling?', '["Physics itself forced the doubling to occur","Competitors had to match the pace to survive","The industry used it as a planning target","Roadmaps were built around the expected doubling"]'::jsonb, '{1,2,3}'::smallint[], 'Once the whole supply chain coordinated around the schedule, meeting it became a commercial requirement rather than a discovery. That is the interesting part: an observation turned into an industrial deadline.', 1::smallint),
  ('moores-law', 'What has changed in recent years?', '["Transistor counts have stopped rising entirely","Transistor scaling has slowed considerably","Performance gains now come mainly from clock speed","Node names now measure gate length exactly"]'::jsonb, '{1}'::smallint[], 'Density still rises but far more slowly and expensively than the original doubling. Clock speeds stopped climbing around 2005, and names like 3nm no longer describe any measured feature.', 2::smallint),
  ('moores-law', 'What limits further shrinking?', '["Features approaching the size of a few atoms","Heat density becoming quite unmanageable","A worldwide shortage of raw silicon","Quantum tunnelling causing current leakage"]'::jsonb, '{0,1,3}'::smallint[], 'At current dimensions, electrons leak through barriers and waste heat concentrates faster than it can be removed. Silicon is one of the most abundant elements on Earth.', 3::smallint),
  ('moores-law', 'What is Dennard scaling and why does it matter?', '["It is simply another name for Moore''s law","Power density stayed constant as chips shrank","It broke down around 2005 or thereabouts","Its end is why transistor counts stopped rising"]'::jsonb, '{1,2}'::smallint[], 'Dennard scaling meant smaller transistors also drew proportionally less power, so clock speeds could rise for free until it broke down around 2005. Transistor counts kept climbing; it was clock speed that stalled, which is why processors gained cores instead.', 4::smallint),
  ('gps-needs-relativity', 'Why does GPS have to account for relativity?', '["Relativity affects the radio signal''s own speed","Satellite clocks tick at a different rate to ours","A microsecond of clock error hardly matters","Position is computed from the signal strength"]'::jsonb, '{1}'::smallint[], 'Satellite clocks genuinely tick at a different rate from ground clocks, and the receiver turns tiny time differences into distances. A microsecond of error is about 300 metres, which is the opposite of negligible.', 0::smallint),
  ('gps-needs-relativity', 'Which two relativistic effects act on the satellites?', '["The two effects cancel each other exactly","Their speed slows their clocks slightly","Weaker gravity at altitude speeds their clocks up","The gravitational effect is the larger of the two"]'::jsonb, '{1,2,3}'::smallint[], 'Special relativity slows them by about 7 microseconds a day and general relativity speeds them by about 45, leaving a net gain. Far from cancelling, they leave a substantial correction.', 1::smallint),
  ('gps-needs-relativity', 'What would happen without the correction?', '["Position errors would grow by kilometres per day","Errors would appear and then correct themselves","The whole system would fail almost immediately","Altitude readings would drift, but not position"]'::jsonb, '{0}'::smallint[], 'The drift compounds continuously, so an uncorrected system would degrade by kilometres a day rather than failing at once or self-correcting. Every coordinate is affected, since they all come from the same timing solution.', 2::smallint),
  ('gps-needs-relativity', 'How is the correction implemented?', '["Ground stations continually adjust the broadcast data","Each receiver computes the relativistic terms itself","Satellite clocks are set to run slow before launch","The receiver corrects for its own motion and altitude"]'::jsonb, '{0,2}'::smallint[], 'The oscillators are offset before launch so they tick at the right rate once in orbit, with ground stations refining the corrections. Receivers apply small residual terms but do not carry the main correction.', 3::smallint),
  ('gps-needs-relativity', 'Why is GPS a good argument for relativity being practical?', '["The corrections have been verified in operation","It was the first experimental test of relativity","It is a working system that relies on the theory","It was built specifically to test relativity"]'::jsonb, '{0,2}'::smallint[], 'Relativity here is a design parameter in hardware billions of people carry, and the corrections are verified continuously in operation. Relativity had been tested for decades before GPS existed.', 4::smallint),
  ('incognito-mode-does-not-make-you-anonymous', 'What does private browsing mode actually do?', '["Encrypts your web traffic on the way out","Hides your activity from the websites you visit","Blocks trackers and advertising automatically","Deletes local history and cookies on closing"]'::jsonb, '{3}'::smallint[], 'It is local housekeeping: history, cookies and form data are discarded when the window closes. It blocks nothing on the network, and it does not stop tracking while the session is running.', 0::smallint),
  ('incognito-mode-does-not-make-you-anonymous', 'Who can still see what you are doing?', '["Your internet service provider at home","Nobody, that is the point of the mode","The websites you visit while browsing","Your employer on the company network"]'::jsonb, '{0,2,3}'::smallint[], 'Every party in the path still sees the same traffic, and sites still receive your address and can identify you if you log in. The mode changes only what stays on your own machine.', 1::smallint),
  ('incognito-mode-does-not-make-you-anonymous', 'How can you be tracked even without cookies?', '["Private mode blocks the tracking methods","By your IP address, which stays the same","By cookies stored before the session began","By the browser''s private-mode identifier"]'::jsonb, '{1}'::smallint[], 'Your IP address identifies your connection whatever the browser is doing with cookies. Private mode starts with a clean cookie jar and there is no special identifier attached to it.', 2::smallint),
  ('incognito-mode-does-not-make-you-anonymous', 'What would actually improve anonymity?', '["Using private mode consistently everywhere","A VPN, which shifts trust rather than removing it","Avoiding any logins linked to your identity","Using the Tor network for stronger anonymity"]'::jsonb, '{1,2,3}'::smallint[], 'Real anonymity requires hiding your network location and not identifying yourself, and even then a VPN only moves who can see you. Private mode contributes nothing to any of this.', 3::smallint),
  ('incognito-mode-does-not-make-you-anonymous', 'Why does the misunderstanding persist?', '["The names suggest more privacy than is delivered","Browsers deliberately mislead users about it","Browsers refuse to explain what the mode does","The mode''s own disclaimer is easy to skip"]'::jsonb, '{0,3}'::smallint[], 'Words like incognito and private oversell a narrow feature, and the disclaimer on the new-tab page is easy to skip past. Browsers do state the limits, in text most people never read.', 4::smallint),
  ('the-turing-test', 'What does the Turing test actually assess?', '["Whether a machine is conscious of anything","Whether a machine understands what it is saying","Whether a machine can pass as human in conversation","How much a machine can know about the world"]'::jsonb, '{2}'::smallint[], 'The test measures whether a machine can be told apart from a human in conversation, which is a claim about performance alone. Knowledge, understanding and consciousness are all things it deliberately declines to address.', 0::smallint),
  ('the-turing-test', 'How did Turing frame the question originally?', '["He swapped the thinking question for a real test","He thought the original question too ill-defined","He called the procedure the imitation game","He predicted machines would be conscious by 2000"]'::jsonb, '{0,1,2}'::smallint[], 'His move was to sidestep an unanswerable definitional question with a concrete procedure. His predictions concerned deception rates in a five-minute test, not consciousness.', 1::smallint),
  ('the-turing-test', 'What is the Chinese Room argument meant to show?', '["A system that passes must therefore understand","Machines are unable to process any language","Handling symbols correctly is not understanding","The test measures inner mental states directly"]'::jsonb, '{2}'::smallint[], 'Searle''s argument is that manipulating symbols by rule is not the same as understanding them. It attacks precisely the inference from outward behaviour to inner comprehension.', 2::smallint),
  ('the-turing-test', 'Why do critics say the test is a poor benchmark?', '["It rewards deception and evasion rather than skill","Simple tricks have fooled judges ever since ELIZA","No system has ever come anywhere near passing","It says nothing about capability outside conversation"]'::jsonb, '{0,1,3}'::smallint[], 'Strategies like feigning a child or a non-native speaker score well without demonstrating anything, and conversation is a narrow slice of intelligence. Systems have fooled judges under various conditions for decades.', 3::smallint),
  ('the-turing-test', 'What did the ELIZA experience reveal?', '["It genuinely understood the conversations it had","A simple pattern-matching script convinced users","It was the first program to pass the Turing test","People attribute understanding on little evidence"]'::jsonb, '{1,3}'::smallint[], 'A simple pattern-matching script produced real emotional engagement, showing how little evidence people need before attributing understanding. ELIZA never passed any formal test; Weizenbaum''s point was how easily people were convinced anyway.', 4::smallint),
  ('why-progress-bars-lie', 'Why are progress bars so often inaccurate?', '["Operating systems limit how often the bar updates","Developers deliberately misreport progress","The remaining work is frequently unknown","Speed varies unpredictably during the operation"]'::jsonb, '{2,3}'::smallint[], 'A bar has to estimate a total that often is not known until the work is finished, and the speed of the work varies unpredictably. It is an estimation problem rather than dishonesty or a display limitation.', 0::smallint),
  ('why-progress-bars-lie', 'Why does a bar often stall at 99 per cent?', '["The bar pauses deliberately to reassure the user","The bar reserves the last percent as a buffer","The program has crashed without saying so","A final slow step was left out of the estimate"]'::jsonb, '{3}'::smallint[], 'Flushing buffers, verifying and finalising are real work that the measured part did not include, so a final slow step arrives unrepresented. The bar was honest about what it counted; it was counting the wrong thing.', 1::smallint),
  ('why-progress-bars-lie', 'What did research find about how people perceive progress bars?', '["Users prefer perfectly linear accuracy most","Perceived duration depends on the pattern, not length","Any progress indicator reduces perceived wait","Bars that accelerate towards the end feel faster"]'::jsonb, '{1,2,3}'::smallint[], 'Studies found that a bar speeding up near the end is judged shorter than a linear one of the same duration, and any feedback beats none. Accuracy turns out to matter less to users than shape.', 2::smallint),
  ('why-progress-bars-lie', 'Why are indeterminate spinners sometimes used instead?', '["They are required by accessibility guidelines","When remaining time genuinely cannot be estimated","They can make waits feel shorter than a bar","They promise nothing that can later be broken"]'::jsonb, '{1,3}'::smallint[], 'A spinner signals activity without committing to a number, which is the honest choice when no estimate is possible. It generally feels worse than a bar, because there is no sense of movement towards an end.', 3::smallint),
  ('why-progress-bars-lie', 'What makes a progress indicator genuinely good?', '["Reaching 100 per cent as quickly as possible","Jumping back when a step has to be retried","Being accurate to the nearest percentage point","Describing the current step in plain words"]'::jsonb, '{3}'::smallint[], 'A text label naming the current step buys far more trust than numerical precision ever does. Going backwards destroys trust immediately, and exact accuracy matters less to users than the overall shape.', 4::smallint),
  ('end-to-end-encryption', 'What does end-to-end encryption protect?', '["Who you talked to, and when you did","The fact that you used the service","Your identity from the service itself","The content of the messages you send"]'::jsonb, '{3}'::smallint[], 'Only the endpoints hold the keys, so the provider carries ciphertext it cannot read. Who talks to whom, when, and that you used the service are all metadata, and generally visible.', 0::smallint),
  ('end-to-end-encryption', 'What is metadata in this context?', '["Who messaged whom in the first place","Message sizes and your IP address","Timing and frequency of the messages","The actual words used in the message"]'::jsonb, '{0,1,2}'::smallint[], 'Metadata is everything about the communication except its content, and it can be extraordinarily revealing on its own. A pattern of calls can tell a story without a single word being read.', 1::smallint),
  ('end-to-end-encryption', 'What can still expose an encrypted conversation?', '["A weak password on the recipient''s email account","A compromised phone at either end of the chat","The provider reading the messages in transit","The provider decrypting messages on its servers"]'::jsonb, '{1}'::smallint[], 'Encryption protects the message, not the devices at either end, so a compromised phone exposes everything on it. If the provider could read messages in transit it would not be end-to-end by definition.', 2::smallint),
  ('end-to-end-encryption', 'Why do apps show safety numbers or key fingerprints?', '["Because encryption alone does not prove identity","To verify you are talking to the right person","To make the underlying encryption stronger","To detect any possible interception attempt"]'::jsonb, '{0,1,3}'::smallint[], 'Encrypting to the wrong key is perfectly secure and completely useless, so identity verification is a separate problem. Comparing fingerprints is what closes that gap; it does not change the cipher.', 3::smallint),
  ('end-to-end-encryption', 'What is the core policy tension around this technology?', '["Encryption can be weakened for specific individuals","Any deliberate access path weakens security for everyone","Lawful access requests versus the design of the system","Providers can decrypt stored messages when legally required"]'::jsonb, '{1,2}'::smallint[], 'The tension is between lawful access requests and a design in which the provider holds no keys, and any deliberate access path weakens security for everyone. A provider cannot hand over what it cannot read, which is exactly what makes the demand impossible to satisfy.', 4::smallint),
  ('why-batteries-age', 'What actually degrades in a lithium-ion battery?', '["Electrode materials crack with repeated expansion","The battery''s voltage rises steadily over time","A layer builds up on the electrode, consuming lithium","The battery slowly leaks its electricity away"]'::jsonb, '{0,2}'::smallint[], 'A film grows on the electrode and permanently consumes lithium, while the electrode material cracks under repeated expansion. Both are irreversible, and capacity falls rather than voltage rising.', 0::smallint),
  ('why-batteries-age', 'What accelerates the ageing?', '["Charging in short bursts through the day","Heat, especially while the battery charges","Keeping the battery near 50 per cent charge","Using the device frequently at moderate charge"]'::jsonb, '{1}'::smallint[], 'Heat accelerates every degradation reaction, which is why fast charging in a hot car is the worst case. Mid-range charge and small top-ups are gentle rather than damaging.', 1::smallint),
  ('why-batteries-age', 'What charging habit is best for longevity?', '["Avoiding leaving it at 100 per cent overnight","Keeping charge roughly between 20 and 80 per cent","Charging slowly whenever there is no hurry","Charging fully and discharging fully to calibrate"]'::jsonb, '{0,1,2}'::smallint[], 'Time spent at high voltage is what costs most, so a mid-range band and slower charging both help. Full cycling was advice for nickel chemistries and actively harms lithium cells.', 2::smallint),
  ('why-batteries-age', 'Why do phones now offer optimised charging?', '["To hold at 80 per cent and finish before you wake","To charge the battery more quickly overall","To reduce the hours spent at maximum voltage","Because deep discharge is the main ageing factor"]'::jsonb, '{0,2}'::smallint[], 'The feature holds at 80 per cent and finishes just before you wake, cutting the hours spent at maximum voltage. Both voltage extremes cause wear, so deep discharge is one factor among several rather than the only one.', 3::smallint),
  ('why-batteries-age', 'What is the memory effect and does it apply?', '["It affected the old nickel-cadmium batteries","It applies to lithium-ion cells just as well","A capacity loss caused by charging too quickly","It is why you should fully discharge a phone"]'::jsonb, '{0}'::smallint[], 'Memory effect belongs to nickel-cadmium batteries, where partial cycling reduced usable capacity. Advice derived from it is actively wrong for lithium cells, which are harmed rather than helped by full discharges.', 4::smallint),
  ('training-versus-inference-in-ai', 'What is the difference between training and inference?', '["Inference runs the finished model on new input","Inference updates the model with what you tell it","Training runs again each time you send a message","Training adjusts the model''s own parameters"]'::jsonb, '{0,3}'::smallint[], 'Training adjusts the model''s parameters once, at enormous cost, and inference is running those fixed parameters on new input. Nothing is retrained when you send a message.', 0::smallint),
  ('training-versus-inference-in-ai', 'What follows from the model''s weights being fixed at inference?', '["It becomes permanently smarter as you correct it","It does not learn from your conversation","Everything you type is added to its weights","A new version needs no additional training"]'::jsonb, '{1}'::smallint[], 'The weights are fixed at inference, so the model does not learn from your conversation. Anything it appears to remember within a chat is text held in the context window, which disappears when the session ends.', 1::smallint),
  ('training-versus-inference-in-ai', 'How do the costs compare?', '["Training costs an enormous amount up front","One request can cost more than the training run","Each single inference is comparatively cheap","Total inference cost can exceed the training cost"]'::jsonb, '{0,2,3}'::smallint[], 'One training run may cost more than everything else, but billions of cheap requests add up to more in aggregate. A single request is a tiny fraction of the training cost.', 2::smallint),
  ('training-versus-inference-in-ai', 'What is fine-tuning?', '["Further training of a model on narrower data","A way to run the model on smaller hardware","The same thing as prompting the model carefully","Much cheaper than training one from scratch"]'::jsonb, '{0,3}'::smallint[], 'Fine-tuning is further training of an existing model on narrower data, far cheaper than starting from scratch. It changes the weights, which is what distinguishes it from prompting; making a model smaller is a different technique entirely.', 3::smallint),
  ('training-versus-inference-in-ai', 'Why does the distinction matter practically?', '["Privacy questions differ between the two phases","Telling a model something does not update it","Inference needs larger clusters than training","It explains why models have a knowledge cutoff"]'::jsonb, '{0,1,3}'::smallint[], 'The split explains why a correction you give does not reach other users, why the two phases raise different privacy questions, and why a model''s knowledge stops at the date its training data ended. Training is the phase that needs the clusters; inference can run on a single machine.', 4::smallint),
  ('why-language-models-hallucinate', 'Why do language models produce confident false statements?', '["They are trained on deliberately false examples","They predict likely text rather than retrieving facts","They are programmed to guess when uncertain","They have no database to check against by default"]'::jsonb, '{1,3}'::smallint[], 'The model predicts likely continuations rather than retrieving facts, and by default has no source to check against. Training data is not deliberately false; the problem is that plausibility and truth are not the same target.', 0::smallint),
  ('why-language-models-hallucinate', 'Where are hallucinations most likely?', '["Simple arithmetic with small numbers","Widely repeated historical facts","Common general knowledge of the world","Specific citations and references"]'::jsonb, '{3}'::smallint[], 'Specific citations and references are the classic failure case, because they are highly specific and sparsely represented in training data. Well-covered general facts are comparatively reliable.', 1::smallint),
  ('why-language-models-hallucinate', 'Why is a confident tone not a signal of accuracy?', '["Training text is mostly written very confidently","Confident answers are checked more carefully","The model has no separate sense of its own certainty","Fluency and correctness come from the same process"]'::jsonb, '{0,2,3}'::smallint[], 'Style is learned from text that rarely hedges, and there is no internal fact-checking step tied to tone. Nothing about a confident phrasing means it was verified.', 2::smallint),
  ('why-language-models-hallucinate', 'What reduces the problem?', '["Retrieving real documents and grounding answers","Instructing the model simply not to hallucinate","Asking the same question as often as you can","Asking the model to cite sources you can check"]'::jsonb, '{0,3}'::smallint[], 'Grounding answers in retrieved documents and demanding checkable citations attack the mechanism directly. Repeating the question just samples the same process again, and telling the model to be accurate gives it no new ability to know.', 3::smallint),
  ('why-language-models-hallucinate', 'Why is the word hallucination itself criticised?', '["It suggests the errors are easy to detect","It exaggerates how often the errors occur","It implies the errors are rare and unusual","The same process makes correct and wrong output"]'::jsonb, '{3}'::smallint[], 'There is no separate broken mode: the same process produces the true sentences and the false ones. That is the objection researchers raise, rather than anything about how often or how visibly the errors occur.', 4::smallint),
  ('the-internet-is-not-a-cloud', 'What is the physical reality behind ''the cloud''?', '["Radio towers relaying data between continents","Satellites carrying most international traffic","Data centres packed with rows of servers","Undersea fibre optic cables on the seabed"]'::jsonb, '{2,3}'::smallint[], 'Almost all intercontinental traffic runs through fibre optic cables on the seabed into physical data centres. Satellites and radio carry a tiny fraction, mostly serving places cables do not reach.', 0::smallint),
  ('the-internet-is-not-a-cloud', 'What is true of submarine cables?', '["They carry almost all international traffic","A cable can be about as thick as a garden hose","They are frequently damaged by anchors and fishing","They are usually laid by naval warships and tenders"]'::jsonb, '{0,1,2}'::smallint[], 'A few hundred cables carry nearly everything, and human activity in shallow water causes most faults. Specialised commercial cable ships lay and repair them.', 1::smallint),
  ('the-internet-is-not-a-cloud', 'What about sharks biting cables?', '["Shark bites on cables have been documented","Sharks are attracted by the light the cables emit","It is the single leading cause of cable faults","The whole story is an invented internet myth"]'::jsonb, '{0}'::smallint[], 'Bite marks on cables have been filmed and documented, so the story has a real basis. It is a minor cause compared with anchors and trawling, and the cables leak no light to attract anything.', 2::smallint),
  ('the-internet-is-not-a-cloud', 'Why does the physical layer matter?', '["Data centres consume large amounts of power","Latency is limited by cable routes and light speed","The cloud sits in no single physical location","Cable cuts have disconnected entire regions"]'::jsonb, '{0,1,3}'::smallint[], 'Geography sets the floor on latency, chokepoints create real fragility, and the resource footprint is substantial. That data is distributed does not make it non-physical.', 3::smallint),
  ('the-internet-is-not-a-cloud', 'Why is the cloud metaphor misleading?', '["It obscures who owns and controls the hardware","It exaggerates how reliable the whole system is","It suggests data is stored up in the atmosphere","It hides how fast the connections really are"]'::jsonb, '{0}'::smallint[], 'Your files sit on identifiable machines in identifiable jurisdictions owned by identifiable companies, and the metaphor hides all of that. Nobody actually believes the data is in the sky; what gets obscured is ownership and control.', 4::smallint),
  ('bluetooth-is-named-after-a-viking-king', 'Where does the name Bluetooth come from?', '["A code name that was never meant to stick","The blue colour of early wireless indicator lights","A king who united the warring Danish tribes","Harald Bluetooth, a tenth-century Danish king"]'::jsonb, '{0,2,3}'::smallint[], 'Harald united Denmark and parts of Norway, which made him a fitting metaphor for uniting communication protocols. The name was a placeholder that outlived the marketing alternatives.', 0::smallint),
  ('bluetooth-is-named-after-a-viking-king', 'What is the Bluetooth logo?', '["A stylised blue radio wave symbol","A rune meaning connection or union","The runes for H and B joined together","A letter B drawn in a Nordic style"]'::jsonb, '{2}'::smallint[], 'The mark is a bind rune combining Hagall and Bjarkan, the runes for H and B, Harald Bluetooth''s initials. It looks abstract enough that almost nobody notices.', 1::smallint),
  ('bluetooth-is-named-after-a-viking-king', 'What was Bluetooth designed to replace?', '["Serial connections such as RS-232","Infrared links needing line of sight","Cables between two nearby devices","Wi-Fi for general internet access"]'::jsonb, '{0,1,2}'::smallint[], 'The goal was short-range cable replacement, superseding infrared links that required devices to face each other. It was never intended as a networking technology for internet access.', 2::smallint),
  ('bluetooth-is-named-after-a-viking-king', 'Why does Bluetooth hop between frequencies?', '["To reduce the power that the radio needs","Because it uses a frequency band reserved for it","To reduce interference from other nearby devices","To increase the maximum range of the link"]'::jsonb, '{2}'::smallint[], 'The 2.4 GHz band is shared with Wi-Fi, microwaves and much else, so hopping rapidly across channels avoids sitting on an occupied one. It is about interference, not power, and the band is anything but reserved.', 3::smallint),
  ('bluetooth-is-named-after-a-viking-king', 'What does the naming story illustrate?', '["The name was chosen after extensive market research","Committees usually reject engineers'' informal names","Technical standards accumulate arbitrary history","Internal code names often become permanent"]'::jsonb, '{2,3}'::smallint[], 'The proposed official names were dropped because the placeholder had already spread among engineers, which is how technical standards accumulate arbitrary history. In this case the committee gave in to the code name rather than rejecting it.', 4::smallint),
  ('the-first-computer-bug', 'What is the story of the first computer bug?', '["The machine was permanently damaged by the moth","A moth was found in a relay of the Harvard Mark II","It was taped into the logbook back in 1947","The word bug was invented on that very day"]'::jsonb, '{1,2}'::smallint[], 'A moth found in a relay of the Harvard Mark II was taped into the logbook in 1947, and the specimen survives. The relay was simply cleaned out; nothing was damaged, and the word bug was already engineering slang.', 0::smallint),
  ('the-first-computer-bug', 'How old is the word bug in engineering?', '["It was coined by Grace Hopper''s own team","It was borrowed from telephone work in 1940","Edison used it for faults back in the 1870s","It first appeared in print during the 1950s"]'::jsonb, '{2}'::smallint[], 'Edison wrote about bugs in his inventions in the 1870s, decades before electronic computers existed. That is exactly what makes the logbook entry a joke rather than a coinage.', 1::smallint),
  ('the-first-computer-bug', 'What is the relationship between Grace Hopper and the story?', '["She popularised the anecdote in later talks","Accounts of who found it are not fully clear","She was linked to the team that found the moth","She personally found and removed the moth"]'::jsonb, '{0,1,2}'::smallint[], 'Hopper told the story for decades and it became attached to her, though the log entry does not name who found the insect. She has plenty of genuine achievements that need no embellishment.', 2::smallint),
  ('the-first-computer-bug', 'What was Grace Hopper actually significant for?', '["Work on some of the first compilers","Designing the first electronic computer","Contributions leading towards COBOL","Inventing the transistor with Bell Labs"]'::jsonb, '{0,2}'::smallint[], 'Hopper''s real legacy is early compiler work and the ideas that led to COBOL, making programs writable in something closer to English. She had nothing to do with transistors or with designing the machines themselves.', 3::smallint),
  ('the-first-computer-bug', 'Why does the moth story spread so easily?', '["It is the documented first use of the word","It is the earliest known use of the word bug","Historians agree it is the origin of the word","There is a photograph of the actual logbook"]'::jsonb, '{3}'::smallint[], 'There is a photograph of the actual logbook with the moth still taped to it, which makes the story unusually vivid. The etymology runs the other way, and historians have pointed that out for decades.', 4::smallint),
  ('why-video-is-compressed', 'Why must video be compressed?', '["Uncompressed HD runs to gigabytes per minute","Compression improves the final image quality","Raw video is far too large to store or stream","Compression is required by streaming standards"]'::jsonb, '{0,2}'::smallint[], 'Raw video runs to gigabytes per minute at HD resolution, far beyond what networks or storage can handle. Standards exist because compression is necessary, not the other way round, and it always costs some quality.', 0::smallint),
  ('why-video-is-compressed', 'What is a keyframe?', '["The point at which a stream can start or seek","A reference point that later frames refer to","A frame encoded as a full standalone image","A frame that can store just changed pixels"]'::jsonb, '{0,1,2}'::smallint[], 'Keyframes stand alone, which is why seeking jumps to them, while the frames in between store differences. Storing only changes is what the other frame types do.', 1::smallint),
  ('why-video-is-compressed', 'How do motion vectors save space?', '["They double the number of frames per second","They describe blocks of pixels moving in the frame","They record how the camera panned and tilted","They increase the frame rate of the whole video"]'::jsonb, '{1}'::smallint[], 'A motion vector says where a block of pixels moved from, so the encoder does not have to send that block again. Nothing about them changes the frame rate.', 2::smallint),
  ('why-video-is-compressed', 'Why do fast or chaotic scenes look blocky?', '["Available bits are spread across more new detail","Confetti and water defeat the motion prediction","The encoder deliberately lowers quality for action","Too much changes between frames to predict well"]'::jsonb, '{0,1,3}'::smallint[], 'Prediction breaks down when nothing carries over from the previous frame, so the same bitrate must describe far more novelty. The encoder is not choosing to degrade the scene; it is running out of budget.', 3::smallint),
  ('why-video-is-compressed', 'What perceptual tricks does compression exploit?', '["Errors in flat areas are the hardest to see","Eyes are more sensitive to brightness than colour","Fine detail is far more noticeable when things move","Viewers cannot detect changes in frame rate"]'::jsonb, '{1}'::smallint[], 'The eye resolves brightness far better than colour detail, so codecs throw away colour resolution first. Detail is less noticeable in motion, and errors hide in busy areas rather than flat ones.', 4::smallint),
  ('public-key-cryptography', 'What problem does public-key cryptography solve?', '["Removing the need for secrets of any kind","Communicating securely while everyone is listening","Agreeing a secret without meeting in advance","Making encryption faster than symmetric methods"]'::jsonb, '{1,2}'::smallint[], 'It lets two strangers agree a secret over a channel everyone is listening to, which is what key distribution had always required a courier for. A private key is still a secret; what changes is that it never has to travel.', 0::smallint),
  ('public-key-cryptography', 'How does the key pair work?', '["Either key can undo what the other one did","The public key can be shared with anybody","The private key can be recomputed if it is lost","Both of the keys must be kept fully secret"]'::jsonb, '{1}'::smallint[], 'Publishing one half of the pair is the entire point, and security rests on the infeasibility of deriving the private key from it. If either key undid the other, or the private key could be recomputed, the scheme would be worthless.', 1::smallint),
  ('public-key-cryptography', 'What else does the same mathematics enable?', '["Certificates underpinning HTTPS on the web","Verifying that software has not been altered","Recovering a private key that has been lost","Digital signatures proving who sent a message"]'::jsonb, '{0,1,3}'::smallint[], 'Signing with the private key and verifying with the public one supports identity and integrity across the whole web. A lost private key is simply gone, which is a feature rather than a gap.', 2::smallint),
  ('public-key-cryptography', 'Why is symmetric encryption still used in practice?', '["Public-key methods exchange a symmetric key","It is far faster for shifting bulk data","TLS uses public-key encryption throughout","It is more secure than public-key cryptography"]'::jsonb, '{0,1}'::smallint[], 'Symmetric encryption is far faster for bulk data, so a public-key handshake establishes a session key and symmetric encryption carries the traffic. TLS switches over precisely because public-key operations are too slow for a whole connection.', 3::smallint),
  ('public-key-cryptography', 'Why does quantum computing worry cryptographers?', '["Data captured today could be decrypted later","No replacement algorithms have been proposed","Encryption would become useless almost overnight","Quantum computers would break symmetric ciphers"]'::jsonb, '{0}'::smallint[], 'Data captured today can be stored and decrypted once a capable machine exists, which is why the threat is present-tense. Symmetric encryption is affected far less, and post-quantum replacements are already being standardised.', 4::smallint),
  ('why-passwords-are-hashed', 'What does hashing a password accomplish?', '["Login works by decrypting the stored value","The password can be recovered if the user forgets it","The stored value cannot be reversed to the password","A breach does not immediately expose the passwords"]'::jsonb, '{2,3}'::smallint[], 'A one-way function means the stored value cannot be reversed, so a stolen database is not a list of credentials. Login works by hashing what you typed and comparing, since there is nothing to decrypt.', 0::smallint),
  ('why-passwords-are-hashed', 'Why is it alarming if a site emails you your password?', '["The site has already been breached by someone","It shows the password was stored recoverably","Email attachments are encrypted in transit","It means the site is using strong encryption"]'::jsonb, '{1}'::smallint[], 'Being able to send your password back means the service can read it, which means an attacker who gets in can too. Recoverable storage is the problem, whether or not a breach has happened yet.', 1::smallint),
  ('why-passwords-are-hashed', 'What is a salt and why is it used?', '["Random data added to each password before hashing","It makes identical passwords hash differently","It defeats precomputed rainbow lookup tables","It must be kept completely secret to work"]'::jsonb, '{0,1,2}'::smallint[], 'A unique salt per user means an attacker must attack each hash separately, which kills rainbow tables. Salts are stored alongside the hash and are not secret.', 2::smallint),
  ('why-passwords-are-hashed', 'Why are fast hash functions a bad choice for passwords?', '["Slow functions can produce longer hashes","Fast hashes produce a much shorter output","Attackers can try billions of guesses per second","Deliberately slow functions are used instead"]'::jsonb, '{2,3}'::smallint[], 'Speed helps the attacker far more than the defender, since offline guessing runs billions of attempts per second. Password hashes such as bcrypt and Argon2 are therefore built to be deliberately slow, not longer.', 3::smallint),
  ('why-passwords-are-hashed', 'What still protects you if a hashed database leaks?', '["Not reusing passwords limits the damage done","Two-factor codes are stored in the same database","Hashing on its own makes cracking impossible","A short but memorable password is the safest"]'::jsonb, '{0}'::smallint[], 'Hashing buys time rather than immunity, so not reusing passwords is what stops one leak becoming many. Short passwords fall quickly to offline guessing, and a second factor lives outside the leaked database.', 4::smallint),
  ('capacitive-touchscreens', 'How does a capacitive touchscreen detect your finger?', '["It measures the warmth of your finger","It detects the moisture on your skin","It detects pressure on the glass","It senses a change in an electric field"]'::jsonb, '{3}'::smallint[], 'A grid holds a small charge and a conductive object nearby changes the capacitance at that point. Your body conducts because of its salt content, but the screen is sensing the field rather than measuring wetness.', 0::smallint),
  ('capacitive-touchscreens', 'Why do ordinary gloves not work?', '["The field cannot reach through them to your skin","Touchscreen gloves contain conductive thread","The screen usually needs pressure from bare skin","Wool and leather are effective insulators"]'::jsonb, '{0,1,3}'::smallint[], 'An insulating layer breaks the electrical path, and special gloves fix this by weaving conductive fibres into the fingertips. Pressure was never part of the mechanism.', 1::smallint),
  ('capacitive-touchscreens', 'How do resistive touchscreens differ?', '["They work by pressure pushing two layers together","They ignore anything except a bare fingertip","They are far more sensitive to a light touch","They support multi-touch better than capacitive"]'::jsonb, '{0}'::smallint[], 'Resistive screens work by pressure pushing two conductive layers together, which is why older devices came with a stylus. They respond to any object at all and handle multi-touch poorly.', 2::smallint),
  ('capacitive-touchscreens', 'Why do wet screens behave erratically?', '["The screen cannot separate water from a finger","Droplets create false contact points on it","Water is conductive and registers as a touch","Water can block the electric field completely"]'::jsonb, '{0,1,2}'::smallint[], 'The sensor detects conductive material and water qualifies, producing phantom touches. It is not blocking anything; it is being detected.', 3::smallint),
  ('capacitive-touchscreens', 'What follows from the way the technology works?', '["A sausage can be used to operate a phone screen","Wearing thicker gloves can improve accuracy","A capacitive stylus needs a conductive tip","A metal stylus works better than any bare finger"]'::jsonb, '{0,2}'::smallint[], 'Anything conductive and connected to a large enough body registers, which is why a sausage works and why a capacitive stylus needs a conductive tip and a wide contact patch. A thin metal point does not present enough area to register reliably.', 4::smallint),
  ('placebo-buttons', 'What is a placebo button?', '["A button that works under certain conditions","A control that is not connected to anything","A button that has broken and not been repaired","A button that reports a fault when pressed"]'::jsonb, '{1}'::smallint[], 'The defining feature is a control that is not connected to anything, while the interface still invites the press. These are deliberate rather than broken, and they do nothing at all when pressed.', 0::smallint),
  ('placebo-buttons', 'Which are commonly cited examples?', '["Pedestrian crossing buttons in major cities","Door-close buttons in most modern lifts","Office thermostats in some large buildings","Emergency stop buttons on public escalators"]'::jsonb, '{0,1,2}'::smallint[], 'Crossing buttons on fixed-timer signals, lift close buttons disabled by accessibility rules and dummy thermostats are the standard examples. Emergency stops are legally required to work.', 1::smallint),
  ('placebo-buttons', 'Why are such buttons kept rather than removed?', '["Pressing them genuinely shortens the wait","The feeling of control reduces frustration","Removing them would be far too expensive","They are required by building regulations"]'::jsonb, '{1}'::smallint[], 'A press that changes nothing still reduces frustration, because the feeling of control shortens how long a wait seems. Some crossing buttons do work outside peak hours, but no regulation requires a disconnected one.', 2::smallint),
  ('placebo-buttons', 'Why were lift door-close buttons disabled?', '["They still function for firefighters with a key","They were causing mechanical damage to doors","Accessibility law required minimum door open times","The buttons were physically removed from lifts"]'::jsonb, '{0,2}'::smallint[], 'Regulations mandated a minimum time for people with limited mobility, so the button was deactivated but left in place. It typically still works in service or emergency modes.', 3::smallint),
  ('placebo-buttons', 'What broader design question does this raise?', '["Whether feeling in control has any real value","Whether interfaces should have fewer buttons overall","Whether interfaces should be simplified further","Whether a false sense of agency is acceptable design"]'::jsonb, '{0,3}'::smallint[], 'The practice trades honesty for comfort, which raises a real question about whether a false sense of agency is acceptable and whether feeling in control has value of its own. How many controls an interface should have is a separate design concern.', 4::smallint),
  ('why-aeroplane-mode-exists', 'What is the actual reason for flight mode?', '["It would crash the aircraft''s flight computers","Phone signals are blocked by the fuselage anyway","It is largely a problem for the ground network","Phones at altitude reach many ground cells at once"]'::jsonb, '{2,3}'::smallint[], 'A phone at cruising altitude sees many ground cells at once and transmits at full power, which burdens the network below. Signals do reach the ground, which is exactly why it is a network problem.', 0::smallint),
  ('why-aeroplane-mode-exists', 'What actually happens if you forget to switch it on?', '["The aircraft''s navigation system fails","Almost certainly nothing noticeable happens","The phone loses its stored contact list","The cabin crew are alerted automatically"]'::jsonb, '{1}'::smallint[], 'Dozens of phones are left on during every flight without incident, so almost certainly nothing noticeable happens. The phone does drain its battery hunting for signal, but nothing alerts anyone and no data is lost.', 1::smallint),
  ('why-aeroplane-mode-exists', 'Why are the rules changing?', '["The evidence showed phones were dangerous","Regulators have reassessed the interference risk","Modern avionics are far better shielded now","In-flight cellular systems now exist on aircraft"]'::jsonb, '{1,2,3}'::smallint[], 'Onboard picocells and updated risk assessments have allowed European regulators to relax the rules. The reassessment went in the direction of less risk, not more.', 2::smallint),
  ('why-aeroplane-mode-exists', 'What does flight mode actually switch off?', '["The cellular radio transmitter in it","GPS reception, which can still work","Wi-Fi and Bluetooth, which can be re-enabled","The phone''s internal clock synchronisation"]'::jsonb, '{0,2}'::smallint[], 'It disables transmitters, principally the cellular radio, and modern phones let you switch Wi-Fi and Bluetooth back on separately. GPS and the clock only receive, so they keep working and transmit nothing.', 3::smallint),
  ('why-aeroplane-mode-exists', 'Why do airlines still enforce the rule?', '["Because phones demonstrably cause crashes","Ground network operators still prefer it","Airlines are fined if a phone is left switched on","Each device is now assessed individually"]'::jsonb, '{1}'::smallint[], 'The ground network reason has not gone away, so operators still prefer phones off at altitude. A blanket rule is simpler than assessing each device, and no crash has ever been traced to a passenger phone.', 4::smallint),
  ('random-versus-pseudorandom', 'Why can a computer not produce true randomness on its own?', '["Its clock speed is fixed and entirely predictable","It is a deterministic machine following instructions","The same starting state produces the same sequence","Its processor is too fast to be unpredictable"]'::jsonb, '{1,2}'::smallint[], 'A pseudorandom generator is an algorithm on a deterministic machine, so the same starting state always produces the same sequence. The output looks random statistically, which is a much weaker property than being unpredictable.', 0::smallint),
  ('random-versus-pseudorandom', 'What is a seed?', '["A fresh seed is generated for each number","It stops the sequence from repeating itself","The starting value used by the generator","A source of genuine physical randomness"]'::jsonb, '{2}'::smallint[], 'The seed is the generator''s starting value, and the same seed reproduces the same sequence exactly. That reproducibility is often the point, letting a simulation or test be replayed.', 1::smallint),
  ('random-versus-pseudorandom', 'Where do computers get genuine unpredictability?', '["Dedicated hardware random number generators","Timing of keystrokes and mouse movement","The system clock reading and nothing besides","Electrical noise in hardware components"]'::jsonb, '{0,1,3}'::smallint[], 'Operating systems pool entropy from physical, hard-to-predict sources and modern chips include noise-based generators. A clock value is guessable, which is why seeding from time alone has broken real systems.', 2::smallint),
  ('random-versus-pseudorandom', 'Why does the distinction matter for security?', '["Statistical randomness can be enough for crypto","Weak seeding is caught by statistical tests","They must resist prediction from earlier output","Predictable keys can be reproduced by an attacker"]'::jsonb, '{2,3}'::smallint[], 'Predictable keys can be reproduced by an attacker, so cryptographic generators must resist prediction even from past output. Statistical tests pass happily on sequences an attacker can predict, which is why weak seeding has caused real breaches.', 3::smallint),
  ('random-versus-pseudorandom', 'Where is pseudorandomness perfectly adequate?', '["Choosing the numbers in a public lottery draw","Procedural generation of game landscapes","Generating an encryption key for a message","Generating a session token after a login"]'::jsonb, '{1}'::smallint[], 'Procedural generation in games is a case where speed and reproducibility matter and no adversary is trying to predict the output. Session tokens, lottery draws and encryption keys all fail badly if anyone can guess the sequence.', 4::smallint),
  ('why-ssds-die-suddenly', 'How does SSD failure differ from hard disk failure?', '["SSDs usually give longer warning than hard drives","SSDs can stop responding without notice","Hard drives often give audible or gradual warning","SSDs fail more quickly than hard drives do"]'::jsonb, '{1,2}'::smallint[], 'A mechanical drive usually degrades audibly or gradually, while an SSD''s controller can simply stop presenting the device. Lifespan comparisons depend on workload, but the warning is the part that differs most.', 0::smallint),
  ('why-ssds-die-suddenly', 'What wears out in flash memory?', '["Cells tolerate a limited number of erase cycles","Reading a cell wears it out as much as writing","Cells lose capacity but stay perfectly reliable","The controller chip itself physically wears out"]'::jsonb, '{0}'::smallint[], 'Flash cells tolerate a limited number of write and erase cycles, because erasing forces charge through an insulating barrier and damages it. Reading is essentially free, and worn cells become unreliable rather than merely smaller.', 1::smallint),
  ('why-ssds-die-suddenly', 'What do wear levelling and over-provisioning do?', '["Make the drive run faster as time goes on","Spread writes evenly across all the cells","Keep spare capacity to replace failed blocks","Prevent one area from being worn out early"]'::jsonb, '{1,2,3}'::smallint[], 'Without wear levelling, frequently rewritten areas would fail long before the rest of the drive. Reserved capacity substitutes for blocks as they retire.', 2::smallint),
  ('why-ssds-die-suddenly', 'Why can data become unreadable after failure?', '["The cells are wiped clean when the drive fails","The cells are physically destroyed by the fault","A failed controller leaves the cells unreadable","The controller maps logical blocks to real cells"]'::jsonb, '{2,3}'::smallint[], 'The controller holds the mapping from logical blocks to scattered physical cells, so losing it leaves the flash intact but unintelligible. Nothing is wiped; the data is simply unreachable, which is why recovery is expensive and often fails.', 3::smallint),
  ('why-ssds-die-suddenly', 'What practical advice follows?', '["Rely on the drive slowing down as a warning","Keep backups, since failure may be abrupt","Defragment the drive regularly to spread the wear","Store an SSD unpowered for years to preserve data"]'::jsonb, '{1}'::smallint[], 'Because failure can be abrupt and silent, backups are the only real defence. Health counters give some warning, but slowdown is not a reliable sign, and defragmenting an SSD adds writes for no benefit.', 4::smallint),
  ('rubber-duck-debugging', 'What is rubber duck debugging?', '["A technique invented by a rubber duck manufacturer","Finding the bug during the explanation itself","Explaining your code line by line to an object","Asking a colleague to review the code for you"]'::jsonb, '{1,2}'::smallint[], 'You explain your code line by line to an object that contributes nothing, and the bug surfaces during the explanation itself. The name comes from an anecdote in The Pragmatic Programmer.', 0::smallint),
  ('rubber-duck-debugging', 'Why does explaining out loud help?', '["The listener spots exactly what you missed","Speech forces sequential, explicit reasoning","Speaking is faster than reading through the code","Hearing your own voice improves concentration"]'::jsonb, '{1}'::smallint[], 'Speech forces sequential, explicit reasoning, so you cannot skim past the step where your assumption diverges from what the code does. No listener is needed, which is exactly the surprising part.', 1::smallint),
  ('rubber-duck-debugging', 'What is the related psychological effect?', '["Articulating knowledge reveals what you do not have","The self-explanation effect in learning research","Teaching material improves your own understanding","Repetition strengthens memory of the material"]'::jsonb, '{0,1,2}'::smallint[], 'Learners who explain material to themselves understand it better, and the same mechanism exposes false assumptions in code. Plain repetition is a different effect.', 2::smallint),
  ('rubber-duck-debugging', 'Where else does the technique apply?', '["Copying the error message into a search engine","Writing out a bug report you never send","Reading through the code for a second time","Drafting a question for an online forum"]'::jsonb, '{1,3}'::smallint[], 'Writing a bug report or a forum question forces you to state the problem fully, which is why so many questions get answered by their authors mid-writing. Rereading lets you skim, which is the habit the technique is designed to break.', 3::smallint),
  ('rubber-duck-debugging', 'What does its effectiveness suggest about debugging?', '["Bugs are usually caused by unfamiliar syntax","Fixing a bug is usually harder than locating it","Most bugs come from mistyped lines of code","The difficulty lies in locating, not in fixing"]'::jsonb, '{3}'::smallint[], 'The difficulty in debugging is almost always finding the problem rather than repairing it, which is why articulating your reasoning helps so much. Mistyped lines are caught by tools long before they reach you.', 4::smallint),
  ('the-history-of-the-at-sign', 'What was the @ sign used for before email?', '["An accounting shorthand for ''at a rate of''","A symbol marking the end of a sentence","It was invented for use in early computing","A commercial symbol in invoices and ledgers"]'::jsonb, '{0,3}'::smallint[], 'It was a mercantile symbol meaning at a rate of, used in invoices and ledgers, and as the arroba it was also a unit of weight. That commercial history is why it already sat on typewriter keyboards.', 0::smallint),
  ('the-history-of-the-at-sign', 'How did it end up in email addresses?', '["It was a symbol the operating system ignored","It was the newest symbol added to keyboards","Ray Tomlinson chose it for the job in 1971","It already separated network addresses then"]'::jsonb, '{2}'::smallint[], 'Ray Tomlinson picked it in 1971 because it read naturally as at and could not occur inside a username. Nothing had used it for addressing before, which is precisely why it was free.', 1::smallint),
  ('the-history-of-the-at-sign', 'What does the choice illustrate?', '["It can be traced to a standards committee","An obsolete symbol was given a second life","A small technical decision can have enormous reach","The decision was made quickly and without ceremony"]'::jsonb, '{1,2,3}'::smallint[], 'One engineer picked a convenient character and it became a global symbol on billions of devices. No committee was involved, which is part of why the story is told.', 2::smallint),
  ('the-history-of-the-at-sign', 'What are its names in other languages?', '["Monkey tail, apenstaartje in Dutch","Ampersand, the German name for it","One official name is used worldwide","Snail, in both Italian and French"]'::jsonb, '{0,3}'::smallint[], 'Many languages named the symbol after what it looks like: apenstaartje, monkey tail, in Dutch, and chiocciola or escargot, snail, in Italian and French. German calls it Klammeraffe or simply at, and there is no universal name.', 3::smallint),
  ('the-history-of-the-at-sign', 'What other roles has it taken on since?', '["Denoting a national currency in accounts","A decorator syntax in some programming languages","Marking a comment in most programming languages","Separating out the parts of a web address"]'::jsonb, '{1}'::smallint[], 'It became decorator syntax in languages such as Python and Java, a role descended from the idea of attaching something to a name. Comments and URL separators use entirely different characters.', 4::smallint)
) as q(slug, question, options, correct_indexes, explanation, sort_order)
join public.topics t on t.slug = q.slug
where not exists (
  select 1 from public.quiz_questions existing where existing.topic_id = t.id
);
